import sys

TABLE = -1
AIR = -2
BLOCKS = list(range(1, 15))
FRAGILE = 1


def block_name(b):
    return f"block{b}"


def parse_block(s):
    return int(s[5:])


# Initial configuration:
# 12 table, 13 on 12
# 1 table, 5 on 1
# 10 table, 3 on 10
# 11 table, 8 on 11, 14 on 8, 4 on 14, 9 on 4, 6 on 9, 2 on 6, 7 on 2
initial_loc = {
    1: TABLE,
    2: 6,
    3: 10,
    4: 14,
    5: 1,
    6: 9,
    7: 2,
    8: 11,
    9: 4,
    10: TABLE,
    11: TABLE,
    12: TABLE,
    13: 12,
    14: 8,
}

# Goal configuration:
# 4 table, 1 on 4
# 10 table, 12 on 10
# 14 table, 3 table, 7 on 3, 11 on 7
# 8 table, 5 on 8
# 6, 2, 13, 9 table
goal_loc = {
    1: 4,
    2: TABLE,
    3: TABLE,
    4: TABLE,
    5: 8,
    6: TABLE,
    7: 3,
    8: TABLE,
    9: TABLE,
    10: TABLE,
    11: 7,
    12: 10,
    13: TABLE,
    14: TABLE,
}


def goal_is_feasible(goal):
    if set(goal) != set(BLOCKS):
        return False

    # Additional constraint: no block may be placed on the fragile block.
    for b, s in goal.items():
        if s == FRAGILE:
            return False

    for b, s in goal.items():
        if s != TABLE:
            if s not in goal or s == b:
                return False

    child_count = {}
    for b, s in goal.items():
        if s != TABLE:
            child_count[s] = child_count.get(s, 0) + 1
            if child_count[s] > 1:
                return False

    # Cycle check.
    status = {}
    for b in BLOCKS:
        if b in status:
            continue
        cur = b
        path = []
        while cur != TABLE:
            if cur not in goal:
                return False
            if status.get(cur) == 1:
                return False
            if status.get(cur) == 2:
                break
            status[cur] = 1
            path.append(cur)
            cur = goal[cur]
        for x in path:
            status[x] = 2

    return True


def simulate(initial, plan, goal):
    loc = dict(initial)
    holding = None

    for line in plan:
        if not line.startswith("(") or not line.endswith(")"):
            return False

        parts = line[1:-1].split()
        if not parts:
            return False

        action = parts[0]

        if action == "pickup":
            if len(parts) != 2:
                return False
            try:
                b = parse_block(parts[1])
            except Exception:
                return False
            if b not in BLOCKS:
                return False
            if holding is not None:
                return False
            if loc[b] != TABLE:
                return False
            if any(loc[x] == b for x in BLOCKS):
                return False

            loc[b] = AIR
            holding = b

        elif action == "putdown":
            if len(parts) != 2:
                return False
            try:
                b = parse_block(parts[1])
            except Exception:
                return False
            if b not in BLOCKS:
                return False
            if holding != b:
                return False

            loc[b] = TABLE
            holding = None

        elif action == "unstack":
            if len(parts) != 3:
                return False
            try:
                b = parse_block(parts[1])
                s = parse_block(parts[2])
            except Exception:
                return False
            if b not in BLOCKS or s not in BLOCKS:
                return False
            if holding is not None:
                return False
            if loc[b] != s:
                return False
            if any(loc[x] == b for x in BLOCKS):
                return False

            loc[b] = AIR
            holding = b

        elif action == "stack":
            if len(parts) != 3:
                return False
            try:
                b = parse_block(parts[1])
                s = parse_block(parts[2])
            except Exception:
                return False
            if b not in BLOCKS or s not in BLOCKS:
                return False
            if holding != b:
                return False
            if s == FRAGILE:
                return False
            if loc[s] == AIR:
                return False
            if any(loc[x] == s for x in BLOCKS):
                return False

            loc[b] = s
            holding = None

        else:
            return False

    if holding is not None:
        return False

    return loc == goal


def generate_plan(initial, goal):
    if not goal_is_feasible(goal):
        return None

    loc = dict(initial)
    plan = []

    # Dismantle all towers to the table.
    while True:
        on_count = {b: 0 for b in BLOCKS}
        for b, s in loc.items():
            if s != TABLE and s != AIR:
                on_count[s] += 1

        moved = False
        for b in sorted(BLOCKS):
            if loc[b] != TABLE and on_count[b] == 0:
                s = loc[b]
                plan.append(f"(unstack {block_name(b)} {block_name(s)})")
                plan.append(f"(putdown {block_name(b)})")
                loc[b] = TABLE
                moved = True
                break

        if not moved:
            break

    # Build goal towers bottom-up.
    child_map = {}
    for b, s in goal.items():
        if s != TABLE:
            if s == FRAGILE:
                return None
            child_map.setdefault(s, []).append(b)

    for children in child_map.values():
        if len(children) > 1:
            return None

    for base in sorted(BLOCKS):
        if goal[base] == TABLE:
            cur = base
            while cur in child_map:
                b = child_map[cur][0]

                if loc[b] != TABLE:
                    return None
                if any(loc[x] == b for x in BLOCKS):
                    return None
                if any(loc[x] == cur for x in BLOCKS):
                    return None
                if cur == FRAGILE:
                    return None

                plan.append(f"(pickup {block_name(b)})")
                plan.append(f"(stack {block_name(b)} {block_name(cur)})")

                loc[b] = cur
                cur = b

    if loc != goal:
        return None

    if not simulate(initial, plan, goal):
        return None

    return plan


def main():
    plan = generate_plan(initial_loc, goal_loc)
    if plan is None:
        sys.stdout.write("No plan\n")
    else:
        sys.stdout.write("\n".join(plan))
        if plan:
            sys.stdout.write("\n")


if __name__ == "__main__":
    main()

def solve():
    TABLE = "table"
    names = [f"block{i}" for i in range(1, 16)]

    initial = {
        "block4": TABLE,
        "block14": "block4",
        "block8": "block14",
        "block10": TABLE,
        "block1": TABLE,
        "block12": TABLE,
        "block6": TABLE,
        "block7": "block6",
        "block5": "block7",
        "block3": TABLE,
        "block13": "block3",
        "block15": "block13",
        "block9": "block15",
        "block11": TABLE,
        "block2": "block11",
    }

    goal = {
        "block13": TABLE,
        "block2": "block13",
        "block9": TABLE,
        "block1": TABLE,
        "block11": TABLE,
        "block7": TABLE,
        "block12": "block7",
        "block14": TABLE,
        "block5": "block14",
        "block8": "block5",
        "block10": TABLE,
        "block15": TABLE,
        "block4": TABLE,
        "block6": "block4",
        "block3": "block6",
    }

    loc = initial.copy()
    arm = None
    plan = []

    def is_clear(b):
        return all(loc[x] != b for x in loc)

    def do(action, *args):
        nonlocal arm

        if action == "pickup":
            b = args[0]
            if arm is not None or loc[b] != TABLE or not is_clear(b):
                return False
            arm = b
            loc[b] = None

        elif action == "putdown":
            b = args[0]
            if arm != b:
                return False
            arm = None
            loc[b] = TABLE

        elif action == "unstack":
            x, y = args
            if arm is not None or loc[x] != y or not is_clear(x):
                return False
            arm = x
            loc[x] = None

        elif action == "stack":
            x, y = args
            if arm != x or y == x or loc[y] is None or not is_clear(y):
                return False
            arm = None
            loc[x] = y

        else:
            return False

        plan.append((action,) + args)
        return True

    # Clear all blocks down to the table.
    while True:
        candidates = [
            b for b in names
            if loc[b] is not None and loc[b] != TABLE and is_clear(b)
        ]

        if not candidates:
            if any(loc[b] is not None and loc[b] != TABLE for b in names):
                return "No plan"
            break

        b = candidates[0]
        if not do("unstack", b, loc[b]) or not do("putdown", b):
            return "No plan"

    # Build the goal stacks from the table.
    on_top = {}
    for b, s in goal.items():
        if s != TABLE:
            if s in on_top:
                return "No plan"
            on_top[s] = b

    for base in names:
        if goal[base] != TABLE:
            continue

        stack = [base]
        cur = base
        while cur in on_top:
            cur = on_top[cur]
            if cur in stack:
                return "No plan"
            stack.append(cur)

        if loc[base] != TABLE:
            return "No plan"

        for i in range(1, len(stack)):
            b = stack[i]
            support = stack[i - 1]

            if loc[b] == support and is_clear(b):
                continue

            if loc[b] is None:
                return "No plan"

            if loc[b] != TABLE:
                if not is_clear(b):
                    return "No plan"
                if not do("unstack", b, loc[b]) or not do("putdown", b):
                    return "No plan"

            if not do("pickup", b) or not do("stack", b, support):
                return "No plan"

    if arm is not None:
        return "No plan"

    for b in names:
        if loc[b] != goal[b]:
            return "No plan"

    # Additional constraint: if block1 is moved, block4 must be moved after it.
    pending_block4 = False
    for action, *args in plan:
        if args:
            if args[0] == "block1":
                pending_block4 = True
            if args[0] == "block4":
                pending_block4 = False

    if pending_block4:
        return "No plan"

    return "\n".join(f"({a} " + " ".join(args) + ")" for a, args in plan)


if __name__ == "__main__":
    try:
        print(solve())
    except Exception:
        print("No plan")

import heapq


def main():
    # Blocks are numbered 1..14.
    # State: (supports, arm)
    #   supports[i-1] is the block on which block i is placed, or 0 for table.
    #   arm is the block currently held, or 0 if empty.
    #
    # Initial configuration:
    #   table: 4, 13, 8, 14, 2
    #   13 <- 6 <- 1 <- 7
    #   14 <- 5 <- 3 <- 11 <- 9 <- 10 <- 12
    init_supports = [0] * 15
    init_supports[1] = 6
    init_supports[2] = 0
    init_supports[3] = 5
    init_supports[4] = 0
    init_supports[5] = 14
    init_supports[6] = 13
    init_supports[7] = 1
    init_supports[8] = 0
    init_supports[9] = 11
    init_supports[10] = 9
    init_supports[11] = 3
    init_supports[12] = 10
    init_supports[13] = 0
    init_supports[14] = 0

    start = (tuple(init_supports[1:]), 0)

    def heuristic(state):
        supports, arm = state
        h = 0
        for i, s in enumerate(supports, 1):
            if s != 0:
                h += 2
            elif arm == i:
                h += 1
        return h

    def is_goal(state):
        supports, arm = state
        return arm == 0 and all(s == 0 for s in supports)

    def successors(state):
        supports, arm = state

        on = [[] for _ in range(15)]
        for i, s in enumerate(supports, 1):
            if s != 0:
                on[s].append(i)

        if arm == 0:
            for b in range(1, 15):
                if not on[b]:
                    s = supports[b - 1]
                    if s == 0:
                        yield (supports, b), f"(pickup block{b})"
                    else:
                        next_supports = list(supports)
                        next_supports[b - 1] = 0
                        yield (tuple(next_supports), b), f"(unstack block{b} block{s})"
        else:
            yield (supports, 0), f"(putdown block{arm})"

            for b in range(1, 15):
                if b != arm and not on[b]:
                    next_supports = list(supports)
                    next_supports[arm - 1] = b
                    yield (tuple(next_supports), 0), f"(stack block{arm} block{b})"

    h0 = heuristic(start)
    counter = 0
    heap = [(h0, h0, counter, 0, start)]
    best_g = {start: 0}
    parent = {start: None}

    while heap:
        f, h, _, g, state = heapq.heappop(heap)

        if g != best_g.get(state):
            continue

        if is_goal(state):
            actions = []
            cur = state
            while parent[cur] is not None:
                prev, action = parent[cur]
                actions.append(action)
                cur = prev
            actions.reverse()
            if actions:
                print("\n".join(actions))
            return

        ng = g + 1
        for nstate, action in successors(state):
            if ng < best_g.get(nstate, 10**9):
                best_g[nstate] = ng
                parent[nstate] = (state, action)
                nh = heuristic(nstate)
                counter += 1
                heapq.heappush(heap, (ng + nh, nh, counter, ng, nstate))

    print("No plan")


if __name__ == "__main__":
    main()

from collections import deque

def solve():
    blocks = [f"block{i}" for i in range(1, 14)]
    n = len(blocks)
    idx = {b: i for i, b in enumerate(blocks)}

    TABLE = -1
    HELD = -2

    on = [TABLE] * n

    initial_stacks = [
        (idx["block10"], [idx["block7"], idx["block13"], idx["block5"]]),
        (idx["block9"], [idx["block8"], idx["block4"], idx["block12"], idx["block11"], idx["block6"]]),
    ]

    for bottom, tops in initial_stacks:
        prev = bottom
        for b in tops:
            on[b] = prev
            prev = b

    start = tuple(on)

    stack_id = [2] * n
    for sid, (bottom, tops) in enumerate(initial_stacks):
        stack_id[bottom] = sid
        for b in tops:
            stack_id[b] = sid

    def is_goal(state):
        return all(x == TABLE for x in state)

    def is_clear(state, i):
        for j in range(n):
            if state[j] == i:
                return False
        return True

    def held_block(state):
        for i, x in enumerate(state):
            if x == HELD:
                return i
        return -1

    queue = deque([start])
    parent = {start: None}

    while queue:
        state = queue.popleft()

        if is_goal(state):
            actions = []
            cur = state
            while parent[cur] is not None:
                prev, action = parent[cur]
                actions.append(action)
                cur = prev
            actions.reverse()
            print("\n".join(actions))
            return

        h = held_block(state)

        if h != -1:
            nxt = list(state)
            nxt[h] = TABLE
            nxt = tuple(nxt)
            if nxt not in parent:
                parent[nxt] = (state, f"(putdown {blocks[h]})")
                queue.append(nxt)
        else:
            candidates = [
                i for i in range(n)
                if state[i] >= 0 and is_clear(state, i)
            ]
            candidates.sort(key=lambda i: (stack_id[i], i))

            for i in candidates:
                j = state[i]
                nxt = list(state)
                nxt[i] = HELD
                nxt = tuple(nxt)
                if nxt not in parent:
                    parent[nxt] = (state, f"(unstack {blocks[i]} {blocks[j]})")
                    queue.append(nxt)

    print("No plan")

if __name__ == "__main__":
    solve()

import sys
import heapq

# Variables:
#   held: 0 if arm is empty, otherwise the block currently held.
#   support[b]: 0 if block b is on the table,
#               another block number if block b is on that block,
#               -1 if block b is currently held.
#
# Constraints:
#   - pickup/unstack only clear blocks, with empty arm.
#   - putdown/stack only while holding a block.
#   - stack only on a clear block.
#   - never stack block1 on block4.

BLOCKS = tuple(range(1, 14))

INITIAL_SUPPORT = [0] * 14
INITIAL_SUPPORT[1] = 9
INITIAL_SUPPORT[9] = 13
INITIAL_SUPPORT[13] = 10
INITIAL_SUPPORT[10] = 0

INITIAL_SUPPORT[7] = 4
INITIAL_SUPPORT[4] = 0

INITIAL_SUPPORT[11] = 0

INITIAL_SUPPORT[12] = 5
INITIAL_SUPPORT[5] = 0

INITIAL_SUPPORT[3] = 6
INITIAL_SUPPORT[6] = 8
INITIAL_SUPPORT[8] = 0

INITIAL_SUPPORT[2] = 0

GOAL_TOWERS = [
    [1, 6, 3, 9, 5],
    [13, 7],
    [11],
    [12, 10, 8, 2, 4],
]

GOAL_SUPPORT = [0] * 14
for tower in GOAL_TOWERS:
    GOAL_SUPPORT[tower[0]] = 0
    for i in range(1, len(tower)):
        GOAL_SUPPORT[tower[i]] = tower[i - 1]

FORBIDDEN_STACK = (1, 4)


def heuristic(state):
    held, sup = state

    top = [0] * 14
    for b in BLOCKS:
        s = sup[b]
        if s != -1 and s != 0:
            top[s] = b

    dirty = [False] * 14
    for b in BLOCKS:
        if b == held:
            dirty[b] = True
        else:
            if sup[b] != GOAL_SUPPORT[b]:
                dirty[b] = True

    changed = True
    while changed:
        changed = False
        for b in BLOCKS:
            if dirty[b]:
                t = top[b]
                if t != 0 and not dirty[t]:
                    dirty[t] = True
                    changed = True

    dirty_count = sum(dirty[b] for b in BLOCKS)

    extra = 0
    for b in BLOCKS:
        if b != held:
            g = GOAL_SUPPORT[b]
            if g != 0 and sup[b] == g and dirty[g]:
                extra += 1

    h = 2 * dirty_count + 2 * extra

    if held:
        h -= 1
        g = GOAL_SUPPORT[held]
        if g != 0 and (dirty[g] or top[g] != 0):
            h += 2

    return h


def successors(state):
    held, sup = state

    top = [0] * 14
    for b in BLOCKS:
        s = sup[b]
        if s != -1 and s != 0:
            top[s] = b

    if held == 0:
        for b in BLOCKS:
            if top[b] == 0:
                s = sup[b]
                if s == 0:
                    ns = list(sup)
                    ns[b] = -1
                    yield ("pickup", b), (b, tuple(ns))
                elif s != -1:
                    ns = list(sup)
                    ns[b] = -1
                    yield ("unstack", b, s), (b, tuple(ns))
    else:
        b = held

        ns = list(sup)
        ns[b] = 0
        yield ("putdown", b), (0, tuple(ns))

        for c in BLOCKS:
            if c == b:
                continue
            if top[c] == 0:
                if b == 1 and c == 4:
                    continue
                ns = list(sup)
                ns[b] = c
                yield ("stack", b, c), (0, tuple(ns))


def astar(limit=50000):
    start = (0, tuple(INITIAL_SUPPORT))
    goal = (0, tuple(GOAL_SUPPORT))

    if start == goal:
        return []

    h0 = heuristic(start)
    heap = [(h0, h0, 0, 0, start)]
    best = {start: 0}
    parent = {start: (None, None)}
    counter = 1
    expansions = 0

    while heap:
        _, _, neg_g, _, state = heapq.heappop(heap)
        g = -neg_g

        if g != best.get(state):
            continue

        if state == goal:
            plan = []
            cur = state
            while cur != start:
                prev, action = parent[cur]
                plan.append(action)
                cur = prev
            plan.reverse()
            return plan

        expansions += 1
        if expansions > limit:
            return None

        for action, next_state in successors(state):
            ng = g + 1
            if ng < best.get(next_state, 10**9):
                best[next_state] = ng
                parent[next_state] = (state, action)
                nh = heuristic(next_state)
                counter += 1
                heapq.heappush(heap, (ng + nh, nh, -ng, counter, next_state))

    return None


def constructive_plan():
    sup = list(INITIAL_SUPPORT)
    actions = []

    while True:
        top = [0] * 14
        for b in BLOCKS:
            if sup[b] != 0 and sup[b] != -1:
                top[sup[b]] = b

        b = next((x for x in BLOCKS if sup[x] != 0 and top[x] == 0), None)
        if b is None:
            break

        s = sup[b]
        actions.append(("unstack", b, s))
        sup[b] = 0
        actions.append(("putdown", b))

    for tower in GOAL_TOWERS:
        for i in range(1, len(tower)):
            x = tower[i]
            y = tower[i - 1]
            if (x, y) == FORBIDDEN_STACK:
                return None
            actions.append(("pickup", x))
            actions.append(("stack", x, y))

    return actions


def validate_plan(actions):
    if INITIAL_SUPPORT[1] == 4:
        return False

    sup = list(INITIAL_SUPPORT)
    held = 0

    for act in actions:
        top = [0] * 14
        for b in BLOCKS:
            s = sup[b]
            if s != 0 and s != -1:
                top[s] = b

        if act[0] == "pickup":
            b = act[1]
            if held != 0 or sup[b] != 0 or top[b] != 0:
                return False
            sup[b] = -1
            held = b

        elif act[0] == "unstack":
            b, s = act[1], act[2]
            if held != 0 or sup[b] != s or top[b] != 0:
                return False
            sup[b] = -1
            held = b

        elif act[0] == "putdown":
            b = act[1]
            if held != b:
                return False
            sup[b] = 0
            held = 0

        elif act[0] == "stack":
            b, c = act[1], act[2]
            if held != b or c == b or top[c] != 0:
                return False
            if (b, c) == FORBIDDEN_STACK:
                return False
            sup[b] = c
            held = 0

        else:
            return False

        if sup[1] == 4:
            return False

    if held != 0:
        return False

    for b in BLOCKS:
        if sup[b] != GOAL_SUPPORT[b]:
            return False

    return True


def format_actions(actions):
    lines = []
    for act in actions:
        if act[0] in ("pickup", "putdown"):
            lines.append(f"({act[0]} block{act[1]})")
        else:
            lines.append(f"({act[0]} block{act[1]} block{act[2]})")
    return "\n".join(lines)


def main():
    plan = astar(limit=50000)

    if plan is None or not validate_plan(plan):
        plan = constructive_plan()

    if plan is None or not validate_plan(plan):
        sys.stdout.write("No plan")
    else:
        sys.stdout.write(format_actions(plan))


if __name__ == "__main__":
    main()

import heapq
from itertools import count

BLOCKS = tuple(range(1, 11))
TABLE = 0
HOLDING = -1

initial_pos = [TABLE] * 10
initial_pos[0] = 10
initial_pos[1] = 1
initial_pos[8] = 6
initial_state = (tuple(initial_pos), 0, frozenset())

goal_pos = [TABLE] * 10
goal_pos[0] = 8
goal_tuple = tuple(goal_pos)


def is_clear(pos, b):
    for x in BLOCKS:
        if pos[x - 1] == b:
            return False
    return True


def heuristic(pos):
    return sum(1 for i in range(10) if pos[i] != goal_tuple[i])


def successors(state):
    pos, holding, perm = state

    if holding == 0:
        for b in BLOCKS:
            if b in perm:
                continue
            if pos[b - 1] == TABLE and is_clear(pos, b):
                new_pos = list(pos)
                new_pos[b - 1] = HOLDING
                yield (tuple(new_pos), b, perm), f"(pickup block{b})"

        for b in BLOCKS:
            if b in perm:
                continue
            support = pos[b - 1]
            if support > TABLE and is_clear(pos, b):
                new_pos = list(pos)
                new_pos[b - 1] = HOLDING
                yield (tuple(new_pos), b, perm), f"(unstack block{b} block{support})"
    else:
        b = holding

        new_pos = list(pos)
        new_pos[b - 1] = TABLE
        yield (tuple(new_pos), 0, perm.union({b})), f"(putdown block{b})"

        for c in BLOCKS:
            if c == b:
                continue
            if pos[c - 1] == HOLDING:
                continue
            if is_clear(pos, c):
                new_pos = list(pos)
                new_pos[b - 1] = c
                yield (tuple(new_pos), 0, perm), f"(stack block{b} block{c})"


def main():
    start = initial_state
    if start[0] == goal_tuple and start[1] == 0:
        return

    heap = []
    counter = count()
    h0 = heuristic(start[0])
    heapq.heappush(heap, (h0, h0, 0, next(counter), start))

    best = {start: 0}
    parent = {}

    while heap:
        f, h, g, _, state = heapq.heappop(heap)
        if best.get(state) != g:
            continue

        if state[0] == goal_tuple and state[1] == 0:
            actions = []
            cur = state
            while cur in parent:
                prev, action = parent[cur]
                actions.append(action)
                cur = prev
            actions.reverse()
            print("\n".join(actions))
            return

        for nxt, action in successors(state):
            ng = g + 1
            if ng < best.get(nxt, 10**9):
                best[nxt] = ng
                parent[nxt] = (state, action)
                hn = heuristic(nxt[0])
                heapq.heappush(heap, (ng + hn, hn, ng, next(counter), nxt))

    print("No plan")


