import heapq


def main():
    n = 11
    # Output names are block1..block11, corresponding to A..K.
    names = [f"block{i}" for i in range(1, n + 1)]

    TABLE = -1
    HAND = -2
    EMPTY = -1

    A, B, C, D, E, F, G, H, I, J, K = range(n)

    # Goal:
    # A-B-C, D-E, F-G-H-I-J-K, hand empty.
    goal = [TABLE, A, B, TABLE, D, TABLE, F, G, H, I, J]

    # Initial configuration:
    # A-B-C, D-E, F on table, G-H-I-J-K, hand empty.
    initial = [TABLE, A, B, TABLE, D, TABLE, TABLE, G, H, I, J]

    def is_clear(sup, b):
        return all(x != b for x in sup)

    # Additional constraint: the plan starts by holding F.
    # With F initially on the table, this is encoded as first action: pickup F.
    sup = initial[:]
    hand = EMPTY
    prefix = []

    if hand != EMPTY or sup[F] != TABLE or not is_clear(sup, F):
        print("No plan")
        return

    sup[F] = HAND
    hand = F
    prefix.append(("pickup", F))

    start = (tuple(sup), hand)
    goal_state = (tuple(goal), EMPTY)

    if start == goal_state:
        for action in prefix:
            if len(action) == 2:
                print(f"({action[0]} {names[action[1]]})")
            else:
                print(f"({action[0]} {names[action[1]]} {names[action[2]]})")
        return

    h_cache = {}

    def misplaced_and_above(sup):
        m = [False] * n
        for b in range(n):
            if sup[b] != goal[b]:
                m[b] = True

        changed = True
        while changed:
            changed = False
            for b in range(n):
                if m[b]:
                    for c in range(n):
                        if sup[c] == b and not m[c]:
                            m[c] = True
                            changed = True
        return m

    def heuristic(state):
        if state in h_cache:
            return h_cache[state]

        sup, _ = state
        m = misplaced_and_above(sup)
        h = 0

        for b in range(n):
            if not m[b]:
                continue

            s = sup[b]
            g = goal[b]

            if s == HAND:
                h += 1
            elif s == TABLE:
                if g != TABLE:
                    h += 2
            else:
                if g == TABLE:
                    h += 2
                elif g == s:
                    h += 4
                else:
                    h += 2

        h_cache[state] = h
        return h

    def successors(state, restrict=True):
        sup, hand = state
        res = []

        # In this instance, there is a valid plan that never needs to move
        # blocks already correctly placed and not blocking the moved stack.
        # Restricting to these blocks keeps the search small.
        m = misplaced_and_above(sup) if restrict else [True] * n

        # pickup
        if hand == EMPTY:
            for b in range(n):
                if m[b] and sup[b] == TABLE and is_clear(sup, b):
                    ns = sup[:]
                    ns[b] = HAND
                    res.append((("pickup", b), (tuple(ns), b)))

        # putdown
        if hand != EMPTY:
            b = hand
            if m[b]:
                ns = sup[:]
                ns[b] = TABLE
                res.append((("putdown", b), (tuple(ns), EMPTY)))

        # unstack
        if hand == EMPTY:
            for b in range(n):
                if m[b]:
                    s = sup[b]
                    if s not in (TABLE, HAND) and is_clear(sup, b):
                        y = s
                        ns = sup[:]
                        ns[b] = HAND
                        res.append((("unstack", b, y), (tuple(ns), b)))

        # stack
        if hand != EMPTY:
            b = hand
            if m[b]:
                for y in range(n):
                    if y == b or sup[y] == HAND:
                        continue
                    if is_clear(sup, y):
                        ns = sup[:]
                        ns[b] = y
                        res.append((("stack", b, y), (tuple(ns), EMPTY)))

        # Prefer putdowns and lower heuristic values to follow the natural plan.
        res.sort(key=lambda item: (0 if item[0][0] == "putdown" else 1, heuristic(item[1])))
        return res

    def astar(start_state, restrict):
        g_score = {start_state: 1}  # one action has already been taken: pickup F
        parent = {start_state: (None, None)}
        counter = 0
        h0 = heuristic(start_state)
        heap = [(h0 + 1, h0, -1, counter, start_state)]

        while heap:
            _, _, neg_g, _, state = heapq.heappop(heap)
            g = -neg_g

            if g != g_score.get(state):
                continue

            if state == goal_state:
                actions = []
                cur = state
                while parent[cur][0] is not None:
                    prev, action = parent[cur]
                    actions.append(action)
                    cur = prev
                actions.reverse()
                return actions

            for action, ns in successors(state, restrict):
                ng = g + 1
                if ng < g_score.get(ns, float("inf")):
                    g_score[ns] = ng
                    parent[ns] = (state, action)
                    h2 = heuristic(ns)
                    counter += 1
                    heapq.heappush(heap, (ng + h2, h2, -ng, counter, ns))

        return None

    actions = astar(start, True)

    if actions is None:
        print("No plan")
        return

    plan = prefix + actions

    # Final verification against the stated initial state and constraints.
    if not plan or plan[0] != ("pickup", F):
        print("No plan")
        return

    def apply_action(state, action):
        sup, hand = state
        kind = action[0]

        if kind == "pickup":
            b = action[1]
            if hand != EMPTY or sup[b] != TABLE or not is_clear(sup, b):
                return None
            ns = sup[:]
            ns[b] = HAND
            return (tuple(ns), b)

        if kind == "putdown":
            b = action[1]
            if hand != b:
                return None
            ns = sup[:]
            ns[b] = TABLE
            return (tuple(ns), EMPTY)

        if kind == "unstack":
            b, y = action[1], action[2]
            if hand != EMPTY or sup[b] != y or not is_clear(sup, b):
                return None
            ns = sup[:]
            ns[b] = HAND
            return (tuple(ns), b)

        if kind == "stack":
            b, y = action[1], action[2]
            if hand != b or y == b or sup[y] == HAND or not is_clear(sup, y):
                return None
            ns = sup[:]
            ns[b] = y
            return (tuple(ns), EMPTY)

        return None

    state = (tuple(initial), EMPTY)
    for action in plan:
        state = apply_action(state, action)
        if state is None:
            print("No plan")
            return

    if state != goal_state:
        print("No plan")
        return

    for action in plan:
        if len(action) == 2:
            print(f"({action[0]} {names[action[1]]})")
        else:
            print(f"({action[0]} {names[action[1]]} {names[action[2]]})")


if __name__ == "__main__":
    main()

import sys
from collections import defaultdict

BLOCKS = list(range(1, 15))


def initial_on():
    on = {b: None for b in BLOCKS}
    on[2] = 6
    on[4] = 1
    on[11] = 4
    on[13] = 11
    on[12] = 13
    on[5] = 8
    on[10] = 14
    on[9] = 10
    return on


def build_on_top(on):
    on_top = {b: None for b in BLOCKS}
    for b, support in on.items():
        if support is not None:
            on_top[support] = b
    return on_top


def consistent_goal(goal_on):
    if set(goal_on.keys()) != set(BLOCKS):
        return False

    above = defaultdict(set)
    for b, support in goal_on.items():
        if support is not None:
            above[support].add(b)

    for support, blocks_above in above.items():
        if len(blocks_above) > 1:
            return False

    color = {b: 0 for b in BLOCKS}

    def dfs(b):
        color[b] = 1
        support = goal_on[b]
        if support is not None:
            if color[support] == 1:
                return False
            if color[support] == 0:
                if not dfs(support):
                    return False
        color[b] = 2
        return True

    for b in BLOCKS:
        if color[b] == 0:
            if not dfs(b):
                return False

    return True


def combine_goal_constraints():
    required_support = {b: set() for b in BLOCKS}

    # Stated goal:
    # block7 on table with block13 on top
    # block4 on table with block8 on top
    # all other listed blocks on table
    for b in BLOCKS:
        required_support[b].add(None)
    required_support[13].add(7)
    required_support[8].add(4)

    # Additional constraint:
    # one single tower, lowest number on table, highest number on top
    for b in BLOCKS:
        required_support[b].add(b - 1 if b > 1 else None)

    goal_on = {}
    for b in BLOCKS:
        if len(required_support[b]) != 1:
            return None
        goal_on[b] = next(iter(required_support[b]))

    if not consistent_goal(goal_on):
        return None

    return goal_on


class State:
    def __init__(self, on):
        self.on = on
        self.on_top = build_on_top(on)
        self.holding = None

    def is_goal(self, goal_on):
        if self.holding is not None:
            return False
        return all(self.on[b] == goal_on[b] for b in BLOCKS)


def make_planner(state):
    plan = []

    def pickup(b):
        if state.holding is not None or state.on[b] is not None or state.on_top[b] is not None:
            raise RuntimeError
        state.holding = b
        plan.append(f"(pickup block{b})")

    def putdown(b):
        if state.holding != b or state.on[b] is not None or state.on_top[b] is not None:
            raise RuntimeError
        state.holding = None
        plan.append(f"(putdown block{b})")

    def unstack(x, y):
        if state.holding is not None or state.on[x] != y or state.on_top[x] is not None:
            raise RuntimeError
        state.holding = x
        state.on[x] = None
        state.on_top[x] = None
        state.on_top[y] = None
        plan.append(f"(unstack block{x} block{y})")

    def stack(x, y):
        if state.holding != x or state.on_top[y] is not None:
            raise RuntimeError
        state.holding = None
        state.on[x] = y
        state.on_top[x] = None
        state.on_top[y] = x
        plan.append(f"(stack block{x} block{y})")

    def move_to_table(b):
        while state.on_top[b] is not None:
            c = state.on_top[b]
            move_to_table(c)

        if state.on[b] is None:
            return

        support = state.on[b]
        unstack(b, support)
        putdown(b)

    def clear_above(b):
        while state.on_top[b] is not None:
            c = state.on_top[b]
            move_to_table(c)

    def place(b, goal_on):
        clear_above(b)

        if state.on[b] == goal_on[b] and state.on_top[b] is None:
            return

        if state.on[b] is None:
            pickup(b)
        else:
            support = state.on[b]
            unstack(b, support)

        if goal_on[b] is None:
            putdown(b)
        else:
            target = goal_on[b]
            clear_above(target)
            stack(b, target)

    return plan, place


def topological_order(goal_on):
    order = []
    color = {b: 0 for b in BLOCKS}

    def dfs(b):
        color[b] = 1
        support = goal_on[b]
        if support is not None:
            if color[support] == 1:
                raise RuntimeError
            if color[support] == 0:
                dfs(support)
        order.append(b)
        color[b] = 2

    for b in BLOCKS:
        if color[b] == 0:
            dfs(b)

    return order


def solve():
    goal_on = combine_goal_constraints()

    if goal_on is None:
        print("No plan")
        return

    state = State(initial_on())
    plan, place = make_planner(state)

    try:
        for b in topological_order(goal_on):
            place(b, goal_on)

        if not state.is_goal(goal_on):
            print("No plan")
            return
    except RuntimeError:
        print("No plan")
        return

    if plan:
        sys.stdout.write("\n".join(plan) + "\n")


if __name__ == "__main__":
    solve()

import sys
from itertools import permutations

BLOCKS = list(range(1, 15))
BLOCK_SET = set(BLOCKS)


def block_name(b):
    return f"block{b}"


def validate_stacks(stacks):
    seen = set()
    for s in stacks:
        if not s:
            return False
        for b in s:
            if b not in BLOCK_SET or b in seen:
                return False
            seen.add(b)
    return seen == BLOCK_SET


def state_from_stacks(stacks):
    if not validate_stacks(stacks):
        return None

    support = {b: 0 for b in BLOCKS}
    on_top = {b: None for b in BLOCKS}

    for s in stacks:
        support[s[0]] = 0
        for lower, upper in zip(s, s[1:]):
            support[upper] = lower
            on_top[lower] = upper

    return support, on_top


def main():
    initial_stacks = [
        [12, 8],
        [4],
        [6],
        [5],
        [7],
        [1],
        [13],
        [11],
        [9],
        [3, 14],
        [10],
        [2],
    ]

    if not validate_stacks(initial_stacks):
        print("No plan")
        return

    singletons = {1, 10, 4, 9, 8, 6, 13, 14, 12, 11, 3, 2}
    must_be_on = {7: 6}
    also_on_table = {5}

    mult3 = sorted(b for b in BLOCKS if b % 3 == 0)
    odd_nonmult = sorted(b for b in BLOCKS if b % 2 == 1 and b % 3 != 0)
    even_nonmult = sorted(b for b in BLOCKS if b % 2 == 0 and b % 3 != 0)
    categories = [mult3, odd_nonmult, even_nonmult]

    def satisfies_goal(stacks):
        if len(stacks) != 3:
            return False

        state = state_from_stacks(stacks)
        if state is None:
            return False

        support, on_top = state

        if sum(1 for b in BLOCKS if support[b] == 0) != 3:
            return False

        for b in singletons:
            if support[b] != 0 or on_top[b] is not None:
                return False

        for b, lower in must_be_on.items():
            if support[b] != lower:
                return False

        for b in also_on_table:
            if support[b] != 0:
                return False

        def stack_above(root):
            result = [root]
            while on_top[result[-1]] is not None:
                result.append(on_top[result[-1]])
            return result

        allowed = {tuple(c) for c in categories}
        for root in [b for b in BLOCKS if support[b] == 0]:
            st = stack_above(root)
            if tuple(st) not in allowed:
                return False
            if st != sorted(st):
                return False

        return True

    goal_stacks = None
    seen_candidates = set()

    for perm in permutations(range(3)):
        candidate = [list(categories[i]) for i in perm]
        key = frozenset(tuple(s) for s in candidate)
        if key in seen_candidates:
            continue
        seen_candidates.add(key)

        if satisfies_goal(candidate):
            goal_stacks = candidate
            break

    if goal_stacks is None:
        print("No plan")
        return

    actions = []

    for s in initial_stacks:
        for i in range(len(s) - 1, 0, -1):
            actions.append(("unstack", s[i], s[i - 1]))
            actions.append(("putdown", s[i]))

    for s in goal_stacks:
        for i in range(1, len(s)):
            actions.append(("pickup", s[i]))
            actions.append(("stack", s[i], s[i - 1]))

    lines = []
    for a in actions:
        if len(a) == 2:
            lines.append(f"({a[0]} {block_name(a[1])})")
        else:
            lines.append(f"({a[0]} {block_name(a[1])} {block_name(a[2])})")

    sys.stdout.write("\n".join(lines))


