import sys


def main():
    # Variables:
    #   support[b] = "table" | another block | None (currently held)
    #   arm = None | a block
    # Constraints:
    #   - at most one block is held
    #   - a block can be picked up only if it is on the table and clear
    #   - a block can be unstacked only if it is clear and on another block
    #   - a block can be stacked only if the target block is clear
    #   - the arm must be free before pickup/unstack and holding the block before putdown/stack

    blocks = [f"block{i}" for i in range(1, 11)]

    initial = {
        "block1": "table",
        "block2": "table",
        "block3": "table",
        "block4": "table",
        "block5": "table",
        "block6": "table",
        "block7": "block3",
        "block8": "block5",
        "block9": "table",
        "block10": "table",
    }

    goal = {
        "block1": "block8",
        "block2": "table",
        "block3": "block1",
        "block4": "block7",
        "block5": "block9",
        "block6": "table",
        "block7": "block2",
        "block8": "block10",
        "block9": "block3",
        "block10": "table",
    }

    def is_clear(support, b):
        return all(support[x] != b for x in blocks)

    def apply_action(support, arm, action):
        typ = action[0]

        if typ == "pickup":
            b = action[1]
            if arm is not None:
                return None
            if support[b] != "table":
                return None
            if not is_clear(support, b):
                return None
            support[b] = None
            arm = b

        elif typ == "putdown":
            b = action[1]
            if arm != b:
                return None
            support[b] = "table"
            arm = None

        elif typ == "unstack":
            b, c = action[1], action[2]
            if arm is not None:
                return None
            if support[b] != c:
                return None
            if not is_clear(support, b):
                return None
            support[b] = None
            arm = b

        elif typ == "stack":
            b, c = action[1], action[2]
            if arm != b:
                return None
            if b == c:
                return None
            if support[b] is not None:
                return None
            if support[c] is None:
                return None
            if not is_clear(support, b):
                return None
            if not is_clear(support, c):
                return None
            support[b] = c
            arm = None

        else:
            return None

        return support, arm

    support = dict(initial)
    arm = None
    plan = []

    def do(action):
        nonlocal support, arm
        result = apply_action(support, arm, action)
        if result is None:
            return False
        support, arm = result
        plan.append(action)
        return True

    # First flatten all stacks: move every non-table block to the table.
    while True:
        top = None
        for b in blocks:
            if support[b] is not None and support[b] != "table" and is_clear(support, b):
                top = b
                break

        if top is None:
            break

        below = support[top]
        if not do(("unstack", top, below)):
            print("No plan")
            return
        if not do(("putdown", top)):
            print("No plan")
            return

    # Derive the goal towers from the goal support relation.
    towers = []
    for b in blocks:
        if goal[b] == "table":
            tower = [b]
            current = b
            seen = {b}

            while True:
                above = None
                for x in blocks:
                    if goal[x] == current:
                        above = x
                        break

                if above is None or above in seen:
                    break

                tower.append(above)
                seen.add(above)
                current = above

            towers.append(tower)

    # Build each goal tower bottom-up.  After flattening, all blocks are on the table.
    for tower in towers:
        for i in range(1, len(tower)):
            b = tower[i]
            target = tower[i - 1]

            if not do(("pickup", b)):
                print("No plan")
                return
            if not do(("stack", b, target)):
                print("No plan")
                return

    # Verify the generated plan from the original initial state.
    check_support = dict(initial)
    check_arm = None

    for action in plan:
        result = apply_action(check_support, check_arm, action)
        if result is None:
            print("No plan")
            return
        check_support, check_arm = result

    if check_arm is not None or any(check_support[b] != goal[b] for b in blocks):
        print("No plan")
        return

    sys.stdout.write("\n".join(f"({' '.join(action)})" for action in plan) + "\n")


