    main()

from collections import deque


def main():
    blocks = [f"block{i}" for i in range(1, 12)]

    initial_on = {b: "table" for b in blocks}

    goal_on = {
        "block11": "table",
        "block8": "block11",
        "block2": "block8",
        "block4": "block2",
        "block10": "block4",
        "block1": "block10",
        "block5": "block1",
        "block6": "block5",
        "block3": "block6",
        "block7": "block3",
        "block9": "block7",
    }

    adj = {b: set() for b in blocks}
    indeg = {b: 0 for b in blocks}

    def add_edge(a, b):
        if a == b:
            return
        if b not in adj[a]:
            adj[a].add(b)
            indeg[b] += 1

    for b in blocks:
        support = goal_on[b]
        if support != "table":
            add_edge(support, b)

    moved = {b for b in blocks if initial_on[b] != goal_on[b]}

    if "block1" in moved and "block6" in moved:
        add_edge("block1", "block6")

    q = deque(sorted(b for b in blocks if indeg[b] == 0))
    order = []

    while q:
        q = deque(sorted(q))
        b = q.popleft()
        order.append(b)

        for nb in sorted(adj[b]):
            indeg[nb] -= 1
            if indeg[nb] == 0:
                q.append(nb)

    if len(order) != len(blocks):
        print("No plan")
        return

    plan = []
    for b in order:
        if initial_on[b] == goal_on[b]:
            continue
        if goal_on[b] != "table":
            plan.append(f"(pickup {b})")
            plan.append(f"(stack {b} {goal_on[b]})")

    on = dict(initial_on)
    clear = {b: True for b in blocks}
    holding = None
    need_block6_after_block1 = False
    ok = True

    for line in plan:
        parts = line[1:-1].split()
        act = parts[0]

