import sys


def main():
    # Blocks are numbered 1..14.
    # State variables:
    #   support[b] = 0 (table), -1 (held), or the block supporting b
    #   clear[b]   = True iff no block is directly on top of b
    #
    # Additional constraint:
    #   Every completed move of block1 must have a later completed move of block5.
    # The planner first completes all moves needed for block1's goal tower
    # without moving block5, then moves block5 and the remaining blocks.

    n = 14
    blocks = list(range(1, n + 1))

    initial_stacks = [
        [3, 14, 7, 11],
        [10, 12, 5, 6, 8, 4, 9, 13, 2, 1],
    ]

    goal_stacks = [
        [14, 4, 1],
        [11, 5, 10, 6, 12, 3, 7, 13, 8, 9, 2],
    ]

    TABLE = 0
    HOLD = -1

    def name(b):
        return f"block{b}"

    def make_initial_state():
        support = {b: TABLE for b in blocks}
        clear = {b: True for b in blocks}
        for stack in initial_stacks:
            for i in range(1, len(stack)):
                below = stack[i - 1]
                above = stack[i]
                support[above] = below
                clear[below] = False
            if stack:
                clear[stack[-1]] = True
        return support, clear

    def make_goal_support():
        support = {b: TABLE for b in blocks}
        for stack in goal_stacks:
            for i in range(1, len(stack)):
                support[stack[i]] = stack[i - 1]
        return support

    support, clear = make_initial_state()
    actions = []
    plan = []

    def add_action(act, *args):
        actions.append((act,) + args)
        if len(args) == 1:
            plan.append(f"({act} {name(args[0])})")
        else:
            plan.append(f"({act} {name(args[0])} {name(args[1])})")

    def do_unstack(x, y):
        add_action("unstack", x, y)
        support[x] = HOLD
        clear[y] = True

    def do_putdown(x):
        add_action("putdown", x)
        support[x] = TABLE
        clear[x] = True

    def do_pickup(x):
        add_action("pickup", x)
        support[x] = HOLD

    def do_stack(x, y):
        add_action("stack", x, y)
        support[x] = y
        clear[y] = False
        clear[x] = True

    def find_on_top(b):
        for x in blocks:
            if support[x] == b:
                return x
        return None

    forbidden5 = frozenset([5])

    def move_to_table(b, forbidden=frozenset()):
        """Move block b to the table, first moving any block on top of it."""
        if support[b] == TABLE:
            return

        top = find_on_top(b)
        if top is not None:
            if top in forbidden:
                raise ValueError("constraint would be violated")
            move_to_table(top, forbidden)

        if support[b] == TABLE:
            return

        y = support[b]
        if y == HOLD:
            do_putdown(b)
        else:
            do_unstack(b, y)
            do_putdown(b)

    goal1 = next((s for s in goal_stacks if 1 in s), None)
    goal5 = next((s for s in goal_stacks if 5 in s), None)

    if goal1 is None or goal5 is None:
        print("No plan")
        return

    # Phase 1: prepare and build block1's goal tower without moving block5.
    for b in goal1:
        move_to_table(b, forbidden5)

    for i in range(1, len(goal1)):
        x = goal1[i]
        if support[x] != TABLE:
            move_to_table(x, forbidden5)

        top = find_on_top(x)
        if top is not None:
            if top in forbidden5:
                print("No plan")
                return
            move_to_table(top, forbidden5)

        do_pickup(x)
        do_stack(x, goal1[i - 1])

    # Phase 2: move all blocks not in block1's completed tower to the table.
    in_goal1 = set(goal1)
    roots = [b for b in blocks if support[b] == TABLE]

    for root in roots:
        if root in in_goal1:
            continue

        stack = []
        cur = root
        while cur is not None:
            stack.append(cur)
            cur = find_on_top(cur)

        for b in reversed(stack):
            if b in in_goal1:
                continue
            if support[b] != TABLE:
                y = support[b]
                if y == HOLD:
                    do_putdown(b)
                else:
                    do_unstack(b, y)
                    do_putdown(b)

    # Phase 3: build the remaining goal stacks, with block5's stack first.
    remaining = [s for s in goal_stacks if s is not goal1]
    remaining = [goal5] + [s for s in remaining if s is not goal5]

    for stack in remaining:
        bottom = stack[0]
        if support[bottom] != TABLE:
            move_to_table(bottom)

        top = find_on_top(bottom)
        if top is not None:
            move_to_table(top)

        for i in range(1, len(stack)):
            x = stack[i]
            if support[x] != TABLE:
                move_to_table(x)

            top = find_on_top(x)
            if top is not None:
                move_to_table(top)

            do_pickup(x)
            do_stack(x, stack[i - 1])

    def verify(actions):
        support, clear = make_initial_state()
        held = None
        move_events = []

        for i, action in enumerate(actions):
            act = action[0]

            if act == "pickup":
                x = action[1]
                if held is not None or support[x] != TABLE or not clear[x]:
                    return False
                support[x] = HOLD
                held = x

            elif act == "unstack":
                x, y = action[1], action[2]
                if held is not None or support[x] != y or not clear[x]:
                    return False
                support[x] = HOLD
                clear[y] = True
                held = x

            elif act == "putdown":
                x = action[1]
                if held != x or support[x] != HOLD:
                    return False
                support[x] = TABLE
                clear[x] = True
                held = None
                move_events.append((i, x))

            elif act == "stack":
                x, y = action[1], action[2]
                if (
                    held != x
                    or support[x] != HOLD
                    or support[y] == HOLD
                    or not clear[y]
                    or x == y
                ):
                    return False
                support[x] = y
                clear[y] = False
                clear[x] = True
                held = None
                move_events.append((i, x))

            else:
                return False

        if held is not None:
            return False

        if support != make_goal_support():
            return False

        for b in blocks:
            has_top = any(support[x] == b for x in blocks)
            if clear[b] != (not has_top):
                return False

        # Additional constraint: every completed move of block1
        # must have a later completed move of block5.
        seen5 = False
        for _, b in reversed(move_events):
            if b == 5:
                seen5 = True
            elif b == 1 and not seen5:
                return False

        return True

    if verify(actions):
        print("\n".join(plan))
    else:
        print("No plan")


if __name__ == "__main__":
    main()

from collections import deque

BLOCKS = 7
TABLE = 7
ARM = 8
NAMES = [f"block{i + 1}" for i in range(BLOCKS)]

MULTIPLES_OF_3 = {2, 5}
MULTIPLES_OF_5 = {4}

INITIAL_ON = (5, TABLE, TABLE, TABLE, TABLE, TABLE, 3)
INITIAL_HOLDING = -1
GOAL_ON = (TABLE, TABLE, 4, TABLE, TABLE, 3, 5)


def generate_actions(on, holding):
    clear = [True] * BLOCKS
    for i in range(BLOCKS):
        s = on[i]
        if 0 <= s < BLOCKS:
            clear[s] = False
    if holding != -1:
        clear[holding] = True

    if holding == -1:
        for x in range(BLOCKS):
            if on[x] == TABLE and clear[x]:
                new_on = list(on)
                new_on[x] = ARM
                yield ("pickup", x), tuple(new_on), x, x

            if 0 <= on[x] < BLOCKS and clear[x]:
                y = on[x]
                new_on = list(on)
                new_on[x] = ARM
                yield ("unstack", x, y), tuple(new_on), x, x
    else:
        x = holding

        new_on = list(on)
        new_on[x] = TABLE
        yield ("putdown", x), tuple(new_on), -1, x

        for y in range(BLOCKS):
            if y != x and on[y] != ARM and clear[y]:
                new_on = list(on)
                new_on[x] = y
                yield ("stack", x, y), tuple(new_on), -1, x


def main():
    start = (INITIAL_ON, INITIAL_HOLDING, False)
    parent = {start: None}
    queue = deque([start])

    while queue:
        state = queue.popleft()
        on, holding, need_five = state

        if on == GOAL_ON and holding == -1 and not need_five:
            path = []
            current = state
            while parent[current] is not None:
                previous, action = parent[current]
                path.append(action)
                current = previous
            path.reverse()

            for action in path:
                print(f"({action[0]} " + " ".join(NAMES[i] for i in action[1:]) + ")")
            return

        for action, new_on, new_holding, moved in generate_actions(on, holding):
            if need_five and moved not in MULTIPLES_OF_5:
                continue

            new_need_five = moved in MULTIPLES_OF_3
            new_state = (new_on, new_holding, new_need_five)

            if new_state not in parent:
                parent[new_state] = (state, action)
                queue.append(new_state)

    print("No plan")


