    main()

import heapq

N = 8

# on[i] = -1 if block i is on the table,
#         -2 if block i is held,
#         j if block i is on block j.
INITIAL_ON = (-1, -1, -1, 5, 0, 1, 4, 6)
GOAL_ON = (-1, -1, -1, -1, -1, 4, -1, -1)

HOLD_NONE = -1
HELD = -2


def heuristic(state):
    on, held = state

    must_move = [False] * N

    # Blocks whose support differs from the goal support must be moved.
    for i in range(N):
        if i != held and on[i] != GOAL_ON[i]:
            must_move[i] = True

    # A held block must be placed.
    if held != HOLD_NONE:
        must_move[held] = True

    # If a block must be moved, every block above it must also be moved
    # to make it clear.
    children = [[] for _ in range(N)]
    for i in range(N):
        if on[i] >= 0:
            children[on[i]].append(i)

    changed = True
    while changed:
        changed = False
        for i in range(N):
            if must_move[i] and on[i] != HELD:
                for c in children[i]:
                    if not must_move[c]:
                        must_move[c] = True
                        changed = True

    # A non-held block that must move needs at least lift + place = 2 actions.
    # A held block needs at least one placing action.
    h = 0
    for i in range(N):
        if must_move[i]:
            if i == held:
                h += 1
            else:
                h += 2
    return h


def successors(state):
    on, held = state
    on_list = list(on)

    children = [[] for _ in range(N)]
    for i in range(N):
        if on[i] >= 0:
            children[on[i]].append(i)

    clear = [len(children[i]) == 0 for i in range(N)]

    if held == HOLD_NONE:
        # Unstack clear blocks from other blocks.
        for i in range(N - 1, -1, -1):
            if on[i] >= 0 and clear[i]:
                j = on[i]
                no = on_list[:]
                no[i] = HELD
                yield (tuple(no), i), ("unstack", i, j)

        # Pick up clear blocks from the table.
        for i in range(N - 1, -1, -1):
            if on[i] == -1 and clear[i]:
                no = on_list[:]
                no[i] = HELD
                yield (tuple(no), i), ("pickup", i)
    else:
        i = held

        # Put down the held block.
        no = on_list[:]
        no[i] = -1
        yield (tuple(no), HOLD_NONE), ("putdown", i)

        # Stack the held block on any clear, non-held block.
        for j in range(N - 1, -1, -1):
            if j != i and on[j] != HELD and clear[j]:
                no = on_list[:]
                no[i] = j
                yield (tuple(no), HOLD_NONE), ("stack", i, j)


def format_action(action):
    if action[0] in ("pickup", "putdown"):
        return f"({action[0]} block{action[1] + 1})"
    return f"({action[0]} block{action[1] + 1} block{action[2] + 1})"


def solve():
    start = (INITIAL_ON, HOLD_NONE)
    goal = (GOAL_ON, HOLD_NONE)

    if start == goal:
        return

    counter = 0
    heap = [(heuristic(start), 0, counter, start)]
    dist = {start: 0}
    parent = {}

    while heap:
        _, neg_g, _, state = heapq.heappop(heap)
        g = -neg_g

        if g != dist.get(state):
            continue

        if state == goal:
            actions = []
            cur = state
            while cur in parent:
                prev, action = parent[cur]
                actions.append(action)
                cur = prev
            actions.reverse()

            for action in actions:
                print(format_action(action))
            return

        for next_state, action in successors(state):
            ng = g + 1
            if ng < dist.get(next_state, 10**9):
                dist[next_state] = ng
                parent[next_state] = (state, action)
                counter += 1
                f = ng + heuristic(next_state)
                heapq.heappush(heap, (f, -ng, counter, next_state))

    print("No plan")


if __name__ == "__main__":
    solve()

