def main():
    blocks = [f"block{i}" for i in range(1, 14)]

    # Initial state: block -> support ("table" or another block)
    initial = {b: "table" for b in blocks}
    initial["block11"] = "block7"
    initial["block2"] = "block11"
    initial["block5"] = "block13"
    initial["block8"] = "block4"
    initial["block1"] = "block6"

    # Goal state: block -> support ("table" or another block)
    goal = {b: "table" for b in blocks}
    goal["block13"] = "block6"
    goal["block8"] = "block2"
    goal["block7"] = "block8"
    goal["block1"] = "block7"
    goal["block9"] = "block5"
    goal["block3"] = "block12"
    goal["block11"] = "block3"
    goal["block4"] = "block11"

    state = dict(initial)
    arm = None
    actions = []

    def is_clear(b):
        return all(state[x] != b for x in blocks)

    def pickup(b):
        nonlocal arm
        if arm is not None or state[b] != "table" or not is_clear(b):
            return False
        arm = b
        state[b] = None
        actions.append(f"(pickup {b})")
        return True

    def putdown(b):
        nonlocal arm
        if arm != b:
            return False
        arm = None
        state[b] = "table"
        actions.append(f"(putdown {b})")
        return True

    def unstack(x, y):
        nonlocal arm
        if arm is not None or state[x] != y or not is_clear(x):
            return False
        arm = x
        state[x] = None
        actions.append(f"(unstack {x} {y})")
        return True

    def stack(x, y):
        nonlocal arm
        if arm != x or state[x] is not None:
            return False
        if state[y] is None or not is_clear(y):
            return False
        state[x] = y
        arm = None
        actions.append(f"(stack {x} {y})")
        return True

    ok = True

    # First clear every tower by moving top blocks to the table.
    while ok:
        top = None
        for b in blocks:
            if state[b] not in ("table", None) and is_clear(b):
                top = b
                break
        if top is None:
            break
        support = state[top]
        if not unstack(top, support) or not putdown(top):
            ok = False
            break

    # Then build the goal towers from bottom to top.
    if ok:
        on_goal = {b: [] for b in blocks}
        for b in blocks:
            s = goal[b]
            if s != "table":
                on_goal[s].append(b)

        for bottom in blocks:
            if goal[bottom] == "table":
                cur = bottom
                while on_goal[cur]:
                    child = on_goal[cur].pop(0)
                    if not pickup(child) or not stack(child, cur):
                        ok = False
                        break
                    cur = child
                if not ok:
                    break

    if ok and arm is None and state == goal:
        print("\n".join(actions))
    else:
        print("No plan")

