import heapq

N = 12
TABLE = -1
HOLD = -2

# block i represents block{i+1}
init = [TABLE] * N
init[4] = 3    # block5 on block4
init[10] = 4   # block11 on block5
init[0] = 9    # block1 on block10

# Final-holding constraint is treated as overriding the table placement
# for block12: block12 must be held at the end.
goal = [TABLE] * N
goal[10] = 8   # block11 on block9
goal[2] = 10   # block3 on block11
goal[5] = 3    # block6 on block4
goal[9] = 5    # block10 on block6
goal[0] = 9    # block1 on block10
goal[6] = 0    # block7 on block1
goal[4] = 6    # block5 on block7
goal[7] = 4    # block8 on block5
goal[1] = 7    # block2 on block8
goal[11] = HOLD  # hold block12
FINAL_HELD = 11

start = tuple(init)
goal_state = tuple(goal)

goal_top = [None] * N
for b, g in enumerate(goal):
    if 0 <= g < N:
        goal_top[g] = b


def is_clear(sup, x):
    for z in range(N):
        if sup[z] == x:
            return False
    return True


def final_below(sup, b):
    cur = b
    gcur = b
    while True:
        if cur != gcur:
            return False
        c = sup[cur]
        gc = goal[gcur]
        if c == TABLE or c == HOLD:
            return c == gc
        cur = c
        gcur = gc


def heuristic(sup):
    if sup == goal_state:
        return 0

    total_moves = 0
    for b in range(N):
        s = sup[b]
        g = goal[b]

        if g == HOLD:
            moves = 0 if s == HOLD else 1
        elif s == HOLD:
            moves = 1
        elif s == g:
            if s == TABLE:
                moves = 0
            else:
                moves = 0 if final_below(sup, s) else 2
        else:
            if s == TABLE:
                moves = 1
            elif g == TABLE:
                moves = 1
            elif g == HOLD:
                moves = 1
            else:
                must_leave = (
                    not final_below(sup, s)
                    or (goal_top[s] is not None and goal_top[s] != b)
                )
                if must_leave and not final_below(sup, g):
                    moves = 2
                else:
                    moves = 1

        total_moves += moves

    h = 2 * total_moves
    if sup[FINAL_HELD] != HOLD:
        h -= 1
    return max(0, h)


def fallback_macro_moves():
    # A valid 23-action plan expressed as macro moves (x, from, to).
    return [
        (10, 4, 8),
        (2, TABLE, 10),
        (4, 3, TABLE),
        (0, 9, TABLE),
        (5, TABLE, 3),
        (9, TABLE, 5),
        (0, TABLE, 9),
        (6, TABLE, 0),
        (4, TABLE, 6),
        (7, TABLE, 4),
        (1, TABLE, 7),
        (11, TABLE, HOLD),
    ]


def macro_to_actions(moves):
    actions = []
    for x, s, t in moves:
        if s == TABLE:
            actions.append(("pickup", x, None))
        else:
            actions.append(("unstack", x, s))

        if t == TABLE:
            actions.append(("putdown", x, None))
        elif t == HOLD:
            pass
        else:
            actions.append(("stack", x, t))
    return actions


def solve_astar(limit=200000):
    h0 = heuristic(start)
    counter = 0
    open_heap = [(h0, h0, counter, 0, start)]
    best = {start: 0}
    parent = {}
    popped = 0

    # The fallback plan has 12 macro moves, i.e. 23 primitive actions.
    upper_bound = 2 * len(fallback_macro_moves()) - 1

    while open_heap:
        f, h, _, g, state = heapq.heappop(open_heap)
        if g != best.get(state):
            continue

        popped += 1
        if popped > limit:
            return None
        if f > upper_bound:
            break

        if state == goal_state:
            moves = []
            cur = state
            while cur != start:
                prev, mv = parent[cur]
                moves.append(mv)
                cur = prev
            moves.reverse()
            return macro_to_actions(moves)

        # Final move: hold block12, only when everything else is already correct.
        if state[FINAL_HELD] != HOLD:
            ok = True
            for b in range(N):
                if b != FINAL_HELD and state[b] != goal[b]:
                    ok = False
                    break
            if ok and is_clear(state, FINAL_HELD):
                ns = goal_state
                ng = g + 1
                if ng < best.get(ns, 10**9):
                    best[ns] = ng
                    parent[ns] = (state, (FINAL_HELD, state[FINAL_HELD], HOLD))
                    counter += 1
                    heapq.heappush(open_heap, (ng, 0, counter, ng, ns))

        clear = [is_clear(state, x) for x in range(N)]

        for x in range(N):
            if state[x] == HOLD or not clear[x]:
                continue

            s = state[x]

            # Move to table.
            if s != TABLE:
                lst = list(state)
                lst[x] = TABLE
                ns = tuple(lst)
                ng = g + 2
                if ng < best.get(ns, 10**9):
                    nh = heuristic(ns)
                    if ng + nh <= upper_bound:
                        best[ns] = ng
                        parent[ns] = (state, (x, s, TABLE))
                        counter += 1
                        heapq.heappush(open_heap, (ng + nh, nh, counter, ng, ns))

            # Move onto a clear block.
            for y in range(N):
                if y == x or state[y] == HOLD or not clear[y] or s == y:
                    continue

                lst = list(state)
                lst[x] = y
                ns = tuple(lst)
                ng = g + 2
                if ng < best.get(ns, 10**9):
                    nh = heuristic(ns)
                    if ng + nh <= upper_bound:
                        best[ns] = ng
                        parent[ns] = (state, (x, s, y))
                        counter += 1
                        heapq.heappush(open_heap, (ng + nh, nh, counter, ng, ns))

    return None


def valid_plan(actions):
    sup = list(init)
    holding = -1

    def clear(x):
        return not any(sup[z] == x for z in range(N))

    for action, x, y in actions:
        if action == "pickup":
            if holding != -1 or sup[x] != TABLE or not clear(x):
                return False
            sup[x] = HOLD
            holding = x
        elif action == "putdown":
            if holding != x:
                return False
            sup[x] = TABLE
            holding = -1
        elif action == "unstack":
            if holding != -1 or y is None or sup[x] != y or not clear(x):
                return False
            sup[x] = HOLD
            holding = x
        elif action == "stack":
            if holding != x or y is None or sup[y] == HOLD or not clear(y):
                return False
            sup[x] = y
            holding = -1
        else:
            return False

    if holding != FINAL_HELD or sup[FINAL_HELD] != HOLD:
        return False

    for b in range(N):
        if b == FINAL_HELD:
            continue
        if sup[b] != goal[b]:
            return False

    return True


def print_actions(actions):
    for action, x, y in actions:
        if y is None:
            print(f"({action} block{x + 1})")
        else:
            print(f"({action} block{x + 1} block{y + 1})")


actions = solve_astar()
if actions is None or not valid_plan(actions):
    actions = macro_to_actions(fallback_macro_moves())

if not valid_plan(actions):
    print("No plan")
else:
    print_actions(actions)

