def normalize(stacks, held=0):
    stacks = tuple(tuple(stack) for stack in stacks if stack)
    return (stacks, held)


initial = normalize([
    [6, 3, 5],
    [11],
    [14, 8, 7, 9, 4, 15, 12, 2, 13, 10],
    [1],
])

goal = normalize([
    [8, 7, 12, 5, 13],
    [15, 4],
    [3, 11, 2, 9, 14, 10, 6, 1],
])

REQUIRED_STACKS = 4


def stack_count(state):
    return len(state[0])


if initial != goal and stack_count(goal) != REQUIRED_STACKS:
    print("No plan")
    sys.exit(0)


def successors(state):
    stacks, held = state

    if held == 0:
        for i, stack in enumerate(stacks):
            if len(stack) == 1:
                x = stack[0]
                new_stacks = list(stacks)
                new_stacks.pop(i)
                yield ("pickup", x, None), (tuple(new_stacks), x)

        for i, stack in enumerate(stacks):
            if len(stack) >= 2:
                x = stack[-1]
                y = stack[-2]
                new_stacks = list(stacks)
                new_stack = stack[:-1]
                if new_stack:
                    new_stacks[i] = new_stack
                else:
                    new_stacks.pop(i)
                yield ("unstack", x, y), (tuple(new_stacks), x)

    if held != 0:
        new_stacks = list(stacks)
        new_stacks.append((held,))
        yield ("putdown", held, None), (tuple(new_stacks), 0)

        for i, stack in enumerate(stacks):
            if stack:
                y = stack[-1]
                new_stacks = list(stacks)
                new_stacks[i] = stack + (held,)
                yield ("stack", held, y), (tuple(new_stacks), 0)


def format_action(action):
    if action[0] in ("pickup", "putdown"):
        return f"({action[0]} block{action[1]})"
    return f"({action[0]} block{action[1]} block{action[2]})"


