        if held_block is not None:
            if held_block not in blocks:
                return False
            if held_block in goal:
                if goal[held_block] != HELD:
                    return False
            if any(s == held_block for s in goal.values()):
                return False

        for b, s in goal.items():
            if b not in blocks:
                return False
            if s != TABLE and s != HELD and s not in blocks:
                return False
            if s == HELD and b != held_block:
                return False

        counts = {}
        for b, s in goal.items():
            if s != TABLE and s != HELD:
                counts[s] = counts.get(s, 0) + 1
        if any(c > 1 for c in counts.values()):
            return False

        color = {}

        def dfs(b):
            if b not in goal:
                return True
            s = goal[b]
            if s == TABLE or s == HELD:
                return True
            if color.get(b) == 1:
                return False
            color[b] = 1
            if not dfs(s):
                return False
            color[b] = 2
            return True

        for b in list(goal.keys()):
            if color.get(b) != 2:
                if not dfs(b):
                    return False
        return True

