        support[b] = TABLE
        held = None
        return True

    def do_unstack(b, under):
        nonlocal held
        if held is not None or under in (TABLE, HELD) or support[b] != under or top[b] is not None:
            return False
        support[b] = HELD
        top[under] = None
        held = b
        return True

    def do_stack(b, on):
        nonlocal held
        if held != b or support[b] != HELD or top[b] is not None:
            return False
        if on not in blocks or support[on] == HELD or top[on] is not None:
            return False
        support[b] = on
        top[on] = b
        held = None
        return True

    def add_action(*args):
