            return

    if final_held is not None:
        if support[final_held] != TABLE:
            if top[final_held] is not None:
                print("No plan")
                return
            if support[final_held] == HELD:
                add_action("putdown", final_held)
                if not do_putdown(final_held):
                    print("No plan")
                    return
            else:
                under = support[final_held]
                add_action("unstack", final_held, under)
                if not do_unstack(final_held, under):
