import heapq

BLOCKS = 12

# pos values:
#   0  -> on table
#   k  -> on block k
#  -1  -> in arm
START = (10, 0, 0, 0, 4, 0, 0, 0, 0, 0, 5, 0)
GOAL = (10, 8, 11, 0, 7, 4, 1, 5, 0, 6, 9, 0)


def heuristic(pos):
    """
    Admissible heuristic:
    - A block in the arm needs at least 1 action.
    - A block whose support differs from its goal support needs at least 2 actions.
    - A block whose support is already correct still needs 2 actions if some
      block below it must move, because it must be moved off and later back.
    """
    base = [0] * BLOCKS
    will_move = [False] * BLOCKS
    h = 0

    for i in range(BLOCKS):
        p = pos[i]
        g = GOAL[i]
        if p == -1:
            b = 1
        elif p == g:
            b = 0
        else:
            b = 2

        base[i] = b
        if b:
            will_move[i] = True
            h += b

    # Propagate "must move" upward through current stacks.
    for _ in range(BLOCKS):
        changed = False
        for i in range(BLOCKS):
            p = pos[i]
            if p > 0 and not will_move[i] and will_move[p - 1]:
                will_move[i] = True
                changed = True
        if not changed:
            break

    # Blocks that are correctly supported but sit above a block that must move.
    for i in range(BLOCKS):
        if base[i] == 0:
            p = pos[i]
            if p > 0 and will_move[p - 1]:
                h += 2

    return h


def get_arm(pos):
    for i, p in enumerate(pos):
        if p == -1:
            return i + 1
    return 0


def neighbors(pos):
    arm = get_arm(pos)

    clear = [True] * 13
    for i, p in enumerate(pos):
        if p > 0:
            clear[p] = False

    if arm == 0:
        for b in range(1, BLOCKS + 1):
            p = pos[b - 1]
            if p == 0 and clear[b]:
                nxt = list(pos)
                nxt[b - 1] = -1
                yield ("pickup", b), tuple(nxt)
            elif p > 0 and clear[b]:
                nxt = list(pos)
                nxt[b - 1] = -1
                yield ("unstack", b, p), tuple(nxt)
    else:
        nxt = list(pos)
        nxt[arm - 1] = 0
        yield ("putdown", arm), tuple(nxt)

        for y in range(1, BLOCKS + 1):
            if y == arm:
                continue
            if pos[y - 1] == -1:
                continue
            if clear[y]:
                nxt = list(pos)
                nxt[arm - 1] = y
                yield ("stack", arm, y), tuple(nxt)


def solve():
    if START == GOAL:
        return []

    h0 = heuristic(START)
    counter = 0

    # Heap entries: (f, h, tie_breaker, g, state)
    heap = [(h0, h0, 0, 0, START)]
    g_score = {START: 0}
    parent = {START: None}

    while heap:
        f, h, _, g, state = heapq.heappop(heap)

        if g != g_score.get(state):
            continue

        if state == GOAL:
            actions = []
            cur = state
            while parent[cur] is not None:
                prev, action = parent[cur]
                actions.append(action)
                cur = prev
            actions.reverse()
            return actions

        for action, nstate in neighbors(state):
            ng = g + 1
            old = g_score.get(nstate)
            if old is None or ng < old:
                g_score[nstate] = ng
                parent[nstate] = (state, action)
                nh = heuristic(nstate)
                counter += 1
                heapq.heappush(heap, (ng + nh, nh, counter, ng, nstate))

    return None


def format_action(action):
    if action[0] == "pickup":
        return f"(pickup block{action[1]})"
    if action[0] == "putdown":
        return f"(putdown block{action[1]})"
    if action[0] == "stack":
        return f"(stack block{action[1]} block{action[2]})"
    if action[0] == "unstack":
        return f"(unstack block{action[1]} block{action[2]})"
    return ""


def main():
    plan = solve()
    if plan is None:
        print("No plan")
    else:
        for action in plan:
            print(format_action(action))


if __name__ == "__main__":
    main()

BLOCKS = tuple(range(1, 15))

INITIAL_STACKS = [
    [10, 6, 8],
    [13, 2, 9, 7],
    [4, 1, 14, 5, 3, 11],
]

GOAL_STACKS = [
    [13, 3, 10],
    [4, 8, 11],
    [6, 1, 7, 2, 12, 9, 5, 14],
]


def block_name(b):
    return f"block{b}"


def stacks_to_state(stacks):
    on = {b: None for b in BLOCKS}
    on_top = {b: None for b in BLOCKS}
    for st in stacks:
        for i, b in enumerate(st):
            if i > 0:
                on[b] = st[i - 1]
                on_top[st[i - 1]] = b
    return on, on_top, None


def state_stacks(on, on_top):
    stacks = []
    for b in BLOCKS:
        if on[b] is None:
            st = []
            cur = b
            while cur is not None:
                st.append(cur)
                cur = on_top[cur]
            stacks.append(st)
    return stacks


def valid_stacks(stacks):
    blocks = [b for st in stacks for b in st]
    return sorted(blocks) == list(BLOCKS)


def satisfies_additional(stacks):
    if len(stacks) != 2:
        return False
    if not valid_stacks(stacks):
        return False

    for st in stacks:
        if st != sorted(st):
            return False

    a, b = stacks

    def all_multiple(st):
        return all(x % 5 == 0 for x in st)

    def all_non_multiple(st):
        return all(x % 5 != 0 for x in st)

    return (all_multiple(a) and all_non_multiple(b)) or (
        all_multiple(b) and all_non_multiple(a)
    )


def flatten_plan(initial_stacks):
    on, on_top, held = stacks_to_state(initial_stacks)
    actions = []

    if held is not None:
        actions.append(("putdown", held))
        held = None

    while True:
        b = None
        for x in BLOCKS:
            if on[x] is not None and on_top[x] is None:
                b = x
                break

        if b is None:
            break

        support = on[b]
        actions.append(("unstack", b, support))
        on[b] = None
        on_top[support] = None
        actions.append(("putdown", b))

    return actions


def build_plan(goal_stacks):
    actions = []
    for st in goal_stacks:
        for i in range(1, len(st)):
            actions.append(("pickup", st[i]))
            actions.append(("stack", st[i], st[i - 1]))
    return actions


def apply_action(state, action):
    on, on_top, held = state
    kind = action[0]

    if kind == "pickup":
        b = action[1]
        if held is not None or on[b] is not None or on_top[b] is not None:
            return None
        on = dict(on)
        on_top = dict(on_top)
        on[b] = None
        return on, on_top, b

    if kind == "putdown":
        b = action[1]
        if held != b:
            return None
        on = dict(on)
        on_top = dict(on_top)
        on[b] = None
        return on, on_top, None

    if kind == "unstack":
        b, c = action[1], action[2]
        if held is not None or on[b] != c or on_top[b] is not None:
            return None
        on = dict(on)
        on_top = dict(on_top)
        on[b] = None
        on_top[c] = None
        return on, on_top, b

    if kind == "stack":
        b, c = action[1], action[2]
        if held != b or on_top[c] is not None:
            return None
        on = dict(on)
        on_top = dict(on_top)
        on[b] = c
        on_top[c] = b
        return on, on_top, None

    return None


def matches_goal(state, goal_stacks):
    on, on_top, held = state
    if held is not None:
        return False
    current = {tuple(st) for st in state_stacks(on, on_top)}
    target = {tuple(st) for st in goal_stacks}
    return current == target


def validate_plan(initial_stacks, goal_stacks, actions):
    state = stacks_to_state(initial_stacks)
    for action in actions:
        state = apply_action(state, action)
        if state is None:
            return False

    on, on_top, held = state
    if held is not None:
        return False

    final_stacks = state_stacks(on, on_top)
    return matches_goal(state, goal_stacks) and satisfies_additional(final_stacks)


def main():
    if not valid_stacks(INITIAL_STACKS) or not valid_stacks(GOAL_STACKS):
        print("No plan")
        return

    if not satisfies_additional(GOAL_STACKS):
        print("No plan")
        return

    actions = flatten_plan(INITIAL_STACKS) + build_plan(GOAL_STACKS)

    if not validate_plan(INITIAL_STACKS, GOAL_STACKS, actions):
        print("No plan")
        return

    for action in actions:
        if len(action) == 2:
            print(f"({action[0]} {block_name(action[1])})")
        else:
            print(f"({action[0]} {block_name(action[1])} {block_name(action[2])})")


if __name__ == "__main__":
    main()

import heapq
import itertools

# State representation:
# A state is a tuple of 13 integers for block1..block13.
# Value 0 means the block is on the table.
# Value b means the block is directly on block b.
# The arm is always empty in macro states; each macro move is one lift
# (pickup or unstack) followed by one placement (putdown or stack).
# The pickup limit is enforced as the number of macro moves.

N = 13
BLOCKS = tuple(range(1, N + 1))

# Initial supports:
# 10,7,1 | 12,11,6 | 8,3,5,4,13,2,9
INITIAL = (7, 13, 8, 5, 3, 11, 10, 0, 2, 0, 12, 0, 4)

# Goal supports:
# 7,3 | 8,13 | 5,2,1 | 10 | 11 | 6 | 4 | 9 | 12
GOAL = (2, 5, 7, 0, 0, 0, 0, 0, 0, 0, 0, 0, 8)

MAX_PICKUPS = 20


def heuristic(state):
    """
    Admissible lower bound on remaining macro moves.

    Base:
      Every block whose current support differs from its goal support
      must be moved at least once.

    Extra safe lower bounds:
      - If block x must end on block y, but x is currently above y,
        x must be moved once to clear y and later moved onto y: +1.
      - If block x is already on block y, x's goal is y, and y itself
        must move, then x must be moved off y and later back onto y: +2.
    """
    total = 0
    goal = GOAL

    for i in range(N):
        cur = state[i]
        want = goal[i]

        lb = 1 if cur != want else 0

        if want != 0:
            y = want
            if cur != y:
                # Check whether y is an ancestor of x in the current stack.
                anc = cur
                while anc != 0:
                    if anc == y:
                        lb += 1
                        break
                    anc = state[anc - 1]
            else:
                # x is directly on y and x's goal is y.
                # If y must move, x must move twice.
                if state[y - 1] != goal[y - 1]:
                    lb += 2

        total += lb

    return total


def successors(state):
    """
    Generate all valid macro moves from an arm-empty state.

    A macro move:
      - lifts a clear block x from its current support,
      - places it on table or on a clear block.
    """
    has_on = [False] * (N + 1)
    for i, sup in enumerate(state, 1):
        if sup != 0:
            has_on[sup] = True

    clear = [True] * (N + 1)
    for b in BLOCKS:
        clear[b] = not has_on[b]

    base = list(state)

    for b in BLOCKS:
        if not clear[b]:
            continue

        cur = state[b - 1]
        want = GOAL[b - 1]

        # Generate promising destinations first, but all valid ones are included.
        cand = []
        if want != b and want != cur and (want == 0 or clear[want]):
            cand.append(want)

        if 0 not in cand:
            cand.append(0)

        for d in BLOCKS:
            if clear[d] and d != b and d != cur and d not in cand:
                cand.append(d)

        for d in cand:
            if d == b or d == cur:
                continue

            base[b - 1] = d
            yield tuple(base), (b, cur, d)

        base[b - 1] = cur


def solve():
    if INITIAL == GOAL:
        return []

    h_cache = {INITIAL: heuristic(INITIAL)}
    h0 = h_cache[INITIAL]

    if h0 > MAX_PICKUPS:
        return None

    INF = 10**9
    g_score = {INITIAL: 0}
    parent = {INITIAL: None}
    action = {INITIAL: None}

    counter = itertools.count()
    # Heap entries: (f, h, -g, tie-breaker, state)
    heap = [(h0, h0, 0, next(counter), INITIAL)]

    while heap:
        f, h, neg_g, _, state = heapq.heappop(heap)
        g = -neg_g

        if g != g_score.get(state):
            continue

        if state == GOAL:
            lines = []
            cur_state = state

            while parent[cur_state] is not None:
                b, cur_sup, dest = action[cur_state]

                if cur_sup == 0:
                    lines.append(f"(pickup block{b})")
                else:
                    lines.append(f"(unstack block{b} block{cur_sup})")

                if dest == 0:
                    lines.append(f"(putdown block{b})")
                else:
                    lines.append(f"(stack block{b} block{dest})")

                cur_state = parent[cur_state]

            lines.reverse()
            return lines

        if g >= MAX_PICKUPS:
            continue

        for ns, act in successors(state):
            ng = g + 1

            if ng > MAX_PICKUPS:
                continue

            if ng >= g_score.get(ns, INF):
                continue

            nh = h_cache.get(ns)
            if nh is None:
                nh = heuristic(ns)
                h_cache[ns] = nh

            if ng + nh > MAX_PICKUPS:
                continue

            g_score[ns] = ng
            parent[ns] = state
            action[ns] = act

            heapq.heappush(heap, (ng + nh, nh, -ng, next(counter), ns))

    return None


def main():
    plan = solve()
    if plan is None:
        print("No plan")
    else:
        print("\n".join(plan))


if __name__ == "__main__":
    main()

def main():
    blocks = tuple(range(1, 13))

    goal_on = {b: 0 for b in blocks}
    for x, y in [
        (9, 6),
        (3, 2),
        (7, 3),
        (4, 7),
        (11, 4),
        (12, 11),
        (8, 12),
        (1, 8),
        (10, 1),
        (5, 10),
    ]:
        goal_on[x] = y

    def illegal_stack(x, y):
        return x % 2 == 1 and y % 2 == 0

    child_count = {b: 0 for b in blocks}
    for x, y in goal_on.items():
        if y != 0:
            if x not in blocks or y not in blocks:
                print("No plan")
                return
            child_count[y] += 1
            if child_count[y] > 1 or illegal_stack(x, y):
                print("No plan")
                return

    seen = set()
    for root in blocks:
        if goal_on[root] == 0:
            cur = root
            while cur is not None:
                if cur in seen:
                    print("No plan")
                    return
                seen.add(cur)
                nxt = None
                for c in blocks:
                    if goal_on[c] == cur:
                        nxt = c
                        break
                cur = nxt

    if len(seen) != len(blocks):
        print("No plan")
        return

    def child_of(b):
        for c in blocks:
            if goal_on[c] == b:
                return c
        return None

    plan = []
    for root in blocks:
        if goal_on[root] == 0:
            cur = child_of(root)
            while cur is not None:
                plan.append(("pickup", cur))
                plan.append(("stack", cur, goal_on[cur]))
                cur = child_of(cur)

    def is_clear(b, on, arm):
        if b == arm:
            return False
        if on.get(b) is None:
            return False
        for c in blocks:
            if on.get(c) == b:
                return False
        return True

    on = {b: 0 for b in blocks}
    arm = None

    for action in plan:
        op = action[0]

        if op == "pickup":
            b = action[1]
            if arm is not None or on.get(b) != 0 or not is_clear(b, on, arm):
                print("No plan")
                return
            on[b] = None
            arm = b

        elif op == "putdown":
            b = action[1]
            if arm != b:
                print("No plan")
                return
            on[b] = 0
            arm = None

        elif op == "unstack":
            b, c = action[1], action[2]
            if arm is not None or on.get(b) != c or not is_clear(b, on, arm):
                print("No plan")
                return
            on[b] = None
            arm = b

        elif op == "stack":
            b, c = action[1], action[2]
            if (
                arm != b
                or on.get(c) is None
                or not is_clear(c, on, arm)
                or illegal_stack(b, c)
            ):
                print("No plan")
                return
            on[b] = c
            arm = None

        else:
            print("No plan")
            return

    if arm is not None or any(on[b] != goal_on[b] for b in blocks):
        print("No plan")
        return

    lines = []
    for action in plan:
        op = action[0]
        if op == "pickup":
            lines.append(f"(pickup block{action[1]})")
        elif op == "putdown":
            lines.append(f"(putdown block{action[1]})")
        elif op == "unstack":
            lines.append(f"(unstack block{action[1]} block{action[2]})")
        elif op == "stack":
            lines.append(f"(stack block{action[1]} block{action[2]})")

    print("\n".join(lines))


