from collections import deque

N = 13
BLOCKS = [f"block{i}" for i in range(1, N + 1)]
MAX_STACK_HEIGHT = 2


def make_state(stacks, arm=None):
    on_table = [False] * N
    on = [-1] * N
    top = [-1] * N

    for stack in stacks:
        for pos, b in enumerate(stack):
            if pos == 0:
                on_table[b] = True
            else:
                below = stack[pos - 1]
                on[b] = below
                top[below] = b

    return (arm, tuple(on_table), tuple(on), tuple(top))


INITIAL_STACKS = [
    [11, 5, 0, 2],
    [4],
    [7, 9],
    [6, 12, 3, 10, 1, 8],
]

GOAL_STACKS = [
    [2],
    [7, 6],
    [4, 9],
    [0, 12, 11, 8, 1, 3],
    [10, 5],
]

START = make_state(INITIAL_STACKS)
GOAL = make_state(GOAL_STACKS)


def max_stack_height(state):
    _, on_table, _, top = state
    best = 0

    for i, is_table in enumerate(on_table):
        if is_table:
            h = 1
            cur = i
            while top[cur] != -1:
                cur = top[cur]
                h += 1
            if h > best:
                best = h

    return best


def successors(state):
    arm, on_table, on, top = state
    out = []

    if arm is None:
        for i in range(N):
            if on_table[i] and top[i] == -1:
                nt = list(on_table)
                no = list(on)
                nt[i] = False
                no[i] = -1
                out.append((("pickup", (i,)), (i, tuple(nt), tuple(no), tuple(top))))

            if (not on_table[i]) and on[i] != -1 and top[i] == -1:
                j = on[i]
                nt = list(on_table)
                no = list(on)
                nt_top = list(top)
                no[i] = -1
                nt_top[j] = -1
                out.append((("unstack", (i, j)), (i, tuple(nt), tuple(no), tuple(nt_top))))
    else:
        b = arm

        nt = list(on_table)
        no = list(on)
        nt[b] = True
        no[b] = -1
        out.append((("putdown", (b,)), (None, tuple(nt), tuple(no), tuple(top))))

        for c in range(N):
            if c != b and top[c] == -1:
                nt = list(on_table)
                no = list(on)
                nt_top = list(top)
                nt[b] = False
                no[b] = c
                nt_top[c] = b
                out.append((("stack", (b, c)), (None, tuple(nt), tuple(no), tuple(nt_top))))

    return out


def format_action(action, args):
    if action in ("pickup", "putdown"):
        return f"({action} {BLOCKS[args[0]]})"
    return f"({action} {BLOCKS[args[0]]} {BLOCKS[args[1]]})"


def print_plan(parent, goal_state):
    path = []
    cur = goal_state

    while cur != START:
        prev, action, args = parent[cur]
        path.append((action, args))
        cur = prev

    path.reverse()
    print("\n".join(format_action(a, args) for a, args in path))


def solve():
    if START == GOAL:
        return

    parent = {START: (None, None, None)}
    queue = deque([START])

    while queue:
        state = queue.popleft()

        if state == GOAL:
            print_plan(parent, state)
            return

        for (action, args), nxt in successors(state):
            if max_stack_height(nxt) > MAX_STACK_HEIGHT:
                continue

            if nxt not in parent:
                parent[nxt] = (state, action, args)

                if nxt == GOAL:
                    print_plan(parent, nxt)
                    return

                queue.append(nxt)

    print("No plan")


if __name__ == "__main__":
    solve()

import sys

def main():
    TABLE = -1
    HELD = -2
    blocks = list(range(1, 11))

    # Initial state:
    # block8 is on block5, all other blocks are on the table, hand is empty.
    loc = {b: TABLE for b in blocks}
    loc[8] = 5
    hand = -1
    plan = []

    def bname(b):
        return f"block{b}"

    def is_clear(b):
        return all(loc[x] != b for x in blocks)

    def pickup(b):
        nonlocal hand
        if hand != -1 or loc[b] != TABLE or not is_clear(b):
            return False
        hand = b
        loc[b] = HELD
        plan.append(f"(pickup {bname(b)})")
        return True

    def putdown(b):
        nonlocal hand
        if hand != b:
            return False
        hand = -1
        loc[b] = TABLE
        plan.append(f"(putdown {bname(b)})")
        return True

    def unstack(b, support):
        nonlocal hand
        if hand != -1 or loc[b] != support or not is_clear(b):
            return False
        hand = b
        loc[b] = HELD
        plan.append(f"(unstack {bname(b)} {bname(support)})")
        return True

    def stack(b, support):
        nonlocal hand
        if hand != b or loc[support] == HELD or not is_clear(support):
            return False
        loc[b] = support
        hand = -1
        plan.append(f"(stack {bname(b)} {bname(support)})")
        return True

    # First move every block that is not on the table down to the table.
    while True:
        top = None
        for b in blocks:
            if loc[b] != TABLE and loc[b] != HELD and is_clear(b):
                top = b
                break
        if top is None:
            break
        if not (unstack(top, loc[top]) and putdown(top)):
            plan.clear()
            break

    # Goal state:
    # Tower 1: block2 on table, block3 on block2, block5 on block3,
    #          block1 on block5, block7 on block1, block8 on block7.
    # Tower 2: block6 on table, block9 on block6, block10 on block9,
    #          block4 on block10.
    goal = {
        2: TABLE,
        3: 2,
        5: 3,
        1: 5,
        7: 1,
        8: 7,
        6: TABLE,
        9: 6,
        10: 9,
        4: 10,
    }

    on_top = {}
    for b, support in goal.items():
        if support != TABLE:
            on_top[support] = b

    towers = []
    for bottom in sorted(b for b in blocks if goal[b] == TABLE):
        tower = [bottom]
        current = bottom
        while current in on_top:
            current = on_top[current]
            tower.append(current)
        towers.append(tower)

    if sorted(sum(towers, [])) != blocks:
        plan.clear()

    if plan:
        for tower in towers:
            for i, b in enumerate(tower):
                if i == 0:
                    if loc[b] != TABLE:
                        plan.clear()
                        break
                else:
                    if not (pickup(b) and stack(b, tower[i - 1])):
                        plan.clear()
                        break
            if not plan:
                break

    if plan and hand == -1 and all(loc[b] == goal[b] for b in blocks):
        sys.stdout.write("\n".join(plan))
    else:
        print("No plan")

if __name__ == "__main__":
    main()

from collections import deque

BLOCKS = ["block1", "block2", "block3"]
NUM = {b: int(b[5:]) for b in BLOCKS}
LIMIT = 5


def make_state(loc, arm):
    return (tuple(loc[b] for b in BLOCKS), arm)


def dict_state(state):
    loc, arm = state
    return dict(zip(BLOCKS, loc)), arm


def is_clear(d, b):
    return not any(d[c] == b for c in BLOCKS)


def stacks_ok(state, moved):
    if not moved:
        return True

    loc, _ = state
    d = dict(zip(BLOCKS, loc))

    for b in BLOCKS:
        if d[b] == "table":
            total = 0
            cur = b
            seen = set()

            while cur is not None:
                if cur in seen:
                    return False
                seen.add(cur)
                total += NUM[cur]

                nxt = None
                for c in BLOCKS:
                    if d[c] == cur:
                        nxt = c
                        break
                cur = nxt

            if total > LIMIT:
                return False

    return True


def is_goal(state):
    loc, arm = state
    d = dict(zip(BLOCKS, loc))
    return (
        arm is None
        and d["block3"] == "table"
        and d["block2"] == "block3"
        and d["block1"] == "block2"
    )


def successors(state):
    d, arm = dict_state(state)

    if arm is None:
        for b in BLOCKS:
            if d[b] == "table" and is_clear(d, b):
                nd = d.copy()
                nd[b] = "arm"
                yield ("pickup", b), make_state(nd, b)
            elif d[b] != "table" and d[b] != "arm" and is_clear(d, b):
                under = d[b]
                nd = d.copy()
                nd[b] = "arm"
                yield ("unstack", b, under), make_state(nd, b)
    else:
        b = arm

        nd = d.copy()
        nd[b] = "table"
        yield ("putdown", b), make_state(nd, None)

        for c in BLOCKS:
            if c == b:
                continue
            if d[c] == "arm":
                continue
            if not is_clear(d, c):
                continue

            nd = d.copy()
            nd[b] = c
            yield ("stack", b, c), make_state(nd, None)


def main():
    initial_d = {
        "block1": "block2",
        "block2": "table",
        "block3": "table",
    }
    initial = make_state(initial_d, None)

    if is_goal(initial):
        return

    q = deque()
    q.append((initial, []))
    visited = {initial}

    while q:
        state, path = q.popleft()

        for action, ns in successors(state):
            if not stacks_ok(ns, True):
                continue
            if ns in visited:
                continue

            new_path = path + [action]

            if is_goal(ns):
                for act in new_path:
                    print("(" + " ".join(act) + ")")
                return

            visited.add(ns)
            q.append((ns, new_path))

    print("No plan")


