            x = action[1]
            if holding != x:
                return None
            new_on = on[:]
            new_on[x] = TABLE
            return (new_on, -1)

        if verb == 'unstack':
            x, y = action[1], action[2]
            if holding != -1 or on[x] != y or not clear(on, x):
                return None
            new_on = on[:]
            new_on[x] = HELD
            return (new_on, x)

        if verb == 'stack':
            x, y = action[1], action[2]
            if holding != x or x == y or on[y] == HELD or not clear(on, y):
                return None
            new_on = on[:]
            new_on[x] = y
            return (new_on, -1)

        return None

    plan = [('stack', idx['B'], idx['A'])]
    for bottom, top in [('C', 'D'), ('E', 'F'), ('G', 'H'), ('I', 'J'), ('K', 'L'), ('M', 'N')]:
        b = idx[bottom]
        t = idx[top]
        prev = idx[labels[b - 1]]
        plan.extend([
            ('unstack', t, b),
            ('putdown', t),
            ('pickup', b),
            ('stack', b, prev),
            ('pickup', t),
            ('stack', t, b)
        ])

    state = (on, holding)
    for action in plan:
        new_state = apply_action(state, action)
        if new_state is None:
            print('No plan')
            return
        state = new_state

    if state[0] == goal_on and state[1] == goal_holding:
        for action in plan:
            if len(action) == 2:
                print(f"({action[0]} {names[action[1]]})")
            else:
                print(f"({action[0]} {names[action[1]]} {names[action[2]]})")
    else:
        print('No plan')

if __name__ == '__main__':
    solve()

import sys
from collections import deque


def main():
    blocks = tuple(range(1, 8))

    # loc[b] = 0  -> block b is on the table
    # loc[b] = c  -> block b is on block c
    # loc[b] = -1 -> block b is held by the arm
    init_loc = [0] * 8
    init_loc[3] = 5
    init_loc[4] = 2
    init = (tuple(init_loc), 0)

    def is_goal(state):
        loc, arm = state
        return arm == 0 and all(loc[b] == 0 for b in blocks)

    def is_clear(loc, b):
        return not any(loc[k] == b for k in blocks)

    def successors(state):
        loc, arm = state

        for b in blocks:
            if arm == 0:
                if loc[b] == 0 and is_clear(loc, b):
                    new_loc = list(loc)
                    new_loc[b] = -1
                    yield (tuple(new_loc), b), f"pickup {b}"

                if loc[b] not in (0, -1) and is_clear(loc, b):
                    on = loc[b]
                    new_loc = list(loc)
                    new_loc[b] = -1
                    yield (tuple(new_loc), b), f"unstack {b} {on}"

            if arm == b:
                new_loc = list(loc)
                new_loc[b] = 0
                yield (tuple(new_loc), 0), f"putdown {b}"

                for c in blocks:
                    if c != b and loc[c] != -1 and is_clear(loc, c):
                        new_loc = list(loc)
                        new_loc[b] = c
                        yield (tuple(new_loc), 0), f"stack {b} {c}"

    if is_goal(init):
        return

    parent = {init: None}
    queue = deque([init])
    found = None

    while queue:
        state = queue.popleft()

        for next_state, action in successors(state):
            if next_state in parent:
                continue

            parent[next_state] = (state, action)

            if is_goal(next_state):
                found = next_state
                break

            queue.append(next_state)

        if found is not None:
            break

    if found is None:
        print("No plan")
        return

    plan = []
    current = found
    while parent[current] is not None:
        previous, action = parent[current]
        plan.append(action)
        current = previous

    plan.reverse()

    lines = []
    for action in plan:
        parts = action.split()
        verb = parts[0]
        args = [f"block{int(x)}" for x in parts[1:]]
        lines.append(f"({verb} {' '.join(args)})")

    sys.stdout.write("\n".join(lines))
    if lines:
        sys.stdout.write("\n")


if __name__ == "__main__":
    main()

# Formalization:
# Variables: holding (0 if arm free, else a block), below[b] for b in 1..8.
#   below[b] = 0  -> b is on the table
#   below[b] = -1 -> b is held
#   below[b] = c  -> b is on block c
# Constraints: standard Blocksworld preconditions/effects for pickup, putdown,
#   unstack, stack. Additional weight constraint: after any action (and in the
#   goal state), for every block b, the total weight of blocks above b is <= b.

from collections import deque

N = 8
TABLE = 0
HELD = -1


def build_below(pairs):
    below = [TABLE] * (N + 1)
    for x, y in pairs:
        below[x] = y
    return tuple(below)


initial_below = build_below([
    (6, TABLE), (1, 6),
    (3, TABLE), (2, 3), (8, 2), (5, 8), (7, 5), (4, 7)
])

goal_below = build_below([
    (3, TABLE), (8, 3), (4, 8), (1, 4),
    (2, 1), (7, 2), (6, 7), (5, 6)
])

start = (TABLE, initial_below)
goal = (TABLE, goal_below)


def get_ontop(below):
    ontop = [0] * (N + 1)
    for x in range(1, N + 1):
        y = below[x]
        if y >= TABLE:
            ontop[y] = x
    return ontop


def is_valid(state):
    holding, below = state

    # Basic state consistency.
    if holding != TABLE:
        if below[holding] != HELD:
            return False

    for x in range(1, N + 1):
        y = below[x]
        if y == HELD:
            if x != holding:
                return False
        elif y < TABLE or y > N:
            return False

    # A non-table block can have at most one block directly above it.
    above_count = [0] * (N + 1)
    for x in range(1, N + 1):
        y = below[x]
        if y >= 1:
            above_count[y] += 1
            if above_count[y] > 1:
                return False

    ontop = get_ontop(below)
    if holding != TABLE and ontop[holding] != 0:
        return False

    # Weight constraint: load above each block <= its own weight.
    for b in range(1, N + 1):
        total = 0
        cur = ontop[b]
        seen = set()
        while cur != 0:
            if cur in seen:
                return False
            seen.add(cur)
            total += cur
            cur = ontop[cur]
        if total > b:
            return False

    return True


def successors(state):
    holding, below = state
    ontop = get_ontop(below)

    if holding == TABLE:
        for x in range(1, N + 1):
            if below[x] == TABLE and ontop[x] == 0:
                nb = list(below)
                nb[x] = HELD
                yield ('pickup', x), (x, tuple(nb))
            elif below[x] >= 1 and ontop[x] == 0:
                y = below[x]
                nb = list(below)
                nb[x] = HELD
                yield ('unstack', x, y), (x, tuple(nb))
    else:
        x = holding

        nb = list(below)
        nb[x] = TABLE
        yield ('putdown', x), (TABLE, tuple(nb))

        for y in range(1, N + 1):
            if ontop[y] == 0 and below[y] >= TABLE:
                nb = list(below)
                nb[x] = y
                yield ('stack', x, y), (TABLE, tuple(nb))


def solve():
    # The goal itself must satisfy the weight constraint.
    if not is_valid(goal):
        print("No plan")
        return

    if start == goal:
        return

    queue = deque([start])
    visited = {start}
    parent = {start: (None, None)}

    while queue:
        state = queue.popleft()

        for action, next_state in successors(state):
            if next_state in visited:
                continue
            if not is_valid(next_state):
                continue

            parent[next_state] = (state, action)

            if next_state == goal:
                actions = []
                cur = next_state
                while parent[cur][0] is not None:
                    prev, act = parent[cur]
                    actions.append(act)
                    cur = prev
                actions.reverse()

                for act in actions:
                    if len(act) == 2:
                        print(f"({act[0]} block{act[1]})")
                    else:
                        print(f"({act[0]} block{act[1]} block{act[2]})")
                return

            visited.add(next_state)
            queue.append(next_state)

    print("No plan")


if __name__ == "__main__":
    solve()

# Variables:
#   support[b] = 'T' if b is on the table,
#                another block if b is on that block,
#                None if b is currently held.
#   held       = block currently in the hand, or None.
#
# Constraints are enforced by action preconditions:
#   pickup  : arm empty, block on table, block clear
#   putdown : holding the block
#   unstack : arm empty, block on another block, block clear
#   stack   : holding the block, target not held, target clear

BLOCKS = [chr(ord('a') + i) for i in range(15)]


class State:
    def __init__(self, support, held):
        self.support = support
        self.held = held
        self.plan = []

    def above(self, b):
        for x, s in self.support.items():
            if s == b:
                return x
        return None

    def top_above(self, b):
        cur = self.above(b)
        while cur is not None and self.above(cur) is not None:
            cur = self.above(cur)
        return cur

    def clear(self, b):
        return self.held != b and self.above(b) is None

    def act(self, name, *blocks):
        if name == "pickup":
            x = blocks[0]
            if self.held is not None or self.support[x] != "T" or not self.clear(x):
                return False
            self.held = x
            self.support[x] = None

        elif name == "putdown":
            x = blocks[0]
            if self.held != x:
                return False
            self.held = None
            self.support[x] = "T"

        elif name == "unstack":
            x, y = blocks
            if self.held is not None or self.support[x] != y or not self.clear(x):
                return False
            self.held = x
            self.support[x] = None

        elif name == "stack":
            x, y = blocks
            if self.held != x or self.support[y] is None or not self.clear(y):
                return False
            self.held = None
            self.support[x] = y

        else:
            return False

        self.plan.append(f"({name} {' '.join(blocks)})")
        return True


def clear_above(st, b):
    while True:
        top = st.top_above(b)
        if top is None:
            return True
        if not st.act("unstack", top, st.support[top]):
            return False
        if not st.act("putdown", top):
            return False


def move_to_table(st, b):
    if st.held == b:
        return st.act("putdown", b)

    if st.support[b] == "T":
        return clear_above(st, b)

    if not clear_above(st, b):
        return False
    if not st.act("unstack", b, st.support[b]):
        return False
    return st.act("putdown", b)


def is_above(st, b, t):
    cur = st.support[b]
    while cur is not None and cur != "T":
        if cur == t:
            return True
        cur = st.support[cur]
    return False


def move_onto(st, b, t):
    if b == t:
        return True

    if st.support[b] == t:
        return clear_above(st, b)

    if st.held == t:
        if not st.act("putdown", t):
            return False

    if is_above(st, b, t):
        if not clear_above(st, b):
            return False
        if st.support[b] != "T":
            if not st.act("unstack", b, st.support[b]):
                return False
            if not st.act("putdown", b):
                return False
        if not clear_above(st, t):
            return False
    else:
        if not clear_above(st, t):
            return False

    if st.held == b:
        return st.act("stack", b, t)

    if st.support[b] == "T":
        if not clear_above(st, b):
            return False
        if not st.act("pickup", b):
            return False
        return st.act("stack", b, t)

    if not clear_above(st, b):
        return False
    if not st.act("unstack", b, st.support[b]):
        return False
    return st.act("stack", b, t)


def main():
    initial_support = {
        'a': 'T', 'b': 'a', 'c': 'b',
        'd': 'T', 'e': 'd', 'f': 'e',
        'g': 'T', 'h': 'T', 'i': 'T', 'j': 'T',
        'k': 'T', 'l': 'T', 'm': 'T', 'n': 'T',
        'o': None,
    }

    goal_support = {
        'a': 'T', 'b': 'T', 'c': 'T', 'd': 'T', 'e': 'T', 'f': 'T', 'g': 'T',
        'h': 'i', 'i': 'j', 'j': 'T',
        'k': 'l', 'l': 'm', 'm': 'n', 'n': 'o', 'o': 'T',
    }

    st = State(initial_support, 'o')

    # Additional constraint: the hand initially holds block o.
    if st.held is not None and not st.act("putdown", st.held):
        print("No plan")
        return

    goal_above = {b: [] for b in BLOCKS}
    for b, s in goal_support.items():
        if s != "T":
            goal_above[s].append(b)

    stacks = []
    for b in BLOCKS:
        if goal_support[b] == "T":
            stack = [b]
            cur = b
            while goal_above[cur]:
                cur = goal_above[cur][0]
                stack.append(cur)
            stacks.append(stack)

    # Build longer goal stacks first.
    stacks.sort(key=lambda x: -len(x))

    ok = True
    for stack in stacks:
        if not move_to_table(st, stack[0]):
            ok = False
            break
        for below, above_block in zip(stack, stack[1:]):
            if not move_onto(st, above_block, below):
                ok = False
                break
        if not ok:
            break

    if ok and st.held is None and all(st.support[b] == goal_support[b] for b in BLOCKS):
        print("\n".join(st.plan))
    else:
        print("No plan")


if __name__ == "__main__":
    main()

TABLE = "table"
BLOCKS = [f"block{i}" for i in range(1, 13)]

GOAL_SUPPORT = {
    "block1": "block8",
    "block2": TABLE,
    "block3": "block2",
    "block4": "block7",
    "block5": "block10",
    "block6": TABLE,
    "block7": "block3",
    "block8": "block12",
    "block9": "block6",
    "block10": "block1",
    "block11": "block4",
    "block12": "block11",
}

INITIAL_SUPPORT = {b: TABLE for b in BLOCKS}

BUILD_ORDER = [
    "block6", "block9",
    "block2", "block3", "block7", "block4",
    "block11", "block12", "block8", "block1",
    "block10", "block5",
]


def chain(support, x):
    if support.get(x) is None:
        return None
    res = [x]
    cur = x
    while support[cur] != TABLE:
        cur = support[cur]
        if cur is None or cur not in support:
            return None
        res.append(cur)
    res.append(TABLE)
    res.reverse()
    return res


def is_clear(support, x):
    return all(support[b] != x for b in BLOCKS)


def in_place(support, x, goal_chain):
    return chain(support, x) == goal_chain[x]


def solve():
    support = dict(INITIAL_SUPPORT)
    actions = []

    goal_chain = {}
    for b in BLOCKS:
        res = [b]
        cur = b
        while GOAL_SUPPORT[cur] != TABLE:
            cur = GOAL_SUPPORT[cur]
            res.append(cur)
        res.append(TABLE)
        res.reverse()
        goal_chain[b] = res

    goal_depth = {b: len(goal_chain[b]) - 1 for b in BLOCKS}

    while True:
        moved = False
        for x in sorted(BLOCKS, key=lambda b: goal_depth[b], reverse=True):
            if support[x] != TABLE and support[x] is not None and not in_place(support, x, goal_chain):
                if is_clear(support, x):
                    y = support[x]
                    support[x] = TABLE
                    actions.append(f"(unstack {x} {y})")
                    actions.append(f"(putdown {x})")
                    moved = True
                    break
        if not moved:
            break

    for x in BUILD_ORDER:
        if in_place(support, x, goal_chain):
            continue
        if not is_clear(support, x):
            return None

        if support[x] == TABLE:
            support[x] = None
            actions.append(f"(pickup {x})")
        else:
            y = support[x]
            support[x] = None
            actions.append(f"(unstack {x} {y})")

        if GOAL_SUPPORT[x] == TABLE:
            support[x] = TABLE
            actions.append(f"(putdown {x})")
        else:
            target = GOAL_SUPPORT[x]
            if not is_clear(support, target):
                return None
            support[x] = target
            actions.append(f"(stack {x} {target})")

    if all(support[b] == GOAL_SUPPORT[b] for b in BLOCKS):
        return actions
    return None


def main():
    plan = solve()
    if plan is None:
        print("No plan")
    else:
        print("\n".join(plan))


