from collections import deque

TABLE = 0
HELD = -1
N = 6

INITIAL_LOC = (TABLE, 5, 3, TABLE, TABLE, TABLE)
GOAL_LOC = (TABLE, TABLE, TABLE, 2, TABLE, TABLE)


def is_clear(loc, b):
    return all(loc[i] != b for i in range(N))


def is_goal(state):
    loc, arm, _ = state
    return arm == HELD and loc == GOAL_LOC


def successors(state, restrict):
    loc, arm, locked = state
    loc = list(loc)

    if arm == HELD:
        for b in range(N):
            if loc[b] == TABLE and is_clear(loc, b):
                new_loc = loc[:]
                new_loc[b] = HELD
                yield (tuple(new_loc), b, locked), f"(pickup block{b + 1})"

        if not (restrict and locked):
            for b in range(N):
                if b in locked:
                    continue
                for c in range(N):
                    if loc[b] == c and is_clear(loc, b):
                        new_loc = loc[:]
                        new_loc[b] = HELD
                        yield (tuple(new_loc), b, locked), f"(unstack block{b + 1} block{c + 1})"
    else:
        b = arm

        new_loc = loc[:]
        new_loc[b] = TABLE
        yield (tuple(new_loc), HELD, locked), f"(putdown block{b + 1})"

        for c in range(N):
            if loc[c] != HELD and is_clear(loc, c):
                new_loc = loc[:]
                new_loc[b] = c
                yield (tuple(new_loc), HELD, locked | {b}), f"(stack block{b + 1} block{c + 1})"


def solve(restrict):
    start = (INITIAL_LOC, HELD, frozenset())
    parent = {start: (None, None)}
    queue = deque([start])

    while queue:
        state = queue.popleft()

        if is_goal(state):
            plan = []
            while state != start:
                prev, action = parent[state]
                plan.append(action)
                state = prev
            plan.reverse()
            return plan

        for next_state, action in successors(state, restrict):
            if next_state not in parent:
                parent[next_state] = (state, action)
                queue.append(next_state)

    return None


def main():
    plan = solve(True)
    if plan is None:
        plan = solve(False)

    if plan is None:
        print("No plan")
    else:
        print("\n".join(plan))


if __name__ == "__main__":
    main()

def main():
    blocks = list(range(1, 14))

    initial_on = {
        1: None,
        2: None,
        3: None,
        4: None,
        5: None,
        6: None,
        7: 10,
        8: None,
        9: 3,
        10: 12,
        11: None,
        12: None,
        13: 7,
    }

    initial_above = {b: None for b in blocks}
    for b, s in initial_on.items():
        if s is not None:
            initial_above[s] = b

    goal_on = {
        13: None,
        3: 13,
        2: 3,
        4: 2,
        12: 4,
        11: None,
        6: 11,
        7: 6,
        8: 7,
        10: None,
        1: 10,
        5: 1,
        9: 5,
    }

    on = initial_on.copy()
    above = initial_above.copy()
    holding = None
    plan = []

    def name(b):
        return f"block{b}"

    def emit(action):
        plan.append(action)

    def pickup(b):
        nonlocal holding
        if holding is not None or on[b] is not None or above[b] is not None:
            raise RuntimeError
        holding = b
        emit(("pickup", b))

    def putdown(b):
        nonlocal holding
        if holding != b:
            raise RuntimeError
        holding = None
        on[b] = None
        emit(("putdown", b))

    def unstack(x, y):
        nonlocal holding
        if holding is not None or on[x] != y or above[x] is not None:
            raise RuntimeError
        holding = x
        on[x] = None
        above[y] = None
        emit(("unstack", x, y))

    def stack(x, y):
        nonlocal holding
        if holding != x or above[y] is not None:
            raise RuntimeError
        holding = None
        on[x] = y
        above[y] = x
        emit(("stack", x, y))

    def clear_block(b):
        while above[b] is not None:
            top = above[b]
            move_to_table(top)

    def move_to_table(b):
        if holding is not None:
            raise RuntimeError
        if on[b] is None:
            return
        clear_block(b)
        if on[b] is None:
            pickup(b)
        else:
            y = on[b]
            unstack(b, y)
        putdown(b)

    def move_onto(b, target):
        if target is None:
            move_to_table(b)
            return
        if on[b] == target and holding is None:
            clear_block(b)
            return
        clear_block(b)
        clear_block(target)
        if on[b] is None:
            pickup(b)
        else:
            y = on[b]
            unstack(b, y)
        stack(b, target)

    goal_stacks = [
        [13, 3, 2, 4, 12],
        [11, 6, 7, 8],
        [10, 1, 5, 9],
    ]

    def valid_plan(actions):
        on_v = initial_on.copy()
        above_v = initial_above.copy()
        holding_v = None

        for action in actions:
            if action[0] == "pickup":
                b = action[1]
                if holding_v is not None or on_v[b] is not None or above_v[b] is not None:
                    return False
                holding_v = b
            elif action[0] == "putdown":
                b = action[1]
                if holding_v != b:
                    return False
                holding_v = None
                on_v[b] = None
            elif action[0] == "unstack":
                x, y = action[1], action[2]
                if holding_v is not None or on_v[x] != y or above_v[x] is not None:
                    return False
                holding_v = x
                on_v[x] = None
                above_v[y] = None
            elif action[0] == "stack":
                x, y = action[1], action[2]
                if holding_v != x or above_v[y] is not None:
                    return False
                holding_v = None
                on_v[x] = y
                above_v[y] = x
            else:
                return False

        if holding_v is not None:
            return False
        return all(on_v[b] == goal_on[b] for b in blocks)

    def format_action(action):
        if action[0] in ("pickup", "putdown"):
            return f"({action[0]} {name(action[1])})"
        return f"({action[0]} {name(action[1])} {name(action[2])})"

    try:
        for st in goal_stacks:
            for i, b in enumerate(st):
                target = None if i == 0 else st[i - 1]
                move_onto(b, target)

        if valid_plan(plan):
            print("\n".join(format_action(a) for a in plan))
        else:
            print("No plan")
    except Exception:
        print("No plan")


if __name__ == "__main__":
    main()

