GOAL_LOCS[4] = 9
GOAL_LOCS[7] = 4
GOAL_LOCS = tuple(GOAL_LOCS)

TRIGGER = 1
REQUIRED = 2
HORIZON = 4


def is_clear(locs, b):
    for x in BLOCKS:
        if locs[x] == b:
