def next_rem(rem, moved):
    if rem > 0:
        if moved == REQUIRED:
            rem = 0
        else:
            rem -= 1
            if rem == 0:
                return None

    if moved == TRIGGER:
        rem = HORIZON if rem == 0 else min(rem, HORIZON)

    return rem


def successors(state):
    locs, arm, rem = state

    if arm == 0:
        for b in BLOCKS:
            if locs[b] == 0 and is_clear(locs, b):
                nr = next_rem(rem, b)
                if nr is not None:
                    yield (locs, b, nr), f"(pickup block{b})"

    if arm != 0:
        b = arm

        nr = next_rem(rem, b)
        if nr is not None:
            yield (locs, 0, nr), f"(putdown block{b})"

        for c in BLOCKS:
            if c != b and is_clear(locs, c):
                nl = list(locs)
                nl[b] = c
                nr = next_rem(rem, b)
                if nr is not None:
                    yield (tuple(nl), 0, nr), f"(stack block{b} block{c})"

    if arm == 0:
        for b in BLOCKS:
            c = locs[b]
            if c != 0 and is_clear(locs, b):
                nl = list(locs)
                nl[b] = 0
                nr = next_rem(rem, b)
                if nr is not None:
                    yield (tuple(nl), b, nr), f"(unstack block{b} block{c})"


def heuristic(locs):
    return sum(1 for b in BLOCKS if locs[b] != GOAL_LOCS[b])


def solve():
    if (INITIAL_LOCS[TRIGGER] != GOAL_LOCS[TRIGGER] and
            GOAL_LOCS[TRIGGER] == REQUIRED and
            HORIZON > 0):
        print("No plan")
        return

    start = (INITIAL_LOCS, 0, 0)
    if start[0] == GOAL_LOCS and start[2] == 0:
        return

    counter = 0
    heap = [(heuristic(start[0]), 0, counter, start, [])]
    best = {start: 0}

    while heap:
        f, g, _, state, actions = heapq.heappop(heap)
        if g != best.get(state, -1):
            continue

        locs, arm, rem = state
        if locs == GOAL_LOCS and arm == 0 and rem == 0:
            print("\n".join(actions))
            return

        for ns, act in successors(state):
            ng = g + 1
            if ng < best.get(ns, 10**9):
                best[ns] = ng
                counter += 1
                heapq.heappush(
                    heap,
                    (ng + heuristic(ns[0]), ng, counter, ns, actions + [act])
                )

    print("No plan")


if __name__ == "__main__":
    solve()

def main():
    blocks = list('abcdefghijklmno')

    initial = {
        'a': 'table', 'b': 'a', 'c': 'b',
        'd': 'table', 'e': 'd', 'f': 'e',
        'g': 'table', 'h': 'table', 'i': 'table',
        'j': 'table', 'k': 'table', 'l': 'table',
        'm': 'table', 'n': 'table', 'o': 'table'
    }

    goal = {
        'a': 'table', 'b': 'table', 'c': 'table',
        'd': 'table', 'e': 'table', 'f': 'table',
        'g': 'table', 'h': 'j', 'i': 'h',
        'j': 'table', 'k': 'l', 'l': 'm',
        'm': 'n', 'n': 'o', 'o': 'table'
    }

    def valid_state(loc):
        for b in blocks:
            if loc[b] != 'table' and loc[b] not in blocks:
                return False

        top_count = {}
        for b in blocks:
            if loc[b] != 'table':
                top_count[loc[b]] = top_count.get(loc[b], 0) + 1
                if top_count[loc[b]] > 1:
                    return False

        for b in blocks:
            seen = set()
            cur = b
            while cur != 'table':
                if cur in seen:
                    return False
                seen.add(cur)
                cur = loc[cur]

        return True

    if not valid_state(initial) or not valid_state(goal):
        print('No plan')
        return

    def depth(loc, b):
        d = 0
        cur = b
        while loc[cur] != 'table':
            d += 1
            cur = loc[cur]
        return d

    plan = []

    for b in sorted((b for b in blocks if initial[b] != 'table'),
                    key=lambda x: -depth(initial, x)):
        plan.append(('unstack', b, initial[b]))
        plan.append(('putdown', b))

    child = {}
    for b in blocks:
        if goal[b] != 'table':
            child[goal[b]] = b

    for base in blocks:
        if goal[base] != 'table':
            continue

        tower = [base]
        cur = base
        while cur in child:
            cur = child[cur]
            tower.append(cur)

        for lower, upper in zip(tower, tower[1:]):
            plan.append(('pickup', upper))
            plan.append(('stack', upper, lower))

    loc = dict(initial)
    holding = None

    def clear(x):
        return not any(loc[z] == x for z in blocks)

    ok = True
    for action in plan:
        if action[0] == 'pickup':
            x = action[1]
            if holding is not None or loc[x] != 'table' or not clear(x):
                ok = False
                break
            loc[x] = 'held'
            holding = x

        elif action[0] == 'putdown':
            x = action[1]
            if holding != x:
                ok = False
                break
            loc[x] = 'table'
            holding = None

        elif action[0] == 'unstack':
            x, y = action[1], action[2]
            if holding is not None or loc[x] != y or not clear(x):
                ok = False
                break
            loc[x] = 'held'
            holding = x

        elif action[0] == 'stack':
            x, y = action[1], action[2]
            if holding != x or loc[y] == 'held' or not clear(y):
                ok = False
                break
            loc[x] = y
            holding = None

        else:
            ok = False
            break

    if ok and holding is None and all(loc[b] == goal[b] for b in blocks):
        for action in plan:
            print(f"({action[0]} {' '.join(action[1:])})")
    else:
        print('No plan')


