# Formalization:
# - support[b] is the entity directly below block b: "table" or another block.
# - A block is clear iff no block has support equal to it.
# - Actions:
#     (pickup X)    requires X on table and clear
#     (putdown X)   requires X held
#     (unstack X Y) requires X on Y and clear
#     (stack X Y)   requires X held and Y clear
# - Additional constraint: no block may be placed on top of block4,
#   i.e. no valid state may contain support[X] == "block4".

class PlanFailed(Exception):
    pass


def main():
    TABLE = "table"
    blocks = [f"block{i}" for i in range(1, 14)]
    fragile = "block4"

    initial_support = {
        "block11": TABLE,
        "block5": TABLE,
        "block6": TABLE,
        "block12": TABLE,
        "block3": TABLE,
        "block10": "block12",
        "block7": "block10",
        "block13": "block7",
        "block9": "block3",
        "block1": TABLE,
        "block8": TABLE,
        "block2": TABLE,
        "block4": TABLE,
    }

    goal_support = {
        "block13": TABLE,
        "block3": "block13",
        "block2": "block3",
        "block4": "block2",
        "block12": "block4",
        "block11": TABLE,
        "block6": "block11",
        "block7": "block6",
        "block8": "block7",
        "block10": TABLE,
        "block1": "block10",
        "block5": "block1",
        "block9": "block5",
    }

    # The goal itself must satisfy the fragile constraint.
    # Here the goal requires block12 on block4, which is forbidden.
    for b, s in goal_support.items():
        if s == fragile:
            print("No plan")
            return

    support = dict(initial_support)
    actions = []

    def above(b):
        return [x for x in blocks if support[x] == b]

    def is_clear(b):
        return not above(b)

    def can_place(b, target):
        if b == target:
            return False
        if target == fragile:
            return False
        return True

    def move_to_table(b):
        if support[b] is None:
            return

        for x in list(above(b)):
            move_to_table(x)

        if support[b] == TABLE:
            return

        y = support[b]
        if not is_clear(b):
            raise PlanFailed()

        actions.append(f"(unstack {b} {y})")
        support[b] = None
        actions.append(f"(putdown {b})")
        support[b] = TABLE

    def move_to(b, target):
        if support[b] is None:
            raise PlanFailed()

        if support[b] == target:
            for x in list(above(b)):
                move_to_table(x)
            return

        for x in list(above(b)):
            if x == target:
                raise PlanFailed()
            move_to_table(x)

        if target != TABLE:
            if target == b:
                raise PlanFailed()
            for x in list(above(target)):
                if x == b:
                    raise PlanFailed()
                move_to_table(x)

        if not can_place(b, target):
            raise PlanFailed()

        if support[b] == TABLE:
            actions.append(f"(pickup {b})")
            support[b] = None
        else:
            y = support[b]
            if not is_clear(b):
                raise PlanFailed()
            actions.append(f"(unstack {b} {y})")
            support[b] = None

        if target == TABLE:
            actions.append(f"(putdown {b})")
            support[b] = TABLE
        else:
            if not is_clear(target):
                raise PlanFailed()
            actions.append(f"(stack {b} {target})")
            support[b] = target

    try:
        # Clear all stacks by moving every block to the table.
        for b in blocks:
            move_to_table(b)

        # Build each goal stack from bottom to top.
        goal_stacks = []
        for b in blocks:
            if goal_support[b] == TABLE:
                stack = [b]
                cur = b
                seen = {b}
                while True:
                    nexts = [x for x in blocks if goal_support[x] == cur]
                    if not nexts:
                        break
                    if len(nexts) > 1 or nexts[0] in seen:
                        raise PlanFailed()
                    cur = nexts[0]
                    seen.add(cur)
                    stack.append(cur)
                goal_stacks.append(stack)

        if sum(len(s) for s in goal_stacks) != len(blocks):
            raise PlanFailed()

        for stack in goal_stacks:
            for i, b in enumerate(stack):
                target = TABLE if i == 0 else stack[i - 1]
                move_to(b, target)

        # Final verification of the goal and the fragile constraint.
        for b in blocks:
            if support[b] != goal_support[b]:
                raise PlanFailed()
            if support[b] == fragile:
                raise PlanFailed()

        for action in actions:
            print(action)

    except PlanFailed:
        print("No plan")


if __name__ == "__main__":
    main()

import sys
from collections import deque

N = 6
BLOCKS = tuple(range(1, N + 1))


def is_clear(state, b):
    for i in BLOCKS:
        if state[i] == b:
            return False
    return True


def apply_action(state, action):
    a = action[0]
    arm = state[0]
    loc = list(state)

    if a == 'pickup':
        x = action[1]
        if arm != 0 or loc[x] != 0 or not is_clear(state, x):
            return None
        loc[0] = x
        loc[x] = -1

    elif a == 'unstack':
        x, y = action[1], action[2]
        if arm != 0 or loc[x] != y or not is_clear(state, x):
            return None
        loc[0] = x
        loc[x] = -1

    elif a == 'putdown':
        x = action[1]
        if arm != x or loc[x] != -1:
            return None
        loc[0] = 0
        loc[x] = 0

    elif a == 'stack':
        x, y = action[1], action[2]
        if arm != x or loc[x] != -1 or y == x or loc[y] == -1 or not is_clear(state, y):
            return None
        loc[x] = y
        loc[0] = 0

    else:
        return None

    return tuple(loc)


def generate_actions(state):
    arm = state[0]
    actions = []

    if arm == 0:
        for x in BLOCKS:
            support = state[x]
            if support != 0 and support != -1 and is_clear(state, x):
                actions.append(('unstack', x, support))

        for x in BLOCKS:
            if state[x] == 0 and is_clear(state, x):
                actions.append(('pickup', x))

    else:
        x = arm
        for y in BLOCKS:
            if y != x and state[y] != -1 and is_clear(state, y):
                actions.append(('stack', x, y))
        actions.append(('putdown', x))

    return actions


def format_action(action):
    a = action[0]
    if a == 'pickup' or a == 'putdown':
        return f"({a} block{action[1]})"
    return f"({a} block{action[1]} block{action[2]})"


def solve():
    initial = (0, 4, 1, 0, 5, 6, 3)
    goal = (0, 0, 0, 4, 0, 0, 2)

    q = deque([initial])
    parent = {initial: None}

    while q:
        state = q.popleft()

        if state == goal:
            plan = []
            cur = state
            while parent[cur] is not None:
                prev, action = parent[cur]
                plan.append(action)
                cur = prev
            plan.reverse()
            sys.stdout.write("\n".join(format_action(a) for a in plan))
            return

        for action in generate_actions(state):
            nxt = apply_action(state, action)
            if nxt is not None and nxt not in parent:
                parent[nxt] = (state, action)
                q.append(nxt)

    sys.stdout.write("No plan")


if __name__ == "__main__":
    solve()

import heapq

# Blocks are numbered 0..9, corresponding to block1..block10.
# A state is a tuple loc where loc[b] is:
#   -1 (TABLE) if block b is on the table, or
#   the id of the block directly below b.
# A "move" is a complete support change of one clear block.
# Additional constraint:
#   after moving block2 (id 1), the next move must be block4 (id 3);
#   after moving block4 (id 3), the next move must be block6 (id 5).

TABLE = -1
N = 10

INITIAL = (TABLE,) * N
GOAL = (
    TABLE,  # block1 on table
    8,      # block2 on block9
    TABLE,  # block3 on table
    TABLE,  # block4 on table
    TABLE,  # block5 on table
    4,      # block6 on block5
    5,      # block7 on block6
    3,      # block8 on block4
    2,      # block9 on block3
    0,      # block10 on block1
)

BLOCK2, BLOCK4, BLOCK6 = 1, 3, 5


def next_required(block):
    if block == BLOCK2:
        return BLOCK4
    if block == BLOCK4:
        return BLOCK6
    return -1


def is_clear(loc, block):
    return all(v != block for v in loc)


def has_correct_block_on(loc, base):
    for z in range(N):
        if loc[z] == base and loc[z] == GOAL[z]:
            return True
    return False


def heuristic(loc, req):
    misplaced = sum(1 for i in range(N) if loc[i] != GOAL[i])

    extra = 0
    # If block2 still needs to move, block4 and block6 will later have to be
    # clear.  Correctly placed blocks sitting on them must be moved at least once.
    if loc[BLOCK2] != GOAL[BLOCK2]:
        if has_correct_block_on(loc, BLOCK4):
            extra += 1
        if has_correct_block_on(loc, BLOCK6):
            extra += 1

    if req == BLOCK4:
        if has_correct_block_on(loc, BLOCK4):
            extra += 1
        if has_correct_block_on(loc, BLOCK6):
            extra += 1
    if req == BLOCK6:
        if has_correct_block_on(loc, BLOCK6):
            extra += 1

    pending = 0
    if req == BLOCK4:
        pending = 2  # move block4, then block6
    elif req == BLOCK6:
        pending = 1  # move block6

    return max(misplaced + extra, pending)


def penalty(loc, req):
    # Tie-breaker only: avoid states where a forced move is blocked.
    p = 0
    if req == BLOCK4:
        if any(v == BLOCK4 for v in loc):
            p += 1000
        if any(v == BLOCK6 for v in loc):
            p += 100
    if req == BLOCK6:
        if any(v == BLOCK6 for v in loc):
            p += 1000

    if loc[BLOCK2] != GOAL[BLOCK2]:
        if any(v == BLOCK4 for v in loc):
            p += 10
        if any(v == BLOCK6 for v in loc):
            p += 10

    return p


def a_star(limit=10000):
    start = (INITIAL, -1)
    h0 = heuristic(INITIAL, -1)
    p0 = penalty(INITIAL, -1)

    heap = [(h0, 0, p0, 0, INITIAL, -1)]
    best = {start: 0}
    parent = {}
    counter = 1
    expansions = 0
    INF = 10**9

    while heap:
        f, g, p, _, loc, req = heapq.heappop(heap)
        state = (loc, req)

        if g != best.get(state):
            continue

        if loc == GOAL and req == -1:
            actions = []
            cur = state
            while cur in parent:
                prev, act = parent[cur]
                actions.append(act)
                cur = prev
            actions.reverse()
            return actions

        expansions += 1
        if expansions > limit:
            return None

        successors = []

        for x in range(N):
            if req != -1 and x != req:
                continue
            if not is_clear(loc, x):
                continue

            s = loc[x]

            # Move to table, if this is a real support change.
            if s != TABLE:
                new_loc = list(loc)
                new_loc[x] = TABLE
                new_state = (tuple(new_loc), next_required(x))
                ng = g + 1
                if ng < best.get(new_state, INF):
                    h = heuristic(new_state[0], new_state[1])
                    pn = penalty(new_state[0], new_state[1])
                    fix = 0 if new_loc[x] == GOAL[x] else 1
                    away = 0 if loc[x] == GOAL[x] else 1
                    successors.append((h, pn, fix, away, x, s, TABLE, new_state, ng))

            # Move onto another clear block.
            for t in range(N):
                if t == x or t == s:
                    continue
                if not is_clear(loc, t):
                    continue

                new_loc = list(loc)
                new_loc[x] = t
                new_state = (tuple(new_loc), next_required(x))
                ng = g + 1
                if ng < best.get(new_state, INF):
                    h = heuristic(new_state[0], new_state[1])
                    pn = penalty(new_state[0], new_state[1])
                    fix = 0 if new_loc[x] == GOAL[x] else 1
                    away = 0 if loc[x] == GOAL[x] else 1
                    successors.append((h, pn, fix, away, x, s, t, new_state, ng))

        successors.sort()

        for h, pn, fix, away, x, s, t, new_state, ng in successors:
            if ng < best.get(new_state, INF):
                best[new_state] = ng
                parent[new_state] = (state, (x, s, t))
                counter += 1
                heapq.heappush(
                    heap,
                    (ng + h, ng, pn, counter, new_state[0], new_state[1]),
                )

    return None


def verify_macro(actions):
    loc = list(INITIAL)
    req = -1

    for x, s, t in actions:
        if req != -1 and x != req:
            return False
        if s != loc[x]:
            return False
        if s == t:
            return False
        if not is_clear(loc, x):
            return False
        if t != TABLE and not is_clear(loc, t):
            return False

        loc[x] = t
        req = next_required(x)

    return tuple(loc) == GOAL and req == -1


def constructive_plan():
    # Fallback / direct construction:
    # block9 -> block3
    # block4 -> block1 temporarily, forcing block6 -> block10 temporarily
    # block2 -> block9, forcing block4 -> table, then block6 -> block5
    # finish the remaining goal stacks.
    loc = list(INITIAL)
    req = -1
    actions = []

    def do_move(x, t):
        nonlocal req
        if req != -1 and x != req:
            return False
        s = loc[x]
        if s == t:
            return False
        if not is_clear(loc, x):
            return False
        if t != TABLE and not is_clear(loc, t):
            return False

        loc[x] = t
        req = next_required(x)
        actions.append((x, s, t))
        return True

    sequence = [
        (8, 2),      # block9 on block3
        (3, 0),      # block4 on block1
        (5, 9),      # block6 on block10
        (1, 8),      # block2 on block9
        (3, TABLE),  # block4 back to table
        (5, 4),      # block6 on block5
        (6, 5),      # block7 on block6
        (7, 3),      # block8 on block4
        (9, 0),      # block10 on block1
    ]

    for x, t in sequence:
        if not do_move(x, t):
            return None

    if tuple(loc) != GOAL or req != -1:
        return None

    return actions


def expand_plan(actions):
    names = [f"block{i + 1}" for i in range(N)]
    lines = []

    for x, s, t in actions:
        if s == TABLE:
            lines.append(f"(pickup {names[x]})")
        else:
            lines.append(f"(unstack {names[x]} {names[s]})")

        if t == TABLE:
            lines.append(f"(putdown {names[x]})")
        else:
            lines.append(f"(stack {names[x]} {names[t]})")

    return lines


def main():
    plan = None
    try:
        plan = a_star(limit=10000)
    except Exception:
        plan = None

    if plan is None or not verify_macro(plan):
        plan = constructive_plan()

    if plan is None or not verify_macro(plan):
        print("No plan")
    else:
        print("\n".join(expand_plan(plan)))


if __name__ == "__main__":
    main()

import heapq
from collections import Counter

# Formalization:
# State variables:
#   arm: -1 for empty, or 0..11 for the held block index
#   pos[i]: TABLE, HELD, or the index of the block directly below block i
#
# Valid-state constraints:
#   - If arm == i, then pos[i] == HELD.
#   - At most one block can be directly on top of any block.
#   - A block can be picked up or unstacked only if it is clear.
#   - A block can be stacked only onto a clear, non-held block.
#
# Goal constraints from the text:
#   block3 on table, block11 on block3, block10 on block11, block7 on block10
#   block4 on table
#   block5 on table, block12 on block5
#   block1 on table
#   block2 on table, block9 on block2, block8 on block9
#   block6 on table
#
# Additional constraint:
#   The plan must end with the arm holding block1.

N = 12
TABLE = -1
HELD = -2

names = [f"block{i}" for i in range(1, N + 1)]


def main():
    # Initial arrangement.
    init_pos = [TABLE] * N

    def set_table(b):
        init_pos[b - 1] = TABLE

    def set_on(a, b):
        init_pos[a - 1] = b - 1

    set_table(8)
    set_table(10)
    set_on(9, 10)
    set_on(2, 9)
    set_on(1, 2)
    set_on(11, 1)
    set_on(12, 11)
    set_on(5, 12)
    set_on(6, 5)
    set_table(4)
    set_table(7)
    set_on(3, 7)

    initial_state = (-1, tuple(init_pos))

    # Goal arrangement, 1-based as in the statement.
    goal_table = [3, 4, 5, 1, 2, 6]
    goal_on = [
        (11, 3),
        (10, 11),
        (7, 10),
        (12, 5),
        (9, 2),
        (8, 9),
    ]

    # Additional final-state constraint: hold block1.
    FINAL_ARM = 1  # 1-based

    goal_table_idx = [b - 1 for b in goal_table]
    goal_on_idx = [(t - 1, s - 1) for t, s in goal_on]
    goal_table_set = set(goal_table_idx)

    top_counts = Counter(t for t, _ in goal_on_idx)
    support_counts = Counter(s for _, s in goal_on_idx)

    inconsistent = False

    # Basic goal-consistency checks.
    if any(c > 1 for c in top_counts.values()):
        inconsistent = True
    if any(c > 1 for c in support_counts.values()):
        inconsistent = True
    if goal_table_set & set(top_counts):
        inconsistent = True
    for t, s in goal_on_idx:
        if t == s:
            inconsistent = True

    goal_support = [None] * N
    for i in goal_table_idx:
        goal_support[i] = TABLE
    for t, s in goal_on_idx:
        goal_support[t] = s

    # A finally held block cannot also be required on the table,
    # on another block, or supporting another block.
    if FINAL_ARM is not None:
        fa = FINAL_ARM - 1
        if goal_support[fa] is not None and goal_support[fa] != HELD:
            inconsistent = True
        if fa in goal_table_set:
            inconsistent = True
        if fa in top_counts:
            inconsistent = True
        if fa in support_counts:
            inconsistent = True
        if not inconsistent:
            goal_support[fa] = HELD

    if FINAL_ARM is not None:
        if sum(1 for gs in goal_support if gs == HELD) != 1:
            inconsistent = True
    else:
        if any(gs == HELD for gs in goal_support):
            inconsistent = True

    if inconsistent:
        print("No plan")
        return

    final_arm_idx = FINAL_ARM - 1 if FINAL_ARM is not None else -1

    def min_move_count(cur, goal):
        """Admissible per-block lower bound on actions for this block."""
        if goal is None:
            return 0
        if cur == goal:
            return 0
        if cur == HELD:
            return 1
        if goal == HELD:
            return 1
        if cur == TABLE:
            return 2
        if goal == TABLE:
            return 2
        return 2

    def heuristic(state):
        _, pos = state
        total = 0
        for i, gs in enumerate(goal_support):
            if gs is not None:
                total += min_move_count(pos[i], gs)
        return total

    def is_goal(state):
        arm, pos = state
        if arm != final_arm_idx:
            return False
        for i, gs in enumerate(goal_support):
            if gs is not None and pos[i] != gs:
                return False
        return True

    def successors(state):
        arm, pos = state

        top_of = [-1] * N
        for i, p in enumerate(pos):
            if p != TABLE and p != HELD:
                top_of[p] = i

        if arm == -1:
            for b in range(N):
                p = pos[b]
                if top_of[b] != -1:
                    continue

                if p == TABLE:
                    new_pos = list(pos)
                    new_pos[b] = HELD
                    yield ("pickup", b), (b, tuple(new_pos))
                elif p != HELD:
                    if pos[p] != HELD:
                        new_pos = list(pos)
                        new_pos[b] = HELD
                        yield ("unstack", b, p), (b, tuple(new_pos))
        else:
            b = arm

            new_pos = list(pos)
            new_pos[b] = TABLE
            yield ("putdown", b), (-1, tuple(new_pos))

            for c in range(N):
                if c == b:
                    continue
                if pos[c] == HELD:
                    continue
                if top_of[c] == -1:
                    new_pos = list(pos)
                    new_pos[b] = c
                    yield ("stack", b, c), (-1, tuple(new_pos))

    def astar(initial):
        h0 = heuristic(initial)
        counter = 0
        heap = [(h0, 0, counter, initial)]
        best = {initial: 0}
        parent = {}

        while heap:
            _, g, _, state = heapq.heappop(heap)

            if g != best.get(state, 10**18):
                continue

            if is_goal(state):
                plan = []
                while state in parent:
                    prev, action = parent[state]
                    plan.append(action)
                    state = prev
                plan.reverse()
                return plan

            for action, nstate in successors(state):
                ng = g + 1
                old = best.get(nstate)
                if old is None or ng < old:
                    best[nstate] = ng
                    parent[nstate] = (state, action)
                    h = heuristic(nstate)
                    counter += 1
                    heapq.heappush(heap, (ng + h, ng, counter, nstate))

        return None

    plan = astar(initial_state)

    if plan is None:
        print("No plan")
    else:
        for action in plan:
            parts = [action[0]] + [names[i] for i in action[1:]]
            print("(" + " ".join(parts) + ")")


