import heapq

N = 14
BLOCKS = [f"block{i}" for i in range(1, N + 1)]
IDX = {name: i for i, name in enumerate(BLOCKS)}
TABLE = -1
ARM = -2


def initial_state():
    pos = [TABLE] * N
    pos[IDX["block14"]] = IDX["block8"]
    return (tuple(pos), -1)


def goal_state():
    desired = [TABLE] * N
    for name in ("block4", "block6", "block14", "block8", "block9",
                 "block3", "block12", "block11", "block2", "block5", "block1"):
        desired[IDX[name]] = TABLE
    desired[IDX["block10"]] = IDX["block9"]
    desired[IDX["block7"]] = IDX["block2"]
    desired[IDX["block13"]] = IDX["block7"]
    return (tuple(desired), -1)


def clear_flags(pos):
    above = [0] * N
    for b, loc in enumerate(pos):
        if 0 <= loc < N:
            above[loc] += 1
    return [c == 0 for c in above]


def heuristic(pos, desired):
    h = 0
    for p, d in zip(pos, desired):
        if p == d:
            continue
        if p == ARM:
            h += 1
        else:
            h += 2
    return h


def solve():
    start = initial_state()
    goal = goal_state()
    desired = goal[0]

    if start == goal:
        return []

    h0 = heuristic(start[0], desired)
    counter = 0
    heap = [(h0, h0, 0, counter, start)]
    dist = {start: 0}
    parent = {}

    while heap:
        f, h, g, _, state = heapq.heappop(heap)

        if g > dist.get(state, 10**9):
            continue

        if state == goal:
            actions = []
            cur = state
            while cur in parent:
                prev, act = parent[cur]
                actions.append(act)
                cur = prev
            actions.reverse()
            return actions

        pos, arm = state
        clear = clear_flags(pos)

        if arm == -1:
            for b in range(N):
                if not clear[b]:
                    continue

                if pos[b] == TABLE:
                    npos = list(pos)
                    npos[b] = ARM
                    nstate = (tuple(npos), b)
                    act = ("pickup", (b,))
                    ng = g + 1

                    if ng < dist.get(nstate, 10**9):
                        dist[nstate] = ng
                        parent[nstate] = (state, act)
                        nh = heuristic(nstate[0], desired)
                        counter += 1
                        heapq.heappush(heap, (ng + nh, nh, ng, counter, nstate))

                elif 0 <= pos[b] < N:
                    y = pos[b]
                    npos = list(pos)
                    npos[b] = ARM
                    nstate = (tuple(npos), b)
                    act = ("unstack", (b, y))
                    ng = g + 1

                    if ng < dist.get(nstate, 10**9):
                        dist[nstate] = ng
                        parent[nstate] = (state, act)
                        nh = heuristic(nstate[0], desired)
                        counter += 1
                        heapq.heappush(heap, (ng + nh, nh, ng, counter, nstate))

        else:
            x = arm

            npos = list(pos)
            npos[x] = TABLE
            nstate = (tuple(npos), -1)
            act = ("putdown", (x,))
            ng = g + 1

            if ng < dist.get(nstate, 10**9):
                dist[nstate] = ng
                parent[nstate] = (state, act)
                nh = heuristic(nstate[0], desired)
                counter += 1
                heapq.heappush(heap, (ng + nh, nh, ng, counter, nstate))

            for y in range(N):
                if y == x or pos[y] == ARM:
                    continue
                if not clear[y]:
                    continue

                npos = list(pos)
                npos[x] = y
                nstate = (tuple(npos), -1)
                act = ("stack", (x, y))
                ng = g + 1

                if ng < dist.get(nstate, 10**9):
                    dist[nstate] = ng
                    parent[nstate] = (state, act)
                    nh = heuristic(nstate[0], desired)
                    counter += 1
                    heapq.heappush(heap, (ng + nh, nh, ng, counter, nstate))

    return None


def main():
    plan = solve()
    if plan is None:
        print("No plan")
    else:
        for action, args in plan:
            names = " ".join(BLOCKS[i] for i in args)
            print(f"({action} {names})")


