import heapq

N = 13
TABLE = 0
ARM = N + 1

def block_name(i):
    return f"block{i}"

initial_stacks = [
    [10, 13, 9, 1],
    [4, 7],
    [11],
    [5, 12],
    [8, 6, 3],
    [2],
]

goal_stacks = [
    [1, 6, 3, 9, 5],
    [13, 7],
    [11],
    [12, 10, 8, 2, 4],
]

def state_from_stacks(stacks):
    below = [TABLE] * (N + 1)
    on_top = [0] * (N + 1)
    for stack in stacks:
        if not stack:
            continue
        below[stack[0]] = TABLE
        for i in range(1, len(stack)):
            below[stack[i]] = stack[i - 1]
            on_top[stack[i - 1]] = stack[i]
    return (tuple(below), tuple(on_top))

initial_state = state_from_stacks(initial_stacks)
goal_state = state_from_stacks(goal_stacks)
goal_below = goal_state[0]

def get_holding(state):
    below = state[0]
    for b in range(1, N + 1):
        if below[b] == ARM:
            return b
    return 0

must_cache = {}

def must_move(state):
    if state in must_cache:
        return must_cache[state]

    below, _ = state
    must = [False] * (N + 1)

    for b in range(1, N + 1):
        if below[b] != goal_below[b] and below[b] != ARM:
            must[b] = True

    changed = True
    while changed:
        changed = False
        for b in range(1, N + 1):
            if not must[b]:
                s = below[b]
                if 1 <= s <= N and must[s]:
                    must[b] = True
                    changed = True

    mt = tuple(must)
    must_cache[state] = mt
    return mt

h_cache = {}

def heuristic(state):
    if state in h_cache:
        return h_cache[state]

    below, on_top = state
    must = must_move(state)
    h = 0

    for b in range(1, N + 1):
        c = below[b]
        g = goal_below[b]

        if c == ARM:
            if g == TABLE:
                h += 1
            else:
                s = g
                if 1 <= s <= N and below[s] == goal_below[s] and on_top[s] == 0 and not must[s]:
                    h += 1
                else:
                    h += 3
        else:
            if c == g:
                if must[b]:
                    h += 4
            else:
                h += 2

    h_cache[state] = h
    return h

def apply_action(state, act):
    below = list(state[0])
    on_top = list(state[1])
    name, x, y = act

    if name == "pickup":
        below[x] = ARM
    elif name == "putdown":
        below[x] = TABLE
    elif name == "unstack":
        on_top[y] = 0
        below[x] = ARM
    elif name == "stack":
        on_top[y] = x
        below[x] = y

    return (tuple(below), tuple(on_top))

def is_legal(state, act):
    below, on_top = state
    holding = get_holding(state)
    name, x, y = act

    if name == "pickup":
        return holding == 0 and 1 <= x <= N and below[x] == TABLE and on_top[x] == 0
    if name == "putdown":
        return holding == x
    if name == "unstack":
        return holding == 0 and 1 <= x <= N and 1 <= y <= N and below[x] == y and on_top[x] == 0
    if name == "stack":
        return holding == x and 1 <= y <= N and on_top[y] == 0 and below[y] != ARM
    return False

def action_str(act):
    name, x, y = act
    if name in ("pickup", "putdown"):
        return f"({name} {block_name(x)})"
    return f"({name} {block_name(x)} {block_name(y)})"

def action_priority(act):
    name, x, y = act
    if name == "putdown":
        return (0, 0, 0)
    if name == "unstack":
        return (0, 1, x)
    if name == "stack":
        return (0, 2, y)
    if name == "pickup":
        return (1, 0, x)
    return (2, 0, 0)

def successors(state):
    below, on_top = state
    holding = get_holding(state)
    actions = []

    if holding:
        actions.append(("putdown", holding, 0))
        for y in range(1, N + 1):
            if on_top[y] == 0 and below[y] != ARM:
                actions.append(("stack", holding, y))
    else:
        for b in range(1, N + 1):
            if on_top[b] == 0:
                if below[b] == TABLE:
                    actions.append(("pickup", b, 0))
                elif 1 <= below[b] <= N:
                    actions.append(("unstack", b, below[b]))

    unique_actions = []
    seen = set()
    for act in actions:
        if act not in seen:
            seen.add(act)
            unique_actions.append(act)

    scored = []
    for act in unique_actions:
        if not is_legal(state, act):
            continue
        new_state = apply_action(state, act)
        new_h = heuristic(new_state)
        scored.append((new_h, action_priority(act), new_state, act))

    scored.sort(key=lambda item: (item[0], item[1]))
    return [(new_state, act) for _, _, new_state, act in scored]

def astar():
    start = initial_state
    h0 = heuristic(start)
    counter = 0
    heap = [(h0, 0, counter, start)]
    g_score = {start: 0}
    parent = {start: None}
    expansions = 0
    max_expansions = 20000

    while heap:
        expansions += 1
        if expansions > max_expansions:
            return None

        _, neg_g, _, state = heapq.heappop(heap)
        g = -neg_g

        if g != g_score.get(state):
            continue

        if state == goal_state:
            path = []
            cur = state
            while parent[cur] is not None:
                prev, act = parent[cur]
                path.append(act)
                cur = prev
            path.reverse()
            return path

        for new_state, act in successors(state):
            new_g = g + 1
            if new_g < g_score.get(new_state, float("inf")):
                g_score[new_state] = new_g
                parent[new_state] = (state, act)
                nf = new_g + heuristic(new_state)
                counter += 1
                heapq.heappush(heap, (nf, -new_g, counter, new_state))

    return None

def trivial_plan():
    actions = []

    for stack in initial_stacks:
        for i in range(len(stack) - 1, 0, -1):
            actions.append(("unstack", stack[i], stack[i - 1]))
            actions.append(("putdown", stack[i]))

    for stack in goal_stacks:
        for i in range(1, len(stack)):
            actions.append(("pickup", stack[i]))
            actions.append(("stack", stack[i], stack[i - 1]))

    return actions

def verify(actions):
    state = initial_state
    for act in actions:
        if not is_legal(state, act):
            return False
        state = apply_action(state, act)
    return state == goal_state

def main():
    plan = astar()
    if plan is None or not verify(plan):
        plan = trivial_plan()

    if verify(plan):
        for act in plan:
            print(action_str(act))
    else:
        print("No plan")

if __name__ == "__main__":
    main()

def main():
    blocks = list(range(1, 16))

    # Initial state: support[x] = y means block x is on block y, or 0 if on table.
    initial_support = {
        5: 0, 2: 0, 12: 0, 1: 0, 14: 0, 3: 0, 11: 0, 7: 0, 10: 0, 9: 0, 6: 0,
        15: 2, 4: 15, 13: 1, 8: 13
    }

    # Explicit goal constraints from the text.
    required_on = [
        (5, 8), (15, 5), (6, 15), (4, 6),
        (11, 4), (10, 11), (3, 10), (14, 3),
        (9, 13), (12, 9), (1, 12), (2, 1)
    ]
    required_table = [7, 8, 13]

    # Additional constraints:
    # - exactly two stacks
    # - one stack contains only multiples of 3, the other contains none
    # - each stack is increasing from table to top
    # These uniquely determine the only possible final state.
    candidate = {}
    for stack in ([b for b in blocks if b % 3 == 0],
                  [b for b in blocks if b % 3 != 0]):
        prev = 0
        for b in stack:
            candidate[b] = prev
            prev = b

    def is_clear(support, x):
        return not any(z != x and support[z] == x for z in support)

    def validate(support):
        if set(support.keys()) != set(blocks):
            return False

        for x, y in support.items():
            if y == x:
                return False
            if y != 0 and y not in support:
                return False

        child_count = {}
        for x, y in support.items():
            child_count[y] = child_count.get(y, 0) + 1
        if any(c > 1 for c in child_count.values()):
            return False

        for x in blocks:
            seen = set()
            cur = x
            while cur != 0:
                if cur in seen:
                    return False
                seen.add(cur)
                cur = support[cur]

        if sum(1 for y in support.values() if y == 0) != 2:
            return False

        for x, y in support.items():
            if y != 0 and y >= x:
                return False

        roots = [x for x in blocks if support[x] == 0]
        children = {0: []}
        for x, y in support.items():
            children.setdefault(y, []).append(x)

        def stack_from(root):
            res = [root]
            cur = root
            while True:
                kids = children.get(cur, [])
                if not kids:
                    break
                cur = kids[0]
                res.append(cur)
            return res

        s1 = stack_from(roots[0])
        s2 = stack_from(roots[1])

        def all_mult(s):
            return all(b % 3 == 0 for b in s)

        def no_mult(s):
            return all(b % 3 != 0 for b in s)

        if not ((all_mult(s1) and no_mult(s2)) or (all_mult(s2) and no_mult(s1))):
            return False

        return True

    possible = validate(candidate)

    if possible:
        for x, y in required_on:
            if candidate.get(x) != y:
                possible = False
                break

        if possible:
            for x in required_table:
                if candidate.get(x) != 0:
                    possible = False
                    break

    if not possible:
        print("No plan")
        return

    def make_plan(initial, goal):
        actions = []
        support = dict(initial)

        # Dismantle all stacks to the table.
        while True:
            moved = None
            for x in blocks:
                y = support[x]
                if y != 0 and is_clear(support, x):
                    moved = (x, y)
                    break

            if moved is None:
                break

            x, y = moved
            actions.append(('unstack', x, y))
            support[x] = 0
            actions.append(('putdown', x))

        # Build the goal stacks from bottom to top.
        children = {0: []}
        for x, y in goal.items():
            children.setdefault(y, []).append(x)

        for root in children.get(0, []):
            prev = root
            while True:
                kids = children.get(prev, [])
                if not kids:
                    break
                x = kids[0]
                actions.append(('pickup', x))
                actions.append(('stack', x, prev))
                prev = x

        return actions

    plan = make_plan(initial_support, candidate)

    def simulate(actions, support, arm):
        support = dict(support)

        for a in actions:
            if a[0] == 'pickup':
                x = a[1]
                if arm != 0 or support[x] != 0 or not is_clear(support, x):
                    return None
                arm = x

            elif a[0] == 'putdown':
                x = a[1]
                if arm != x or support[x] != 0:
                    return None
                support[x] = 0
                arm = 0

            elif a[0] == 'stack':
                x, y = a[1], a[2]
                if arm != x or support[x] != 0:
                    return None
                if y not in support:
                    return None
                if not is_clear(support, y):
                    return None
                support[x] = y
                arm = 0

            elif a[0] == 'unstack':
                x, y = a[1], a[2]
                if arm != 0 or support[x] != y or not is_clear(support, x):
                    return None
                support[x] = 0
                arm = x

            else:
                return None

        if arm != 0:
            return None
        return support

    final = simulate(plan, initial_support, 0)
    if final is None or final != candidate or not validate(final):
        print("No plan")
        return

    for a in plan:
        if a[0] in ('stack', 'unstack'):
            print(f"({a[0]} block{a[1]} block{a[2]})")
        else:
            print(f"({a[0]} block{a[1]})")


if __name__ == "__main__":
    main()

import sys


def block_name(i):
    return f"block{i}"


def is_clear(b, below, n):
    for x in range(1, n + 1):
        if below[x] == b:
            return False
    return True


def apply_action(actions, below, arm, action, b, c=0, n=15):
    if action == "pickup":
        if arm != 0 or below[b] != 0 or not is_clear(b, below, n):
            return False
        below[b] = -1
        arm = b

    elif action == "unstack":
        if arm != 0 or c == 0 or below[b] != c or below[c] == -1 or not is_clear(b, below, n):
            return False
        below[b] = -1
        arm = b

    elif action == "putdown":
        if arm != b:
            return False
        below[b] = 0
        arm = 0

    elif action == "stack":
        if arm != b or c == 0 or b == c or below[c] == -1 or not is_clear(c, below, n):
            return False
        below[b] = c
        arm = 0

    else:
        return False

    if action in ("pickup", "putdown"):
        actions.append(f"({action} {block_name(b)})")
    else:
        actions.append(f"({action} {block_name(b)} {block_name(c)})")

    return True


def main():
    n = 15

    initial_stacks = [
        [6, 3, 5],
        [11],
        [14, 8, 7, 9, 4, 15, 12, 2, 13, 10],
        [1],
    ]

    goal_stacks = [
        [8, 7, 12, 5, 13],
        [15, 4],
        [3, 11, 2, 9, 14, 10, 6, 1],
    ]

    init_blocks = [b for s in initial_stacks for b in s]
    goal_blocks = [b for s in goal_stacks for b in s]

    if sorted(init_blocks) != list(range(1, n + 1)) or sorted(goal_blocks) != list(range(1, n + 1)):
        print("No plan")
        return

    below = [0] * (n + 1)
    for s in initial_stacks:
        below[s[0]] = 0
        for i in range(1, len(s)):
            below[s[i]] = s[i - 1]

    arm = 0
    actions = []

    while True:
        moved = False
        for b in range(1, n + 1):
            if below[b] != 0 and below[b] != -1 and is_clear(b, below, n):
                s = below[b]
                if not apply_action(actions, below, arm, "unstack", b, s, n):
                    print("No plan")
                    return
                if not apply_action(actions, below, arm, "putdown", b, 0, n):
                    print("No plan")
                    return
                moved = True
                break
        if not moved:
            break

    for s in goal_stacks:
        for i, b in enumerate(s):
            if i == 0:
                if below[b] != 0 or not is_clear(b, below, n):
                    print("No plan")
                    return
                continue

            support = s[i - 1]
            if (
                below[b] != 0
                or not is_clear(b, below, n)
                or below[support] == -1
                or not is_clear(support, below, n)
            ):
                print("No plan")
                return

            if not apply_action(actions, below, arm, "pickup", b, 0, n):
                print("No plan")
                return
            if not apply_action(actions, below, arm, "stack", b, support, n):
                print("No plan")
                return

    goal_below = [0] * (n + 1)
    for s in goal_stacks:
        for i, b in enumerate(s):
            goal_below[b] = 0 if i == 0 else s[i - 1]

    if arm != 0 or below != goal_below:
        print("No plan")
    else:
        sys.stdout.write("\n".join(actions))


