from collections import deque

BLOCKS = list(range(1, 9))

# support[b] is 0 for table, or the block directly below b.
# A held block has support 0 and is identified by holding.
initial_support = [0] * 9
initial_support[3] = 5
initial_support[6] = 3
initial_support[8] = 2
start = (tuple(initial_support), 0)

goal_support = {
    8: 0,
    7: 8,
    2: 7,
    4: 2,
    5: 4,
    3: 5,
    6: 0,
    1: 6,
}

# Additional constraint: the final state must have the arm holding block3.
goal_holding = 3


def goal_consistent(goal_support, goal_holding):
    # A held block cannot be specified as being on the table or on another block.
    if goal_holding != 0:
        if goal_holding in goal_support:
            return False
        for support in goal_support.values():
            if support == goal_holding:
                return False

    # A non-table block can have at most one block on top of it.
    top_count = {}
    for support in goal_support.values():
        if support != 0:
            top_count[support] = top_count.get(support, 0) + 1
            if top_count[support] > 1:
                return False

    # The specified support relation must be acyclic.
    for b in goal_support:
        cur = b
        seen = set()
        while cur in goal_support and goal_support[cur] != 0:
            if cur in seen:
                return False
            seen.add(cur)
            cur = goal_support[cur]
    return True


def is_clear(support, b, holding):
    if b == holding:
        return True
    for i in BLOCKS:
        if i != holding and support[i] == b:
            return False
    return True


def actions(state):
    support, holding = state

    if holding == 0:
        for b in BLOCKS:
            if support[b] == 0 and is_clear(support, b, holding):
                yield ("pickup", b), (support, b)

            for c in BLOCKS:
                if support[b] == c and is_clear(support, b, holding):
                    new_support = list(support)
                    new_support[b] = 0
                    yield ("unstack", b, c), (tuple(new_support), b)
    else:
        b = holding
        yield ("putdown", b), (support, 0)

        for c in BLOCKS:
            if c != b and is_clear(support, c, holding):
                new_support = list(support)
                new_support[b] = c
                yield ("stack", b, c), (tuple(new_support), 0)


def is_goal(state):
    support, holding = state

    if holding != goal_holding:
        return False

    if goal_holding != 0 and support[goal_holding] != 0:
        return False

    for b, s in goal_support.items():
        if support[b] != s:
            return False

    if goal_holding != 0:
        for i in BLOCKS:
            if i != goal_holding and support[i] == goal_holding:
                return False

    return True


if not goal_consistent(goal_support, goal_holding):
    print("No plan")
else:
    if is_goal(start):
        pass
    else:
        queue = deque([start])
        parent = {start: (None, None)}
        found = None

        while queue:
            state = queue.popleft()

            for action, nxt in actions(state):
                if nxt in parent:
                    continue

                parent[nxt] = (state, action)

                if is_goal(nxt):
                    found = nxt
                    break

                queue.append(nxt)

            if found is not None:
                break

        if found is None:
            print("No plan")
        else:
            plan = []
            cur = found

            while cur != start:
                prev, act = parent[cur]
                plan.append(act)
                cur = prev

            plan.reverse()

            for act in plan:
                if act[0] in ("pickup", "putdown"):
                    print(f"({act[0]} block{act[1]})")
                else:
                    print(f"({act[0]} block{act[1]} block{act[2]})")

def main():
    # Internal labels A..M correspond to output names block1..block13.
    blocks = [chr(ord('A') + i) for i in range(13)]
    out_name = {b: "block" + str(i + 1) for i, b in enumerate(blocks)}

    # State:
    # loc[b] = "table" if b is on the table,
    # loc[b] = another block if b is on that block,
    # loc[b] = None if b is held.
    loc = {b: "table" for b in blocks}
    arm = "G"
    loc["G"] = None

    # Initial towers, with G initially held rather than on F.
    for bottom, top in [
        ("A", "B"), ("B", "C"),
        ("D", "E"), ("E", "F"),
        ("H", "I"), ("I", "J"), ("J", "K"), ("K", "L"),
    ]:
        loc[top] = bottom

    # Goal tower from bottom to top.
    goal = blocks
    plan = []

    def top_on(b):
        for x in blocks:
            if loc[x] == b:
                return x
        return None

    def is_clear(b):
        return top_on(b) is None

    def pickup(b):
        nonlocal arm
        if arm is not None or loc[b] != "table" or not is_clear(b):
            raise ValueError("pickup precondition failed")
        arm = b
        loc[b] = None
        plan.append(("pickup", b))

    def putdown(b):
        nonlocal arm
        if arm != b or loc[b] is not None:
            raise ValueError("putdown precondition failed")
        arm = None
        loc[b] = "table"
        plan.append(("putdown", b))

    def unstack(b, support):
        nonlocal arm
        if arm is not None or loc[b] != support or not is_clear(b):
            raise ValueError("unstack precondition failed")
        arm = b
        loc[b] = None
        plan.append(("unstack", b, support))

    def stack(b, support):
        nonlocal arm
        if arm != b or loc[b] is not None or loc[support] is None or not is_clear(support):
            raise ValueError("stack precondition failed")
        arm = None
        loc[b] = support
        plan.append(("stack", b, support))

    def make_clear(b):
        while True:
            t = top_on(b)
            if t is None:
                break
            move_to_table(t)

    def move_to_table(b):
        if arm == b:
            putdown(b)
            return
        if loc[b] == "table":
            return
        if loc[b] is None:
            raise ValueError("block is held but arm is not set")
        make_clear(b)
        support = loc[b]
        unstack(b, support)
        putdown(b)

    # The plan starts with G held; put it down to free the arm.
    if arm is not None:
        putdown(arm)

    # Build the goal tower from bottom to top.
    for i in range(1, len(goal)):
        below = goal[i - 1]
        above = goal[i]

        if loc[above] == below:
            continue

        make_clear(below)

        if arm == above:
            stack(above, below)
        else:
            make_clear(above)
            if loc[above] == "table":
                pickup(above)
            elif loc[above] is None:
                raise ValueError("unexpected held block")
            else:
                support = loc[above]
                unstack(above, support)
            stack(above, below)

    # Verify that the goal state was reached.
    if arm is not None:
        raise ValueError("arm not empty in goal")
    for i, b in enumerate(goal):
        expected = "table" if i == 0 else goal[i - 1]
        if loc[b] != expected:
            raise ValueError("goal not reached")

    for action in plan:
        print("(" + " ".join(out_name[x] for x in action) + ")")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        print("No plan")

from collections import deque

BLOCKS = tuple(f"block{i}" for i in range(1, 11))
INITIAL_TABLE = tuple(f"block{n}" for n in (10, 4, 3, 2, 9, 7, 8, 6, 5, 1))
GOAL_TABLE = tuple(f"block{n}" for n in (8, 5, 3, 10, 9, 2, 6, 7, 4, 1))


def top_of(on_top, b):
    for base, top in on_top:
        if base == b:
            return top
    return None


def add_picked(picked, b):
    if b in picked:
        return picked
    return tuple(sorted(picked + (b,)))


def add_on_top(on_top, base, top):
    d = dict(on_top)
    d[base] = top
    return tuple(sorted(d.items()))


def remove_on_top(on_top, base):
    return tuple((b, t) for b, t in on_top if b != base)


def is_goal(table, on_top, arm, picked):
    return table == GOAL_TABLE and arm is None and not on_top and not picked


def is_dead(table, on_top, arm, picked):
    return arm is not None or bool(picked)


def neighbors(table, on_top, arm, picked):
    if arm is None:
        for b in table:
            if top_of(on_top, b) is None:
                new_table = tuple(x for x in table if x != b)
                yield (new_table, on_top, b, add_picked(picked, b)), f"(pickup {b})"
        for base, top in on_top:
            if top_of(on_top, top) is None:
                yield (table, remove_on_top(on_top, base), top, add_picked(picked, top)), f"(unstack {top} {base})"
    else:
        b = arm
        for y in BLOCKS:
            if y != b and top_of(on_top, y) is None and b not in table:
                yield (table, add_on_top(on_top, y, b), None, picked), f"(stack {b} {y})"


def main():
    initial = (INITIAL_TABLE, (), None, ())
    if is_goal(*initial):
        return

    queue = deque([initial])
    parent = {initial: None}
    found = None

    while queue:
        state = queue.popleft()
        if is_goal(*state):
            found = state
            break

        for ns, action in neighbors(*state):
            if is_goal(*ns):
                found = ns
                parent[ns] = (state, action)
                break
            if is_dead(*ns):
                continue
            if ns not in parent:
                parent[ns] = (state, action)
                queue.append(ns)

        if found is not None:
            break

    if found is None:
        print("No plan")
        return

    actions = []
    state = found
    while parent[state] is not None:
        prev, action = parent[state]
        actions.append(action)
        state = prev

    actions.reverse()
    for action in actions:
        print(action)


if __name__ == "__main__":
    main()

N = 12
TABLE = 0
BLOCKS = [f"block{i}" for i in range(1, N + 1)]


def name(b):
    return BLOCKS[b - 1]


initial = [TABLE] * (N + 1)


def add_stack(support, blocks):
