goal_unary = {
    11: TABLE,
    10: 11,
    1: TABLE,
    5: TABLE,
    3: TABLE,
    7: TABLE,
    8: TABLE,
    9: TABLE,
    4: TABLE,
    6: TABLE,
    2: TABLE,
    12: TABLE,
}


def category(b):
    if b % 4 == 0:
        return 0
    if b % 2 == 1:
        return 1
    return 2


CATEGORY_BLOCKS = {
    0: {4, 8, 12},
    1: {1, 3, 5, 7, 9, 11},
    2: {2, 6, 10},
}


def valid_state(support):
    if any(support[i] is None for i in range(1, N + 1)):
        return False

    on_top = {i: [] for i in range(N + 1)}
    for b in range(1, N + 1):
        y = support[b]
        if y < 0 or y > N or y == b:
            return False
        on_top[y].append(b)

    for y in range(N + 1):
        if len(on_top[y]) > 1:
            return False

    for b in range(1, N + 1):
        seen = set()
        cur = b
        while cur != TABLE:
            if cur in seen:
                return False
            seen.add(cur)
            cur = support[cur]

    return True


def additional_constraint(support):
    if not valid_state(support):
        return False

    if sum(1 for b in range(1, N + 1) if support[b] == TABLE) != 3:
        return False

    on_top = {i: [] for i in range(N + 1)}
    for b in range(1, N + 1):
        on_top[support[b]].append(b)

    stacks = []
    for bottom in on_top[TABLE]:
        chain = [bottom]
        cur = bottom
        while on_top[cur]:
            cur = on_top[cur][0]
            chain.append(cur)
        stacks.append(chain)

    if len(stacks) != 3:
        return False

    cats = set()
    for chain in stacks:
        cat = category(chain[0])
        if set(chain) != CATEGORY_BLOCKS[cat]:
            return False
        if cat in cats:
            return False
        cats.add(cat)
        if chain != sorted(chain):
            return False

    return cats == set(CATEGORY_BLOCKS.keys())


def goal_constraint(support):
    for b, val in goal_unary.items():
        if support[b] != val:
            return False
    return additional_constraint(support)


def find_goal_state():
    domains = [set(range(N + 1)) for _ in range(N + 1)]
    for b in range(1, N + 1):
        domains[b].discard(b)

    for b, val in goal_unary.items():
        if val not in domains[b]:
            return None
        domains[b] = {val}

    order = sorted(range(1, N + 1), key=lambda b: (len(domains[b]), b))
    support = [None] * (N + 1)

    def partial_ok():
        on_top = {i: [] for i in range(N + 1)}
        table_count = 0

        for b in range(1, N + 1):
            y = support[b]
            if y is None:
                continue
            if y < 0 or y > N or y == b:
                return False
            if y == TABLE:
                table_count += 1
            on_top[y].append(b)

        if table_count > 3:
            return False

        for y in range(N + 1):
            if len(on_top[y]) > 1:
                return False

        for b in range(1, N + 1):
            if support[b] is None:
                continue
            seen = set()
            cur = b
            while cur is not None and cur != TABLE:
                if cur in seen:
                    return False
                seen.add(cur)
                if support[cur] is None:
                    break
                cur = support[cur]

        return True

    def dfs(idx):
        if idx == N:
            if goal_constraint(support):
                return support[:]
            return None

        b = order[idx]
        for val in sorted(domains[b]):
            support[b] = val
            if partial_ok():
                res = dfs(idx + 1)
                if res is not None:
                    return res

        support[b] = None
        return None

    return dfs(0)


def make_plan(goal_state):
    actions = []
    sim = initial[:]

    while True:
        on_top = {i: [] for i in range(N + 1)}
        for b in range(1, N + 1):
            if sim[b] != -1:
                on_top[sim[b]].append(b)

        moved = False
        for b in range(1, N + 1):
            if sim[b] != TABLE and sim[b] != -1 and not on_top[b]:
                actions.append(("unstack", b, sim[b]))
                sim[b] = -1
                actions.append(("putdown", b))
                sim[b] = TABLE
                moved = True
                break

        if not moved:
            break

    target_on_top = {i: [] for i in range(N + 1)}
    for b in range(1, N + 1):
        target_on_top[goal_state[b]].append(b)

    for bottom in target_on_top[TABLE]:
        chain = [bottom]
        cur = bottom
        while target_on_top[cur]:
            cur = target_on_top[cur][0]
            chain.append(cur)

        for i in range(1, len(chain)):
            top = chain[i]
            below = chain[i - 1]
            actions.append(("pickup", top))
            sim[top] = -1
            actions.append(("stack", top, below))
            sim[top] = below

    return actions


def main():
    goal_state = find_goal_state()
    if goal_state is None:
