                or below[t] != goal_below[t] or top[t] is not None):
            plan = None
            break

        held = b
        below[b] = None
        plan.append(f"(pickup block{b})")

        held = None
        below[b] = t
        top[t] = b
        plan.append(f"(stack block{b} block{t})")


ok = plan is not None and held is None

if ok:
    for b in blocks:
        if below[b] != goal_below[b]:
            ok = False
            break

if ok:
    for b in blocks:
        p = below[b]
        if p not in ('table', None) and top[p] != b:
            ok = False
            break

        t = top[b]
        if t is not None and below[t] != b:
            ok = False
            break

if ok:
    print("\n".join(plan))
else:
    print("No plan")

def main():
    n = 11
    # Block A -> blocka, Block B -> blockb, ..., Block K -> blockk.
    names = [f"block{chr(ord('A') + i)}".lower() for i in range(n)]

    A, B, C, D, E, F, G, H, I, J, K = range(n)

    initial_stacks = [
        [A, B, C],
        [D, E],
        [F],
        [G, H, I, J, K],
    ]

    sup = [-1] * n   # -1 = table, -2 = held, otherwise index of block below
    top = [-1] * n   # -1 = clear, otherwise index of block above

    for stack in initial_stacks:
        for i, b in enumerate(stack):
            if i == 0:
                sup[b] = -1
            else:
                sup[b] = stack[i - 1]
                top[stack[i - 1]] = b

    goal_stacks = [
        [A, B, C],
        [D, E],
        [F, G, H, I, J, K],
    ]

    goal_sup = [-1] * n
    goal_top = [-1] * n

    for stack in goal_stacks:
        for i, b in enumerate(stack):
            if i == 0:
                goal_sup[b] = -1
            else:
                goal_sup[b] = stack[i - 1]

            if i + 1 < len(stack):
                goal_top[b] = stack[i + 1]
            else:
                goal_top[b] = -1

    actions = []
    held = -1

    def pickup(b):
        nonlocal held
        held = b
        sup[b] = -2
        actions.append(f"(pickup {names[b]})")

    def putdown(b):
        nonlocal held
        sup[b] = -1
        held = -1
        actions.append(f"(putdown {names[b]})")

    def stack(b, y):
        nonlocal held
        sup[b] = y
        top[y] = b
        held = -1
        actions.append(f"(stack {names[b]} {names[y]})")

    def unstack(b, y):
        nonlocal held
        sup[b] = -2
        top[y] = -1
        held = b
        actions.append(f"(unstack {names[b]} {names[y]})")

    def move_to_table(b):
        while top[b] != -1:
            move_to_table(top[b])

        if sup[b] == -1:
            return

        y = sup[b]
        unstack(b, y)
        putdown(b)

    def clear(b):
        while top[b] != -1:
            move_to_table(top[b])

    def move_to(b, dest):
        if sup[b] == dest:
            clear(b)
            return

        clear(b)

        if dest != -1:
            clear(dest)

        if sup[b] == -1:
            pickup(b)
        else:
            y = sup[b]
            unstack(b, y)

        if dest == -1:
            putdown(b)
        else:
            stack(b, dest)

    for stack in goal_stacks:
        for b in stack:
            if sup[b] == goal_sup[b] and top[b] == goal_top[b]:
                continue

            if sup[b] == goal_sup[b]:
                clear(b)
            else:
                move_to(b, goal_sup[b])

    if held != -1 or any(sup[i] != goal_sup[i] or top[i] != goal_top[i] for i in range(n)):
        print("No plan")
    else:
        if actions:
            print("\n".join(actions))


