        for stack in stacks:
            if not stack:
                continue
            on[stack[0]] = "table"
            for lower, upper in zip(stack, stack[1:]):
                on[upper] = lower
        return on

    initial_on = to_on(initial_stacks)
    goal_on = to_on(goal_stacks)

