goal_on[1] = 0
goal_on[5] = 1


def solve_constructive():
    on = initial_on[:]
    actions = []

    def get_top(x):
        for b in blocks:
            if on[b] == x:
                return b
        return 0

    def clear_block(x):
        while True:
            z = get_top(x)
            if z == 0:
                return True
            if not move_block(z, 0):
                return False

    def move_block(x, target):
        if x == target:
            return False
        if x == 1 and target == 3:
            return False

        if on[x] == target:
            return clear_block(x)

        if not clear_block(x):
            return False

        if target > 0:
            if not clear_block(target):
                return False

        if on[x] == target:
            return True

        if on[x] == 0:
            actions.append(('pickup', x))
            on[x] = -1
        else:
            support = on[x]
            if support == -1:
                return False
            actions.append(('unstack', x, support))
            on[x] = -1

        if target == 0:
            actions.append(('putdown', x))
            on[x] = 0
        else:
            if on[target] == -1:
                return False
            if x == 1 and target == 3:
                return False
            actions.append(('stack', x, target))
            on[x] = target

        return True

    towers = []
    for b in blocks:
        if goal_on[b] == 0:
            tower = [b]
            seen = {b}
            while True:
                nxt = 0
                for c in blocks:
                    if goal_on[c] == tower[-1]:
                        nxt = c
                        break
                if nxt == 0:
                    break
                if nxt in seen:
                    return None
                tower.append(nxt)
                seen.add(nxt)
            towers.append(tower)

    if sum(len(t) for t in towers) != len(blocks):
        return None

    def initial_height(b):
        h = 0
        cur = initial_on[b]
        while cur > 0:
            h += 1
            cur = initial_on[cur]
        return h

    towers.sort(key=lambda t: (-initial_height(t[0]), -len(t)))

    for tower in towers:
        for i, b in enumerate(tower):
            target = 0 if i == 0 else tower[i - 1]
            if not move_block(b, target):
                return None

    if any(v == -1 for v in on):
        return None
    if on != goal_on:
        return None
    if any(a[0] == 'stack' and a[1] == 1 and a[2] == 3 for a in actions):
        return None

    return actions


def verify(actions):
    on = initial_on[:]
    held = 0

    def clear(x):
        for b in blocks:
            if on[b] == x:
                return False
        return True

    for act in actions:
        name = act[0]

        if name == 'pickup':
            if len(act) != 2:
                return False
            x = act[1]
            if held != 0 or on[x] != 0 or not clear(x):
                return False
            on[x] = -1
            held = x

        elif name == 'putdown':
            if len(act) != 2:
                return False
            x = act[1]
            if held != x or not clear(x):
                return False
            on[x] = 0
            held = 0

        elif name == 'unstack':
            if len(act) != 3:
                return False
            x, y = act[1], act[2]
            if held != 0 or y == 0 or on[x] != y or not clear(x):
                return False
            on[x] = -1
            held = x

        elif name == 'stack':
            if len(act) != 3:
                return False
            x, y = act[1], act[2]
            if held != x or x == y or on[y] == -1 or not clear(x) or not clear(y):
                return False
            if x == 1 and y == 3:
                return False
            on[x] = y
            held = 0

        else:
            return False

    if held != 0 or on != goal_on:
        return False
    return True


def format_action(act):
    if act[0] in ('pickup', 'putdown'):
        return f"({act[0]} block{act[1]})"
    return f"({act[0]} block{act[1]} block{act[2]})"


