        if kind == "pickup":
            b = action[1]
            if arm is not None or on[b] != "table" or not is_clear(b):
                return False
            arm = b
            on[b] = "held"

        elif kind == "putdown":
            b = action[1]
            if arm != b:
                return False
            on[b] = "table"
            arm = None

        elif kind == "unstack":
            x, y = action[1], action[2]
            if arm is not None or on[x] != y or on[y] == "held" or not is_clear(x):
                return False
            arm = x
            on[x] = "held"

        elif kind == "stack":
            x, y = action[1], action[2]
            if arm != x or on[y] == "held" or not is_clear(y):
                return False
            on[x] = y
