import sys

# Formalization:
# State variables:
#   support[b] = "table" | another block id | None (held)
#   top[b]     = block id on top of b | None
#   held       = block id | None
#
# Constraints enforced:
#   - only one held block
#   - pickup/unstack only if the moved block is clear
#   - stack only onto a clear, non-held destination block
#   - putdown only a held clear block

BLOCKS = tuple(range(1, 12))


def bname(b):
    return f"block{b}"


def make_initial():
    support = {b: "table" for b in BLOCKS}
    top = {b: None for b in BLOCKS}

    # Bottom-to-top stacks from the problem statement.
    stacks = [
        (8, 2, 5, 7),
        (9, 10, 1, 3, 11, 4, 6),
    ]

    for stack in stacks:
        for i, b in enumerate(stack):
            if i == 0:
                support[b] = "table"
            else:
                support[b] = stack[i - 1]
        for i in range(len(stack) - 1):
            top[stack[i]] = stack[i + 1]

    return support, top, None


GOAL_ORDER = (7, 4, 11, 2, 9, 5, 8, 10, 1, 3, 6)


def make_goal():
    support = {}
    top = {}
    for i, b in enumerate(GOAL_ORDER):
        support[b] = "table" if i == 0 else GOAL_ORDER[i - 1]
        top[b] = GOAL_ORDER[i + 1] if i + 1 < len(GOAL_ORDER) else None
    return support, top, None


def apply_action(state, action, blocks):
    """Return a new state if the action is legal, otherwise None."""
    support, top, held = state

    if action == "pickup":
        if len(blocks) != 1:
            return None
        b = blocks[0]
        if held is not None:
            return None
        if support[b] != "table":
            return None
        if top[b] is not None:
            return None

        support = dict(support)
        top = dict(top)
        support[b] = None
        return support, top, b

    if action == "putdown":
        if len(blocks) != 1:
            return None
        b = blocks[0]
        if held != b:
            return None
        if top[b] is not None:
            return None

        support = dict(support)
        top = dict(top)
        support[b] = "table"
        return support, top, None

    if action == "unstack":
        if len(blocks) != 2:
            return None
        b, s = blocks
        if held is not None:
            return None
        if b == s:
            return None
        if support[b] != s:
            return None
        if support[s] is None:
            return None
        if top[b] is not None:
            return None

        support = dict(support)
        top = dict(top)
        support[b] = None
        top[s] = None
        return support, top, b

    if action == "stack":
        if len(blocks) != 2:
            return None
        b, s = blocks
        if held != b:
            return None
        if b == s:
            return None
        if top[b] is not None:
            return None
        if support[s] is None:
            return None
        if top[s] is not None:
            return None

        support = dict(support)
        top = dict(top)
        support[b] = s
        top[s] = b
        return support, top, None

    return None


def verify_plan(plan):
    """Independently simulate the printed plan and check the goal."""
    state = make_initial()

    for line in plan:
        if not line.startswith("(") or not line.endswith(")"):
            return False

        parts = line[1:-1].split()
        if not parts:
            return False

        action = parts[0]
        if action not in ("pickup", "putdown", "unstack", "stack"):
            return False

        blocks = []
        for p in parts[1:]:
            if not p.startswith("block"):
                return False
            try:
                num = int(p[5:])
            except ValueError:
                return False
            if num not in BLOCKS:
                return False
            blocks.append(num)

        new_state = apply_action(state, action, blocks)
        if new_state is None:
            return False
        state = new_state

    return state == make_goal()


def generate_plan():
    """
    Construct a valid plan for this single-goal-stack instance.

    Invariant while building the goal stack from bottom to top:
    the already built prefix is a clear stack on the table, and no
    non-prefix block is on top of it.  To place the next block, move
    all non-prefix blocks above it to the table, then move it to its
    goal support.
    """
    support, top, held = make_initial()
    actions = []
    prefix = set()

    def do(action, *args):
        nonlocal held

        if action == "pickup":
            b = args[0]
            if held is not None:
                return False
            if support[b] != "table":
                return False
            if top[b] is not None:
                return False

            held = b
            support[b] = None
            actions.append(f"(pickup {bname(b)})")
            return True

        if action == "putdown":
            b = args[0]
            if held != b:
                return False
            if top[b] is not None:
                return False

            held = None
            support[b] = "table"
            actions.append(f"(putdown {bname(b)})")
            return True

        if action == "unstack":
            b, s = args
            if held is not None:
                return False
            if b == s:
                return False
            if support[b] != s:
                return False
            if support[s] is None:
                return False
            if top[b] is not None:
                return False

            held = b
            support[b] = None
            top[s] = None
            actions.append(f"(unstack {bname(b)} {bname(s)})")
            return True

        if action == "stack":
            b, s = args
            if held != b:
                return False
            if b == s:
                return False
            if top[b] is not None:
                return False
            if support[s] is None:
                return False
            if top[s] is not None:
                return False

            held = None
            support[b] = s
            top[s] = b
            actions.append(f"(stack {bname(b)} {bname(s)})")
            return True

        return False

    def clear_above(b):
        """Move all non-prefix blocks above b to the table."""
        while top[b] is not None:
            x = b
            while top[x] is not None:
                x = top[x]

            if x in prefix:
                return False
            if support[x] is None or support[x] == "table":
                return False

            if not do("unstack", x, support[x]):
                return False
            if not do("putdown", x):
                return False

        return True

    def place(b, dest):
        if not clear_above(b):
            return False

        if dest == "table":
            if support[b] == "table":
                return True
            if support[b] is None:
                return do("putdown", b)
            return do("unstack", b, support[b]) and do("putdown", b)

        s = dest
        if support[b] == s:
            return True

        if top[s] is not None:
            return False

        if support[b] == "table":
            return do("pickup", b) and do("stack", b, s)
        if support[b] is None:
            return do("stack", b, s)

        return do("unstack", b, support[b]) and do("stack", b, s)

    for i, b in enumerate(GOAL_ORDER):
        dest = "table" if i == 0 else GOAL_ORDER[i - 1]
        if not place(b, dest):
            return None
        prefix.add(b)

    goal_support, goal_top, _ = make_goal()
    if held is not None:
        return None

    for b in BLOCKS:
        if support[b] != goal_support[b] or top[b] != goal_top[b]:
            return None

    return actions


def main():
    plan = generate_plan()

    if plan is None or not verify_plan(plan):
        print("No plan")
    else:
        sys.stdout.write("\n".join(plan))
        if plan:
            sys.stdout.write("\n")


if __name__ == "__main__":
    main()

N = 11
NONE = -1
TABLE = -1
ARM = -2


def block_name(i):
    return f"block{i + 1}"


def make_stacks(stacks):
    loc = [TABLE] * N
    top = [NONE] * N
    seen = set()

    for bottom, seq in stacks:
        if bottom in seen:
            raise ValueError
        seen.add(bottom)

        loc[bottom] = TABLE
        prev = bottom
        for b in seq:
            if b in seen:
                raise ValueError
            seen.add(b)
            top[prev] = b
            loc[b] = prev
            prev = b
        top[prev] = NONE

    return (tuple(loc), tuple(top), NONE)


def apply(state, action):
    loc = list(state[0])
    top = list(state[1])
    held = state[2]
    kind = action[0]

    if kind == "pickup":
        b = action[1]
        if held != NONE or loc[b] != TABLE or top[b] != NONE:
            return None
        held = b
        loc[b] = ARM

    elif kind == "putdown":
        b = action[1]
        if held != b:
            return None
        held = NONE
        loc[b] = TABLE
        top[b] = NONE

    elif kind == "unstack":
        b, s = action[1], action[2]
        if held != NONE or loc[b] != s or top[b] != NONE or s == ARM or s == TABLE:
            return None
        held = b
        loc[b] = ARM
        top[s] = NONE

    elif kind == "stack":
        b, t = action[1], action[2]
        if held != b or t == TABLE or top[t] != NONE or loc[t] == ARM or t == b:
            return None
        held = NONE
        loc[b] = t
        top[t] = b
        top[b] = NONE

    else:
        return None

    return (tuple(loc), tuple(top), held)


def clear_block(state, b, actions):
    while state[1][b] != NONE:
        z = state[1][b]
        state, actions = clear_block(state, z, actions)

        if state[0][z] != b:
            raise RuntimeError

        act = ("unstack", z, b)
        ns = apply(state, act)
        if ns is None:
            raise RuntimeError
        state = ns
        actions.append(act)

        act = ("putdown", z)
        ns = apply(state, act)
        if ns is None:
            raise RuntimeError
        state = ns
        actions.append(act)

    return state, actions


def move_to_arm(state, b, actions):
    state, actions = clear_block(state, b, actions)

    if state[2] == b:
        return state, actions

    if state[0][b] == TABLE:
        act = ("pickup", b)
    elif state[0][b] == ARM:
        raise RuntimeError
    else:
        act = ("unstack", b, state[0][b])

    ns = apply(state, act)
    if ns is None:
        raise RuntimeError

    state = ns
    actions.append(act)
    return state, actions


def ensure_bottom_on_table(state, b, actions):
    state, actions = clear_block(state, b, actions)

    if state[2] == b:
        act = ("putdown", b)
        ns = apply(state, act)
        if ns is None:
            raise RuntimeError
        state = ns
        actions.append(act)
        return state, actions

    if state[0][b] != TABLE:
        act = ("unstack", b, state[0][b])
        ns = apply(state, act)
        if ns is None:
            raise RuntimeError
        state = ns
        actions.append(act)

        act = ("putdown", b)
        ns = apply(state, act)
        if ns is None:
            raise RuntimeError
        state = ns
        actions.append(act)

    return state, actions


def solve_single_stack(initial, goal_bottom, goal_sequence):
    state = initial
    actions = []

    state, actions = ensure_bottom_on_table(state, goal_bottom, actions)

    prev = goal_bottom
    for b in goal_sequence:
        state, actions = move_to_arm(state, b, actions)

        act = ("stack", b, prev)
        ns = apply(state, act)
        if ns is None:
            raise RuntimeError

        state = ns
        actions.append(act)
        prev = b

    return state, actions


def start_condition_ok(state):
    return state[2] == NONE and all(loc != ARM for loc in state[0])


def main():
    initial = make_stacks([
        (7, [1, 4, 6]),
        (8, [9, 0, 2, 10, 3, 5]),
    ])

    goal = make_stacks([
        (6, [3, 10, 1, 8, 4, 7, 9, 0, 2, 5]),
    ])

    if not start_condition_ok(initial):
        print("No plan")
        return

    try:
        final, actions = solve_single_stack(
            initial,
            6,
            [3, 10, 1, 8, 4, 7, 9, 0, 2, 5]
        )
    except Exception:
        print("No plan")
        return

    state = initial
    for act in actions:
        state = apply(state, act)
        if state is None:
            print("No plan")
            return

    if state != goal:
        print("No plan")
        return

    for act in actions:
        print("({} {})".format(act[0], " ".join(block_name(x) for x in act[1:])))


if __name__ == "__main__":
    main()

def make_prefix_plan(initial, goal):
    # In this ordered-table model:
    # - pickup removes a block from the table sequence.
    # - putdown appends the held block to the table sequence.
    # Blocks never picked up remain in their initial relative order and
    # must form a prefix of the goal.  Keep the longest such prefix.
    keep = 0
    for block in initial:
        if keep < len(goal) and block == goal[keep]:
            keep += 1

    plan = []
    for block in goal[keep:]:
        plan.append(f"(pickup {block})")
        plan.append(f"(putdown {block})")
    return plan


def make_full_plan(initial, goal):
    # Fallback: move every block in goal order.
    plan = []
    for block in goal:
        plan.append(f"(pickup {block})")
        plan.append(f"(putdown {block})")
    return plan


def verify(plan, initial, goal):
    table = list(initial)
    arm = None

    for action in plan:
        if not action.startswith("(") or not action.endswith(")"):
            return False

        parts = action[1:-1].split()
        if not parts:
            return False

        name = parts[0]

        if name == "pickup" and len(parts) == 2:
            block = parts[1]
            if arm is not None or block not in table:
                return False
            table.remove(block)
            arm = block

        elif name == "putdown" and len(parts) == 2:
            block = parts[1]
            if arm != block:
                return False
            table.append(block)
            arm = None

        else:
            return False

    return arm is None and tuple(table) == goal


def main():
    initial = (
        "block10", "block4", "block3", "block2", "block9",
        "block7", "block8", "block6", "block5", "block1"
    )

    goal = (
        "block8", "block5", "block3", "block10", "block9",
        "block2", "block6", "block7", "block4", "block1"
    )

    plan = make_prefix_plan(initial, goal)
    if not verify(plan, initial, goal):
        plan = make_full_plan(initial, goal)

    if verify(plan, initial, goal):
        if plan:
            print("\n".join(plan))
    else:
        print("No plan")


if __name__ == "__main__":
    main()

def solve():
    blocks = [f"block{i}" for i in range(1, 11)]

    goal = {
        "block1": "table",
        "block10": "block1",
        "block4": "table",
        "block8": "block4",
        "block3": "table",
        "block9": "block3",
        "block2": "block9",
        "block5": "table",
        "block6": "block5",
        "block7": "block6",
    }

    base_order = ["block1", "block4", "block3", "block5"]

    if set(goal) != set(blocks):
        return None

    for b in blocks:
        p = goal[b]
        if p != "table" and p not in blocks:
            return None

    loc = {b: "table" for b in blocks}
    held = None
    actions = []

    def is_clear(b):
        for x in blocks:
            if loc[x] == b:
                return False
        return True

    def perform(action):
        nonlocal held

        if action[0] == "pickup":
            if len(action) != 2:
                return False
            b = action[1]
            if b not in loc:
                return False
            if held is not None or loc[b] != "table" or not is_clear(b):
                return False
            loc[b] = "hand"
            held = b
            return True

        if action[0] == "putdown":
            if len(action) != 2:
                return False
            b = action[1]
            if b not in loc:
                return False
            if held != b:
                return False
            loc[b] = "table"
            held = None
            return True

        if action[0] == "unstack":
            if len(action) != 3:
                return False
            b, p = action[1], action[2]
            if b not in loc or p not in loc:
                return False
            if held is not None or loc[b] != p or not is_clear(b):
                return False
            loc[b] = "hand"
            held = b
            return True

        if action[0] == "stack":
            if len(action) != 3:
                return False
            b, p = action[1], action[2]
            if b not in loc or p not in loc:
                return False
            if held != b or loc[p] == "hand" or not is_clear(p):
                return False
            loc[b] = p
            held = None
            return True

        return False

    def do(action):
        if not perform(action):
            return False
        actions.append(action)
        return True

    def move_to_table(b):
        nonlocal held
        if b not in loc:
            return False

        if held is not None:
            if not do(("putdown", held)):
                return False

        while True:
            tops = [x for x in blocks if loc[x] == b]
            if not tops:
                break
            if not move_to_table(tops[0]):
                return False

        if loc[b] != "table":
            p = loc[b]
            if p not in loc:
                return False
            if not do(("unstack", b, p)):
                return False
            if not do(("putdown", b)):
                return False

        return True

    for b in blocks:
        if goal[b] == "table" and loc[b] != "table":
            return None

    for b in blocks:
        if not move_to_table(b):
            return None

    child_count = {}
    for b in blocks:
        p = goal[b]
        if p != "table":
            child_count[p] = child_count.get(p, 0) + 1

    if any(v > 1 for v in child_count.values()):
        return None

    visited = set()
    for b in blocks:
        if goal[b] == "table":
            cur = b
            while cur is not None:
                if cur in visited:
                    return None
                visited.add(cur)
                children = [x for x in blocks if goal[x] == cur]
                cur = children[0] if children else None

    if visited != set(blocks):
        return None

    def build_base(base):
        cur = base
        while True:
            children = [x for x in blocks if goal[x] == cur]
            if not children:
                break

            child = children[0]

            if not move_to_table(child):
                return False
            if loc[child] != "table" or not is_clear(child):
                return False
            if loc[cur] == "hand" or not is_clear(cur):
                return False

            if not do(("pickup", child)):
                return False
            if not do(("stack", child, cur)):
                return False

            cur = child

        return True

    processed_bases = set()

    for base in base_order:
        if goal.get(base) != "table":
            return None
        if base not in processed_bases:
            processed_bases.add(base)
            if not build_base(base):
                return None

    for base in blocks:
        if goal[base] == "table" and base not in processed_bases:
            if not build_base(base):
                return None

    if held is not None:
        return None

    for b in blocks:
        if loc[b] != goal[b]:
            return None

    return actions


def main():
    actions = solve()
    if actions is None:
        print("No plan")
    else:
        print("\n".join(f"({a[0]} {' '.join(a[1:])})" for a in actions))


if __name__ == "__main__":
    main()

from collections import deque

ALL_BLOCKS = [1, 2, 3, 4, 5, 6]
SEARCH_ORDER = [4, 3, 2, 1, 5, 6]

# on[b]:
#   0  -> block b is on the table
#  -1  -> block b is held
#   c  -> block b is on block c
INITIAL_ON = (0, 0, 6, 4, 0, 0, 0)
INITIAL_ARM = 0

GOAL_ON = (0, 0, 0, 0, 3, 0, 0)
GOAL_ARM = 0

ALWAYS_ON_TABLE = [1, 5, 6]


def is_clear(on, b):
    return all(on[x] != b for x in ALL_BLOCKS)


def valid_state(on, arm):
    held_count = sum(1 for v in on if v == -1)

    if arm == 0:
        if held_count != 0:
            return False
    else:
        if held_count != 1 or on[arm] != -1:
            return False
        if not is_clear(on, arm):
            return False

    for b in ALWAYS_ON_TABLE:
        if on[b] != 0:
            return False

    support_count = {}
    for b in ALL_BLOCKS:
        s = on[b]
        if s == 0 or s == -1:
            continue
        if s == b or s < 1 or s > 6:
            return False
        if on[s] == -1:
            return False
        if s in support_count:
            return False
        support_count[s] = 1

    return True


def successors(state):
    on, arm = state
    next_states = []

    if arm == 0:
        for b in SEARCH_ORDER:
            if on[b] == 0 and is_clear(on, b):
                new_on = list(on)
                new_on[b] = -1
                if valid_state(tuple(new_on), b):
                    next_states.append(((tuple(new_on), b), ("pickup", b)))

        for b in SEARCH_ORDER:
            s = on[b]
            if s != 0 and s != -1 and is_clear(on, b):
                new_on = list(on)
                new_on[b] = -1
                if valid_state(tuple(new_on), b):
                    next_states.append(((tuple(new_on), b), ("unstack", b, s)))
    else:
        b = arm

        new_on = list(on)
        new_on[b] = 0
        if valid_state(tuple(new_on), 0):
            next_states.append(((tuple(new_on), 0), ("putdown", b)))

        for c in SEARCH_ORDER:
            if c == b or on[c] == -1:
                continue
            if is_clear(on, c):
                new_on = list(on)
                new_on[b] = c
                if valid_state(tuple(new_on), 0):
                    next_states.append(((tuple(new_on), 0), ("stack", b, c)))

    return next_states


def main():
    start = (INITIAL_ON, INITIAL_ARM)
    goal = (GOAL_ON, GOAL_ARM)

    if not valid_state(start, INITIAL_ARM) or not valid_state(goal, GOAL_ARM):
        print("No plan")
        return

    visited = {start: None}
    q = deque([start])

    while q:
        state = q.popleft()
        if state == goal:
            break

        for nstate, action in successors(state):
            if nstate not in visited:
                visited[nstate] = (state, action)
                q.append(nstate)

    if goal not in visited:
        print("No plan")
        return

    actions = []
    state = goal
    while state != start:
        prev, action = visited[state]
        actions.append(action)
        state = prev

    actions.reverse()

    for action in actions:
        if len(action) == 2:
            print("({} block{})".format(action[0], action[1]))
        else:
            print("({} block{} block{})".format(action[0], action[1], action[2]))


if __name__ == "__main__":
    main()

from collections import deque

# State variables:
#   support[block] is one of:
#     - 'table'
#     - another block name
#     - None, meaning the block is currently held
#   held is None or one block name.
#
# Constraints enforced:
#   - at most one block is held at a time
#   - pickup only if the block is on the table, clear, and arm is empty
#   - unstack only if the block is clear and the arm is empty
#   - stack only if the source block is held and the target block is clear
#   - putdown only if the block is held

BLOCKS = ["a", "b", "c", "d", "e", "f"]
TABLE = "table"

initial_supports = {
    "a": TABLE,
    "b": "c",
    "c": TABLE,
    "d": TABLE,
    "e": "d",
    "f": TABLE,
}
initial_held = None

goal_supports = {
    "a": "b",
    "b": "c",
    "c": TABLE,
    "d": TABLE,
    "e": "f",
    "f": TABLE,
}
goal_held = None


def encode(supports, held):
    return tuple(supports[b] for b in BLOCKS) + (held,)


def decode(state):
    supports = {b: state[i] for i, b in enumerate(BLOCKS)}
    held = state[len(BLOCKS)]
    return supports, held


def is_clear(supports, x):
    return not any(supports[z] == x for z in BLOCKS if z != x)


def successors(state):
    supports, held = decode(state)
    result = []

    if held is None:
        for x in BLOCKS:
            if supports[x] == TABLE and is_clear(supports, x):
                next_supports = supports.copy()
                next_supports[x] = None
                result.append((("pickup", x), encode(next_supports, x)))

            if supports[x] != TABLE and supports[x] is not None and is_clear(supports, x):
                y = supports[x]
                next_supports = supports.copy()
                next_supports[x] = None
                result.append((("unstack", x, y), encode(next_supports, x)))
    else:
        x = held

        next_supports = supports.copy()
        next_supports[x] = TABLE
        result.append((("putdown", x), encode(next_supports, None)))

        for y in BLOCKS:
            if y == x or supports[y] is None:
                continue
            if is_clear(supports, y):
                next_supports = supports.copy()
                next_supports[x] = y
                result.append((("stack", x, y), encode(next_supports, None)))

    return result


start = encode(initial_supports, initial_held)
goal = encode(goal_supports, goal_held)

answer = [] if start == goal else None

if answer is None:
    queue = deque([(start, [])])
    seen = {start}

    while queue:
        state, plan = queue.popleft()

        if state == goal:
            answer = plan
            break

        for action, next_state in successors(state):
            if next_state not in seen:
                seen.add(next_state)
                queue.append((next_state, plan + [action]))

if answer is None:
    print("No plan")
else:
    for action in answer:
        print("(" + " ".join(action) + ")")

def solve():
    blocks = [f"block{i}" for i in range(1, 16)]
    block_set = set(blocks)

    initial_support = {b: None for b in blocks}
    initial_support["block10"] = "block5"
    initial_holding = None

    goal_stack = [
        "block10", "block6", "block4", "block9", "block1",
        "block13", "block8", "block11", "block3", "block14",
        "block7", "block2", "block15", "block12", "block5",
    ]
    final_hand_required = "block5"

    HOLD = "held"

    final_support = {}
    for i, b in enumerate(goal_stack):
        final_support[b] = goal_stack[i - 1] if i > 0 else None
    for b in blocks:
        if b not in final_support:
            final_support[b] = HOLD if b == final_hand_required else None

    def valid_final_state(support, hand):
        if hand is not None and hand not in block_set:
            return False
        if hand is not None and support[hand] != HOLD:
            return False

        for b in blocks:
            s = support[b]
            if s == HOLD:
                if hand != b:
                    return False
            elif s is None:
                pass
            elif s in block_set:
                if s == b:
                    return False
            else:
                return False

        for c in blocks:
            count = 0
            for b in blocks:
                if support[b] == c:
                    count += 1
            if count > 1:
                return False

        for b in blocks:
            seen = set()
            cur = b
            while cur is not None and support[cur] not in (None, HOLD):
                if cur in seen:
                    return False
                seen.add(cur)
                cur = support[cur]

        return True

    if not valid_final_state(final_support, final_hand_required):
        print("No plan")
        return

    support = dict(initial_support)
    holding = initial_holding
    plan = []

    def is_held(b):
        return b == holding

    def do_pickup(b):
        nonlocal holding
        plan.append(f"(pickup {b})")
        holding = b

    def do_putdown(b):
        nonlocal holding
        plan.append(f"(putdown {b})")
        support[b] = None
        holding = None

    def do_unstack(b, c):
        nonlocal holding
        plan.append(f"(unstack {b} {c})")
        support[b] = None
        holding = b

    def do_stack(b, c):
        nonlocal holding
        plan.append(f"(stack {b} {c})")
        support[b] = c
        holding = None

    def putdown_held_if_any():
        if holding is not None:
            do_putdown(holding)

    def move_to_table(b):
        if support[b] is None:
            return
        putdown_held_if_any()
        do_unstack(b, support[b])
        do_putdown(b)

    def ensure_clear(b):
        while not is_held(b):
            top = None
            for x in blocks:
                if support[x] == b:
                    top = x
                    break
            if top is None:
                break
            ensure_clear(top)
            move_to_table(top)

    def place_on(b, target):
        ensure_clear(b)
        putdown_held_if_any()

        if support[b] == target and not is_held(b):
            return

        if support[b] is None:
            do_pickup(b)
        else:
            do_unstack(b, support[b])

        if target is None:
            do_putdown(b)
        else:
            ensure_clear(target)
            do_stack(b, target)

    for i, b in enumerate(goal_stack):
        target = goal_stack[i - 1] if i > 0 else None
        place_on(b, target)

    for b in blocks:
        if final_support[b] is None and b != final_hand_required:
            if is_held(b):
                putdown_held_if_any()
            if support[b] is not None:
                ensure_clear(b)
                putdown_held_if_any()
                do_unstack(b, support[b])
                do_putdown(b)

    if final_hand_required is not None:
        b = final_hand_required
        ensure_clear(b)
        if holding is not None and holding != b:
            do_putdown(holding)
        if not is_held(b):
            if support[b] is None:
                do_pickup(b)
            else:
                do_unstack(b, support[b])

    if plan:
        print("\n".join(plan))


if __name__ == "__main__":
    solve()

from collections import deque


def main():
    blocks = ('a', 'b', 'c', 'd', 'e')

    # State: (on, table, held)
    # on: frozenset of (top, bottom)
    # table: frozenset of blocks directly on the table
    # held: None or the currently held block
    start = (
        frozenset({('c', 'a'), ('e', 'b')}),
        frozenset({'a', 'b', 'd'}),
        None,
    )

    goal = (
        frozenset({('a', 'b'), ('b', 'c'), ('c', 'd'), ('d', 'e')}),
        frozenset({'e'}),
        None,
    )

    def clear_blocks(state):
        on, _, held = state
        covered = {bottom for _, bottom in on}
        clear = set(blocks) - covered
        if held is not None:
            clear.add(held)
        return clear

    def successors(state):
        on, table, held = state
        on_set = set(on)
        table_set = set(table)
        clear = clear_blocks(state)

        if held is None:
            # unstack x y
            for x, y in sorted(on_set):
                if x in clear:
                    new_on = on_set - {(x, y)}
                    yield ('unstack', x, y), (frozenset(new_on), table, x)

            # pickup x
            for b in blocks:
                if b in table_set and b in clear:
                    new_table = table_set - {b}
                    yield ('pickup', b), (on, frozenset(new_table), b)
        else:
            # putdown x
            new_table = table_set | {held}
            yield ('putdown', held), (on, frozenset(new_table), None)

            # stack x y
            for y in blocks:
                if y != held and y in clear:
                    new_on = on_set | {(held, y)}
                    yield ('stack', held, y), (frozenset(new_on), table, None)

    parent = {start: None}
    queue = deque([start])
    found = None

    while queue:
        state = queue.popleft()

        if state == goal:
            found = state
            break

        for action, nxt in successors(state):
            if nxt not in parent:
                parent[nxt] = (state, action)
                if nxt == goal:
                    found = nxt
                    break
                queue.append(nxt)

        if found is not None:
            break

    if found is None:
        print("No plan")
        return

    actions = []
    state = found
    while parent[state] is not None:
        prev, action = parent[state]
        actions.append(action)
        state = prev

    actions.reverse()

    for action in actions:
        print("(" + " ".join(action) + ")")


if __name__ == "__main__":
    main()

import sys


def main():
    blocks = list(range(1, 16))

    # State variables:
    # support[b] is "table", None (held), or the block id directly below b.
    # on_top[b] is None or the block id directly above b.
    support = {b: "table" for b in blocks}
    on_top = {b: None for b in blocks}
    held = None
    plan = []
    error = False

    def name(b):
        return f"block{b}"

    def clear(b):
        return on_top[b] is None

    def do(action, *args):
        nonlocal held, error
        if error:
            return False

        if action == "pickup":
            (x,) = args
            if held is not None or support[x] != "table" or not clear(x):
                error = True
                return False
            held = x
            support[x] = None
            on_top[x] = None

        elif action == "putdown":
            (x,) = args
            if held != x:
                error = True
                return False
            support[x] = "table"
            on_top[x] = None
            held = None

        elif action == "stack":
            (x, y) = args
            if held != x or x == y or support[y] is None or not clear(x) or not clear(y):
                error = True
                return False
            support[x] = y
            on_top[x] = None
            on_top[y] = x
            held = None

        elif action == "unstack":
            (x, y) = args
            if held is not None or support[x] != y or not clear(x):
                error = True
                return False
            held = x
            support[x] = None
            on_top[x] = None
            on_top[y] = None

        else:
            error = True
            return False

        if action in ("pickup", "putdown"):
            plan.append(f"({action} {name(args[0])})")
        else:
            plan.append(f"({action} {name(args[0])} {name(args[1])})")
        return True

    def put_on(x, y):
        support[x] = y
        on_top[x] = None
        if y != "table":
            on_top[y] = x

    # Initial configuration.
    put_on(15, 10)
    put_on(7, 9)
    put_on(3, 4)

    # Flatten all stacks to the table.
    while not error:
        top = None
        for b in blocks:
            if support[b] is not None and support[b] != "table" and on_top[b] is None:
                top = b
                break
        if top is None:
            break
        do("unstack", top, support[top])
        do("putdown", top)

    # Goal configuration as stacks from bottom to top.
    goal_stacks = [
        [15, 8, 13, 14, 1],
        [5],
        [10],
        [7],
        [9],
        [11, 2],
        [4, 6, 12, 3],
    ]

    # Validate that the goal covers every block exactly once.
    seen = []
    for stack in goal_stacks:
        for b in stack:
            if b not in blocks or b in seen:
                error = True
            seen.append(b)

    if len(seen) != len(blocks) or error:
        print("No plan")
        return

    # Build each goal stack from bottom to top.
    for stack in goal_stacks:
        if error:
            break
        for i in range(1, len(stack)):
            b = stack[i]
            y = stack[i - 1]
            do("pickup", b)
            do("stack", b, y)

    # Verify the final state.
    goal_support = {}
    goal_on_top = {b: None for b in blocks}
    for stack in goal_stacks:
        if stack:
            goal_support[stack[0]] = "table"
        for i in range(1, len(stack)):
            goal_support[stack[i]] = stack[i - 1]
            goal_on_top[stack[i - 1]] = stack[i]

    if (
        not error
        and held is None
        and all(support[b] == goal_support[b] for b in blocks)
        and all(on_top[b] == goal_on_top[b] for b in blocks)
    ):
        sys.stdout.write("\n".join(plan))
    else:
        print("No plan")


if __name__ == "__main__":
    main()

from collections import deque

BLOCKS = ("red", "blue", "green", "yellow")
IDX = {b: i for i, b in enumerate(BLOCKS)}
TABLE = "table"


def make_state(pos, holding):
    pos = list(pos)
    if holding is not None:
        pos[IDX[holding]] = None
    return (tuple(pos), holding)


def is_clear(pos, block):
    return all(s != block for s in pos)


def legal_actions(pos, holding):
    actions = []
    if holding is None:
        for block in BLOCKS:
            support = pos[IDX[block]]
            if support == TABLE and is_clear(pos, block):
                actions.append(("pickup", block, None))
            elif support is not None and support != TABLE and is_clear(pos, block):
                actions.append(("unstack", block, support))
    else:
        block = holding
        actions.append(("putdown", block, None))
        for other in BLOCKS:
            if other == block:
                continue
            support = pos[IDX[other]]
            if support is not None and support != TABLE and is_clear(pos, other):
                actions.append(("stack", block, other))
    return actions


def apply_action(pos, holding, action):
    kind, block, other = action
    pos = list(pos)
    i = IDX[block]

    if kind == "pickup":
        pos[i] = None
        holding = block
    elif kind == "unstack":
        pos[i] = None
        holding = block
    elif kind == "putdown":
        pos[i] = TABLE
        holding = None
    elif kind == "stack":
        pos[i] = other
        holding = None

    return tuple(pos), holding


def is_goal(pos, holding):
    return (
        holding is None
        and pos[IDX["red"]] == TABLE
        and pos[IDX["green"]] == "red"
        and pos[IDX["yellow"]] == "green"
        and pos[IDX["blue"]] == "yellow"
    )


def format_action(action):
    kind, block, other = action
    if other is None:
        return f"({kind} {block})"
    return f"({kind} {block} {other})"


def main():
    initial_positions = {
        "red": TABLE,
        "blue": "red",
        "green": TABLE,
        "yellow": "green",
    }
    initial_pos = tuple(initial_positions[b] for b in BLOCKS)
    initial_holding = None

    first_action = None
    for action in legal_actions(initial_pos, initial_holding):
        next_pos, next_holding = apply_action(initial_pos, initial_holding, action)
        if next_holding == "blue":
            first_action = action
            break

    if first_action is None:
        print("No plan")
        return

    start_pos, start_holding = apply_action(initial_pos, initial_holding, first_action)
    start_state = make_state(start_pos, start_holding)

    queue = deque([(start_state, [first_action])])
    visited = {start_state}

    while queue:
        state, path = queue.popleft()
        pos, holding = state

        if is_goal(pos, holding):
            for action in path:
                print(format_action(action))
            return

        for action in legal_actions(pos, holding):
            next_pos, next_holding = apply_action(pos, holding, action)
            next_state = make_state(next_pos, next_holding)
            if next_state not in visited:
                visited.add(next_state)
                queue.append((next_state, path + [action]))

    print("No plan")


if __name__ == "__main__":
    main()

BLOCKS = list(range(1, 16))
TABLE = "table"
HELD = "held"


def is_prime(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True


def stacks_are_partition(stacks):
    seen = []
    for stack in stacks:
        for b in stack:
            if b not in BLOCKS:
                return False
            seen.append(b)
    return sorted(seen) == BLOCKS


def make_state(stacks):
    support = {b: TABLE for b in BLOCKS}
    for stack in stacks:
        for i in range(len(stack) - 1):
            support[stack[i + 1]] = stack[i]
    return {"support": support, "holding": None}


def clear_blocks(state):
    supported = set()
    for b in BLOCKS:
        s = state["support"][b]
        if s != TABLE and s != HELD:
            supported.add(s)
    return set(BLOCKS) - supported


def is_clear(state, b):
    return b in clear_blocks(state)


def apply_action(state, action):
    op = action[0]
    support = dict(state["support"])
    holding = state["holding"]

    if op == "pickup":
        b = action[1]
        assert holding is None
        assert support[b] == TABLE
        assert is_clear(state, b)
        support[b] = HELD
        holding = b

    elif op == "putdown":
        b = action[1]
        assert holding == b
        support[b] = TABLE
        holding = None

    elif op == "unstack":
        b, s = action[1], action[2]
        assert holding is None
        assert support[b] == s
        assert is_clear(state, b)
        support[b] = HELD
        holding = b

    elif op == "stack":
        b, y = action[1], action[2]
        assert holding == b
        assert y in BLOCKS
        assert y != b
        assert is_clear(state, y)
        support[b] = y
        holding = None

    else:
        raise ValueError("Unknown action")

    return {"support": support, "holding": holding}


def flatten_to_table(state, plan):
    while True:
        b = None
        for cand in BLOCKS:
            s = state["support"][cand]
            if s != TABLE and s != HELD and is_clear(state, cand):
                b = cand
                break

        if b is None:
            break

        s = state["support"][b]
        plan.append(("unstack", b, s))
        state = apply_action(state, plan[-1])

        plan.append(("putdown", b))
        state = apply_action(state, plan[-1])

    return state


def build_goal(state, goal_stacks, plan):
    for stack in goal_stacks:
        for i, b in enumerate(stack):
            if i == 0:
                assert state["support"][b] == TABLE
                continue

            assert state["support"][b] == TABLE
            assert is_clear(state, b)

            plan.append(("pickup", b))
            state = apply_action(state, plan[-1])

            plan.append(("stack", b, stack[i - 1]))
            state = apply_action(state, plan[-1])

    return state


def final_matches_goal(state, goal_stacks):
    if state["holding"] is not None:
        return False

    for stack in goal_stacks:
        if not stack:
            return False
        if state["support"][stack[0]] != TABLE:
            return False
        for i in range(1, len(stack)):
            if state["support"][stack[i]] != stack[i - 1]:
                return False

    return True


def satisfies_additional(goal_stacks):
    if len(goal_stacks) != 2:
        return False

    if any(not stack for stack in goal_stacks):
        return False

    prime_stacks = 0
    nonprime_stacks = 0

    for stack in goal_stacks:
        if all(is_prime(b) for b in stack):
            prime_stacks += 1
        if all(not is_prime(b) for b in stack):
            nonprime_stacks += 1

    if prime_stacks != 1 or nonprime_stacks != 1:
        return False

    for stack in goal_stacks:
        if stack != sorted(stack):
            return False

    return True


def main():
    initial_stacks = [
        [11, 3],
        [10],
        [1],
        [8],
        [12],
        [15, 5, 6, 14],
        [9, 4],
        [7, 13],
        [2],
    ]

    goal_stacks = [
        [8, 12, 13, 4, 2, 7, 15, 14],
        [3, 6, 11, 10, 5, 9],
        [1],
    ]

    if not stacks_are_partition(initial_stacks) or not stacks_are_partition(goal_stacks):
        print("No plan")
        return

    if not satisfies_additional(goal_stacks):
        print("No plan")
        return

    state = make_state(initial_stacks)
    plan = []

    state = flatten_to_table(state, plan)
    state = build_goal(state, goal_stacks, plan)

    if not final_matches_goal(state, goal_stacks):
        print("No plan")
        return

    for action in plan:
        if action[0] in ("unstack", "stack"):
            print(f"({action[0]} block{action[1]} block{action[2]})")
        else:
            print(f"({action[0]} block{action[1]})")


if __name__ == "__main__":
    main()

def solve():
    blocks = [chr(ord('a') + i) for i in range(12)]
    goal = blocks[:]  # bottom to top: a, b, ..., l

    on = {
        'a': 'table',
        'b': 'a',
        'c': None,
        'd': 'table',
        'e': 'd',
        'f': 'e',
        'g': 'table',
        'h': 'table',
        'i': 'table',
        'j': 'i',
        'k': 'j',
        'l': 'k',
    }
    holding = 'c'

    plan = []
    error = False

    def is_clear(b):
        return not any(on[z] == b for z in on)

    def do_pickup(b):
        nonlocal holding, error
        if error:
            return
        if holding is not None or on[b] != 'table' or not is_clear(b):
            error = True
            return
        plan.append(f"(pickup {b})")
        holding = b
        on[b] = None

    def do_unstack(x, y):
        nonlocal holding, error
        if error:
            return
        if holding is not None or on[x] != y or not is_clear(x):
            error = True
            return
        plan.append(f"(unstack {x} {y})")
        holding = x
        on[x] = None

    def do_putdown(x):
        nonlocal holding, error
        if error:
            return
        if holding != x:
            error = True
            return
        plan.append(f"(putdown {x})")
        holding = None
        on[x] = 'table'

    def do_stack(x, y):
        nonlocal holding, error
        if error:
            return
        if holding != x or on[y] is None or not is_clear(y):
            error = True
            return
        plan.append(f"(stack {x} {y})")
        holding = None
        on[x] = y

    built_top = None
    if on[goal[0]] == 'table':
        built_top = goal[0]
        idx = 0
        while idx + 1 < len(goal):
            nxt = goal[idx + 1]
            if on[nxt] == goal[idx]:
                built_top = nxt
                idx += 1
            else:
                break

    if built_top is None:
        error = True
    else:
        while built_top != goal[-1]:
            idx = goal.index(built_top)
            x = goal[idx + 1]

            segment = [x]
            if on[x] is not None:
                i = idx
                while i + 1 < len(goal):
                    nxt = goal[i + 1]
                    if on[nxt] == segment[-1]:
                        segment.append(nxt)
                        i += 1
                    else:
                        break

            for pos in range(len(segment) - 1, 0, -1):
                upper = segment[pos]
                lower = segment[pos - 1]
                do_unstack(upper, lower)
                do_putdown(upper)

            if holding == x:
                pass
            elif on[x] == 'table':
                do_pickup(x)
            else:
                support = on[x]
                if support is None:
                    error = True
                else:
                    do_unstack(x, support)

            do_stack(x, built_top)

            for pos in range(1, len(segment)):
                upper = segment[pos]
                lower = segment[pos - 1]
                do_pickup(upper)
                do_stack(upper, lower)

            built_top = segment[-1]

    if not error and holding is None:
        if on[goal[0]] != 'table':
            error = True
        for i in range(1, len(goal)):
            if on[goal[i]] != goal[i - 1]:
                error = True
                break

    if error:
        print("No plan")
    else:
        print("\n".join(plan))

if __name__ == "__main__":
    solve()

import sys
from heapq import heappush, heappop

N = 13
TABLE = -1
HELD = -2
EMPTY = -3

names = [f"block{i}" for i in range(1, N + 1)]
idx = {name: i for i, name in enumerate(names)}


def bnum(n):
    return idx[f"block{n}"]


def initial_state():
    s = [TABLE] * N
    for n in (10, 12, 7, 13, 3, 4, 9, 6):
        s[bnum(n)] = TABLE
    for x, y in ((11, 7), (2, 11), (5, 13), (8, 4), (1, 6)):
        s[bnum(x)] = bnum(y)
    return tuple(s), EMPTY


def goal_state():
    s = [TABLE] * N
    s[bnum(13)] = bnum(6)
    s[bnum(8)] = bnum(2)
    s[bnum(7)] = bnum(8)
    s[bnum(1)] = bnum(7)
    s[bnum(9)] = bnum(5)
    s[bnum(3)] = bnum(12)
    s[bnum(11)] = bnum(3)
    s[bnum(4)] = bnum(11)
    return tuple(s), EMPTY


INITIAL, INIT_HELD = initial_state()
GOAL, GOAL_HELD = goal_state()


def clear(s, x):
    for z in range(N):
        if z != x and s[z] == x:
            return False
    return True


def stack_count(s):
    return sum(1 for v in s if v == TABLE)


def constraint_ok(s, held, depth):
    if depth == 0:
        return True
    return stack_count(s) == 5


def heuristic(s, held):
    return sum(1 for i in range(N) if s[i] != GOAL[i])


def successors(s, held, depth):
    if held == EMPTY:
        for x in range(N):
            if s[x] == TABLE and clear(s, x):
                ns = list(s)
                ns[x] = HELD
                ns_t = tuple(ns)
                if constraint_ok(ns_t, x, depth + 1):
                    yield ("pickup", x), ns_t, x

    if held != EMPTY and clear(s, held):
        ns = list(s)
        ns[held] = TABLE
        ns_t = tuple(ns)
        if constraint_ok(ns_t, EMPTY, depth + 1):
            yield ("putdown", held), ns_t, EMPTY

    if held == EMPTY:
        for x in range(N):
            y = s[x]
            if y != TABLE and y != HELD and clear(s, x):
                ns = list(s)
                ns[x] = HELD
                ns_t = tuple(ns)
                if constraint_ok(ns_t, x, depth + 1):
                    yield ("unstack", x, y), ns_t, x

    if held != EMPTY and clear(s, held):
        x = held
        for y in range(N):
            if y == x or s[y] == HELD:
                continue
            if not clear(s, y):
                continue
            ns = list(s)
            ns[x] = y
            ns_t = tuple(ns)
            if constraint_ok(ns_t, EMPTY, depth + 1):
                yield ("stack", x, y), ns_t, EMPTY


def find_plan():
    start = (INITIAL, INIT_HELD)
    if INITIAL == GOAL and INIT_HELD == GOAL_HELD:
        return []

    g_score = {start: 0}
    parent = {start: None}
    closed = set()
    counter = 0
    heap = [(heuristic(INITIAL, INIT_HELD), 0, counter, INITIAL, INIT_HELD)]

    while heap:
        _, g, _, s, held = heappop(heap)
        node = (s, held)

        if g != g_score.get(node):
            continue
        if node in closed:
            continue

        closed.add(node)

        if s == GOAL and held == GOAL_HELD:
            actions = []
            cur = node
            while parent[cur] is not None:
                prev_s, prev_h, action = parent[cur]
                actions.append(action)
                cur = (prev_s, prev_h)
            actions.reverse()
            return actions

        for action, ns, nh in successors(s, held, g):
            node2 = (ns, nh)
            if node2 in closed:
                continue
            ng = g + 1
            if node2 not in g_score or ng < g_score[node2]:
                g_score[node2] = ng
                parent[node2] = (s, held, action)
                counter += 1
                heappush(heap, (ng + heuristic(ns, nh), ng, counter, ns, nh))

    return None


def main():
    plan = find_plan()
    if plan is None:
        print("No plan")
    else:
        for action in plan:
            if len(action) == 2:
                a, x = action
                print(f"({a} {names[x]})")
            else:
                a, x, y = action
                print(f"({a} {names[x]} {names[y]})")


if __name__ == "__main__":
    main()

from collections import deque

blocks = [f"block{i}" for i in range(1, 12)]
n = len(blocks)
index = {b: i for i, b in enumerate(blocks)}

TABLE = -1
