from collections import deque

BLOCKS = ("block1", "block2", "block3", "block4")
INDEX = {b: i for i, b in enumerate(BLOCKS)}

INITIAL_TABLE = ("block3", "block4", "block1", "block2")
GOAL_TABLE = ("block4", "block2", "block1", "block3")


def initial_state():
    below = ["table"] * len(BLOCKS)
    above = [None] * len(BLOCKS)
    return (INITIAL_TABLE, tuple(below), tuple(above), None)


def is_goal(state):
    table, below, above, held = state
    return (
        table == GOAL_TABLE
        and held is None
        and all(s == "table" for s in below)
        and all(a is None for a in above)
    )


def successors(state):
    table, below, above, held = state
    table = list(table)
    below = list(below)
    above = list(above)

    if held is None:
        for b in BLOCKS:
            i = INDEX[b]
            if below[i] == "table" and above[i] is None:
                new_table = table.copy()
                new_below = below.copy()
                new_above = above.copy()
                new_table.remove(b)
                new_below[i] = "arm"
                new_state = (tuple(new_table), tuple(new_below), tuple(new_above), b)
                yield (("pickup", b), new_state)

    if held is not None:
        i = INDEX[held]

        if above[i] is None:
            new_table = table + [held]
            new_below = below.copy()
            new_above = above.copy()
            new_below[i] = "table"
            new_state = (tuple(new_table), tuple(new_below), tuple(new_above), None)
            yield (("putdown", held), new_state)

        if above[i] is None:
            for y in BLOCKS:
                if y == held:
                    continue
                j = INDEX[y]
                if below[j] != "arm" and above[j] is None:
                    new_below = below.copy()
                    new_above = above.copy()
                    new_below[i] = y
                    new_above[j] = held
                    new_state = (tuple(table), tuple(new_below), tuple(new_above), None)
                    yield (("stack", held, y), new_state)

    if held is None:
        for x in BLOCKS:
            i = INDEX[x]
            if above[i] is None and below[i] not in ("table", "arm"):
                y = below[i]
                j = INDEX[y]
                new_below = below.copy()
                new_above = above.copy()
                new_below[i] = "arm"
                new_above[j] = None
                new_state = (tuple(table), tuple(new_below), tuple(new_above), x)
                yield (("unstack", x, y), new_state)


def format_action(action):
    if action[0] in ("pickup", "putdown"):
        return f"({action[0]} {action[1]})"
    return f"({action[0]} {action[1]} {action[2]})"


def solve():
    start = initial_state()
    if is_goal(start):
        return

    queue = deque([(start, [])])
    seen = {start}

    while queue:
        state, path = queue.popleft()

        for action, new_state in successors(state):
            if new_state in seen:
                continue

            new_path = path + [action]

            if is_goal(new_state):
                for a in new_path:
                    print(format_action(a))
                return

            seen.add(new_state)
            queue.append((new_state, new_path))

    print("No plan")


if __name__ == "__main__":
    solve()

def main():
    # Variables:
    #   support[b] = None (table), another block name, or "arm" if held.
    #   held = None or a block name.
    #
    # Constraints:
    #   every block has exactly one support; a block can be on at most one block;
    #   the arm holds at most one block; actions are legal only under Blocksworld
    #   preconditions.
    #
    # Goal:
    #   held is None, support["block2"] == "block5", and every other block is
    #   directly on the table.
    blocks = [f"block{i}" for i in range(1, 16)]
    initial_stacks = [
        ["block6", "block11", "block4", "block12", "block7", "block5", "block14"],
        ["block3", "block1", "block13"],
        ["block2", "block9"],
        ["block8", "block15", "block10"],
    ]

    support = {}
    for stack in initial_stacks:
        for i, b in enumerate(stack):
            support[b] = None if i == 0 else stack[i - 1]

    held = None
    plan = []

    def children(b):
        return [x for x in blocks if support[x] == b]

    def is_clear(b):
        return not children(b)

    def do_pickup(b):
        nonlocal held
        if held is not None or support[b] is not None or not is_clear(b):
            return False
        plan.append(f"(pickup {b})")
        support[b] = "arm"
        held = b
        return True

    def do_putdown(b):
        nonlocal held
        if held is None or held != b:
            return False
        plan.append(f"(putdown {b})")
        support[b] = None
        held = None
        return True

    def do_unstack(b, c):
        nonlocal held
        if held is not None or support[b] != c or not is_clear(b):
            return False
        plan.append(f"(unstack {b} {c})")
        support[b] = "arm"
        held = b
        return True

    def do_stack(b, c):
        nonlocal held
        if held is None or held != b or c == b or support[c] == "arm" or not is_clear(c):
            return False
        plan.append(f"(stack {b} {c})")
        support[b] = c
        held = None
        return True

    def make_on_table(b):
        # Make b directly on the table and clear.
        if support[b] == "arm":
            return False

        if support[b] is not None:
            for child in list(children(b)):
                if not make_on_table(child):
                    return False
            if not do_unstack(b, support[b]):
                return False
            if not do_putdown(b):
                return False

        for child in list(children(b)):
            if not make_on_table(child):
                return False

        return True

    ok = True

    # First flatten all stacks to the table.  This satisfies every
    # "on the table" goal predicate temporarily.
    for b in blocks:
        if not make_on_table(b):
            ok = False
            break

    # Then realize the special goal relation: block2 on block5.
    if ok:
        if not make_on_table("block5") or not make_on_table("block2"):
            ok = False
        else:
            if not do_pickup("block2"):
                ok = False
            elif not do_stack("block2", "block5"):
                ok = False

    expected = {b: None for b in blocks}
    expected["block2"] = "block5"

    if ok and held is None and support == expected:
        print("\n".join(plan))
    else:
        print("No plan")


if __name__ == "__main__":
    main()

from collections import deque

BLOCKS = ("block1", "block2", "block3", "block4")
INDEX = {b: i for i, b in enumerate(BLOCKS)}
WEIGHT = {b: int(b[5:]) for b in BLOCKS}

INITIAL_TABLE = ("block3", "block4", "block1", "block2")
GOAL_TABLE = ("block4", "block2", "block1", "block3")


def is_clear(state, block):
    _, _, on = state
    return all(on[i] != block for i in range(len(BLOCKS)))


def is_goal(state):
    table, arm, on = state
    return arm is None and table == GOAL_TABLE and all(o is None for o in on)


def successors(state):
    table, arm, on = state

    if arm is None:
        for x in BLOCKS:
            if x in table and is_clear(state, x):
                new_table = tuple(b for b in table if b != x)
                yield (new_table, x, on), ("pickup", x)

        for x in BLOCKS:
            y = on[INDEX[x]]
            if y is not None and is_clear(state, x):
                new_on = list(on)
                new_on[INDEX[x]] = None
                yield (table, x, tuple(new_on)), ("unstack", x, y)

    else:
        x = arm

        new_table = table + (x,)
        yield (new_table, None, on), ("putdown", x)

        for y in BLOCKS:
            if y == x:
                continue
            if is_clear(state, y) and WEIGHT[x] <= WEIGHT[y]:
                new_on = list(on)
                new_on[INDEX[x]] = y
                yield (table, None, tuple(new_on)), ("stack", x, y)


def main():
    start = (INITIAL_TABLE, None, tuple(None for _ in BLOCKS))

    if is_goal(start):
        return

    parent = {start: None}
    queue = deque([start])
    found = False

    while queue:
        state = queue.popleft()

        if is_goal(state):
            found = True
            break

        for next_state, action in successors(state):
            if next_state not in parent:
                parent[next_state] = (state, action)
                queue.append(next_state)

    if not found:
        print("No plan")
        return

    actions = []
    while parent[state] is not None:
        prev_state, action = parent[state]
        actions.append(action)
        state = prev_state

    for action in reversed(actions):
        print(f"({action[0]} {' '.join(action[1:])})")


if __name__ == "__main__":
    main()

# Variables:
#   loc[b] = None (on table), "arm", or another block directly below b
#   holding = None or a block
#
# Constraints:
#   - A block can be picked up only if it is on the table, clear, and arm is empty.
#   - A block can be unstacked only if it is clear and arm is empty.
#   - A block can be put down only if it is held.
#   - A block can be stacked on another only if the target is clear.
#   - Block 2 is fragile: no block may be stacked on block2.
#   - Goal: every block is on the table and the arm is empty.

from collections import deque

BLOCKS = tuple(f"block{i}" for i in range(1, 8))
INDEX = {b: i for i, b in enumerate(BLOCKS)}
FRAGILE = "block2"

initial_loc = {b: None for b in BLOCKS}
initial_loc["block3"] = "block5"
initial_loc["block4"] = "block2"

INITIAL = (tuple(initial_loc[b] for b in BLOCKS), None)


def is_goal(state):
    locs, holding = state
    return holding is None and all(loc is None for loc in locs)


def is_clear(locs, block):
    return all(loc != block for loc in locs)


def successors(state):
    locs, holding = state
    loc = list(locs)

    if holding is None:
        # unstack X Y: lift X off Y
        for i, b in enumerate(BLOCKS):
            under = loc[i]
            if under is not None and under != "arm" and is_clear(loc, b):
                new_loc = loc.copy()
                new_loc[i] = "arm"
                yield (tuple(new_loc), b), f"unstack {b} {under}"

        # pickup X: pick up X from table
        for i, b in enumerate(BLOCKS):
            if loc[i] is None and is_clear(loc, b):
                new_loc = loc.copy()
                new_loc[i] = "arm"
                yield (tuple(new_loc), b), f"pickup {b}"

    if holding is not None:
        i = INDEX[holding]

        if loc[i] == "arm":
            # putdown X: put held X on table
            new_loc = loc.copy()
            new_loc[i] = None
            yield (tuple(new_loc), None), f"putdown {holding}"

            # stack X Y: put held X on Y
            for j, y in enumerate(BLOCKS):
                if y == holding:
                    continue
                if y == FRAGILE:
                    continue
                if loc[j] == "arm":
                    continue
                if is_clear(loc, y):
                    new_loc = loc.copy()
                    new_loc[i] = y
                    yield (tuple(new_loc), None), f"stack {holding} {y}"


def solve():
    if is_goal(INITIAL):
        return []

    queue = deque([INITIAL])
    parent = {INITIAL: (None, None)}

    while queue:
        state = queue.popleft()

        for nxt, action in successors(state):
            if nxt in parent:
                continue

            parent[nxt] = (state, action)

            if is_goal(nxt):
                plan = []
                cur = nxt
                while parent[cur][0] is not None:
                    plan.append(parent[cur][1])
                    cur = parent[cur][0]
                plan.reverse()
                return plan

            queue.append(nxt)

    return None


plan = solve()

if plan is None:
    print("No plan")
else:
    for action in plan:
        print(f"({action})")

import sys
from collections import deque


def main():
    # Formalization:
    # - Blocks: block1 ... block15
    # - Initial state: all blocks on table, arm empty
    # - Goal state: each block has a required support (table or another block)
    # - Actions: pickup, putdown, stack, unstack
    # - Extra constraint: every action moving block1 must be followed later by an action moving block2
    blocks = [f"block{i}" for i in range(1, 16)]

    # Goal stacks, bottom to top
    goal_stacks = [
        ["block15", "block8", "block2"],
        ["block6", "block3", "block9"],
        ["block11", "block7", "block13", "block1", "block5", "block14"],
        ["block10", "block12", "block4"],
    ]

    # Required final support for each block: None means on table
    support = {}
    for stack in goal_stacks:
        for i, b in enumerate(stack):
            support[b] = None if i == 0 else stack[i - 1]

    if set(support) != set(blocks):
        print("No plan")
        return

    # Blocks that must be moved from the table onto another block
    moved = [b for b in blocks if support[b] is not None]

    # Dependency graph over moved blocks:
    # A block can be stacked only after its support block has been placed.
    deps = {b: set() for b in moved}
    dependents = {b: set() for b in moved}

    for b in moved:
        s = support[b]
        if s is not None and s in deps:
            deps[b].add(s)
            dependents[s].add(b)

    # Additional constraint:
    # If block1 is moved, block2 must be moved after it.
    b1, b2 = "block1", "block2"
    if b1 in deps and b2 in deps:
        deps[b2].add(b1)
        dependents[b1].add(b2)

    def block_num(name):
        return int(name[5:])

    # Topological sort to get a valid move order
    indeg = {b: len(deps[b]) for b in moved}
    q = deque(sorted([b for b in moved if indeg[b] == 0], key=block_num))
    order = []

    while q:
        b = q.popleft()
        order.append(b)
        for d in sorted(dependents[b], key=block_num):
            indeg[d] -= 1
            if indeg[d] == 0:
                q.append(d)

    if len(order) != len(moved):
        print("No plan")
        return

    # Build the plan from the topological order
    plan = []
    for b in order:
        plan.append(f"(pickup {b})")
        plan.append(f"(stack {b} {support[b]})")

    def is_clear(on, b):
        return not any(s == b for s in on.values())

    def validate_plan(plan):
        on_table = set(blocks)
        on = {}  # block -> block it is on
        held = None

        for action in plan:
            parts = action.strip().strip("()").split()
            if not parts:
                return False

            act = parts[0]

            if act == "pickup":
                if len(parts) != 2:
                    return False
                b = parts[1]
                if held is not None or b not in on_table or not is_clear(on, b):
                    return False
                on_table.remove(b)
                held = b

            elif act == "putdown":
                if len(parts) != 2:
                    return False
                b = parts[1]
                if held != b:
                    return False
                on_table.add(b)
                held = None

            elif act == "unstack":
                if len(parts) != 3:
                    return False
                b, y = parts[1], parts[2]
                if held is not None or b not in on or on[b] != y or not is_clear(on, b):
                    return False
                del on[b]
                held = b

            elif act == "stack":
                if len(parts) != 3:
                    return False
                b, y = parts[1], parts[2]
                if held != b or y == b:
                    return False
                if y not in on_table and y not in on:
                    return False
                if not is_clear(on, y):
                    return False
                on[b] = y
                held = None

            else:
                return False

        if held is not None:
            return False

        if on_table.union(on.keys()) != set(blocks):
            return False

        for b in blocks:
            if support[b] is None:
                if b not in on_table:
                    return False
            else:
                if on.get(b) != support[b]:
                    return False

        return True

    def constraint_ok(plan):
        def moved_block(action, target):
            parts = action.strip().strip("()").split()
            return len(parts) >= 2 and parts[1] == target

        next_b2 = None
        for i in range(len(plan) - 1, -1, -1):
            if moved_block(plan[i], b2):
                next_b2 = i
            elif moved_block(plan[i], b1):
                if next_b2 is None:
                    return False
        return True

    if not validate_plan(plan) or not constraint_ok(plan):
        print("No plan")
        return

    print("\n".join(plan))


if __name__ == "__main__":
    main()

import sys


def main():
    blocks = list(range(1, 13))

    initial_stacks = [
        [9, 2, 1, 6],
        [7, 5],
        [10, 4, 3, 12, 8, 11],
    ]

    goal_on = {11: 5, 1: 4}
    expected = {b: goal_on.get(b, "table") for b in blocks}

    def initial_state():
        support = {}
        for stack in initial_stacks:
            support[stack[0]] = "table"
            for i in range(1, len(stack)):
                support[stack[i]] = stack[i - 1]
        return support, None

    def is_clear(support, b):
        if support[b] == "held":
            return True
        for x in support:
            if support[x] == b:
                return False
        return True

    def apply_action(support, holding, action):
        support = dict(support)
        kind = action[0]

        if kind == "pickup":
            b = action[1]
            support[b] = "held"
            holding = b
        elif kind == "putdown":
            b = action[1]
            support[b] = "table"
            holding = None
        elif kind == "unstack":
            b = action[1]
            support[b] = "held"
            holding = b
        elif kind == "stack":
            b, c = action[1], action[2]
            support[b] = c
            holding = None

        return support, holding

    def valid_action(support, holding, action):
        kind = action[0]

        if kind == "pickup":
            b = action[1]
            return holding is None and support[b] == "table" and is_clear(support, b)

        if kind == "putdown":
            b = action[1]
            return holding == b

        if kind == "unstack":
            b, c = action[1], action[2]
            return holding is None and support[b] == c and is_clear(support, b)

        if kind == "stack":
            b, c = action[1], action[2]
            return holding == b and b != c and support[c] != "held" and is_clear(support, c)

        return False

    def is_goal(support, holding):
        if holding is not None:
            return False
        for b in blocks:
            if support[b] != expected[b]:
                return False
        return True

    support, holding = initial_state()
    plan = []

    while True:
        top = None
        for b in blocks:
            if support[b] not in ("table", "held") and is_clear(support, b):
                top = b
                break

        if top is None:
            break

        a1 = ("unstack", top, support[top])
        if not valid_action(support, holding, a1):
            plan = None
            break
        support, holding = apply_action(support, holding, a1)
        plan.append(a1)

        a2 = ("putdown", top)
        if not valid_action(support, holding, a2):
            plan = None
            break
        support, holding = apply_action(support, holding, a2)
        plan.append(a2)

    if plan is not None:
        for b, c in goal_on.items():
            if support[b] != "table" or not is_clear(support, b):
                plan = None
                break
            if support[c] == "held" or not is_clear(support, c):
                plan = None
                break

            a1 = ("pickup", b)
            if not valid_action(support, holding, a1):
                plan = None
                break
            support, holding = apply_action(support, holding, a1)
            plan.append(a1)

            a2 = ("stack", b, c)
            if not valid_action(support, holding, a2):
                plan = None
                break
            support, holding = apply_action(support, holding, a2)
            plan.append(a2)

    if plan is None or not is_goal(support, holding):
        print("No plan")
        return

    lines = []
    for action in plan:
        if len(action) == 2:
            lines.append(f"({action[0]} block{action[1]})")
        else:
            lines.append(f"({action[0]} block{action[1]} block{action[2]})")

    print("\n".join(lines))


if __name__ == "__main__":
    main()
